import React from "react";
import { Form, FormInstance } from "antd";
import { CalendarOutlined } from "@ant-design/icons";
import moment from "moment";
import { FormSection } from "../../common/ui";
import SchedulePicker from "./SchedulePicker";
import {
  RecurringSchedule,
  formatTime,
  listOccurrences,
  summarizeSchedule,
  validateSchedule,
} from "./recurrence";

export const SCHEDULE_SECTION_ID = "section-schedule";
const PREVIEW_DATES = 6;

const scheduleRules = [
  {
    validator: (_: any, value: RecurringSchedule) => {
      const error = validateSchedule(value);
      return error ? Promise.reject(new Error(error)) : Promise.resolve();
    },
  },
];

/** Live preview of what the schedule will produce. */
export const SchedulePreview = ({ form }: { form: FormInstance }) => {
  const schedule: RecurringSchedule = Form.useWatch("schedule", form);
  const pickupTime = formatTime(Form.useWatch("pickupTime", form));
  const returnTime = formatTime(Form.useWatch("returnPickupTime", form));
  const serviceType = Form.useWatch("serviceType", form);

  if (validateSchedule(schedule)) return null;

  const today = moment().startOf("day");
  const { dates } = listOccurrences(schedule);
  const upcoming = dates.filter((d) => !d.isBefore(today, "day"));
  const shown = upcoming.slice(0, PREVIEW_DATES);
  const twoLegs = serviceType === "C/R" || serviceType === "W/R";

  return (
    <div className="mx-recurring-preview">
      <div className="mx-recurring-preview__title">
        <CalendarOutlined /> {summarizeSchedule(schedule, pickupTime)}
      </div>
      <div className="mx-recurring-preview__meta">
        {!pickupTime && "No pickup time set yet (Trip section). "}
        {twoLegs &&
          `Each date includes the return trip${returnTime ? ` at ${returnTime}` : ""}. `}
        {upcoming.length < dates.length &&
          `${dates.length - upcoming.length} of ${dates.length} dates are already in the past.`}
      </div>
      {shown.length > 0 && (
        <div className="mx-recurring-preview__dates">
          <span>Next:</span>
          {shown.map((d) => (
            <span key={d.format("YYYY-MM-DD")} className="mx-recurring-preview__date">
              {d.format("ddd, MMM D")}
            </span>
          ))}
          {upcoming.length > shown.length && <span>+{upcoming.length - shown.length} more</span>}
        </div>
      )}
    </div>
  );
};

const ScheduleSection = ({
  form,
  index,
  done,
}: {
  form: FormInstance;
  index: number;
  done: boolean;
}) => (
  <FormSection
    id={SCHEDULE_SECTION_ID}
    index={index}
    done={done}
    title="Repeat schedule"
    description="Which days this booking becomes a ride. The pickup time comes from the Trip section."
  >
    <Form.Item name="schedule" rules={scheduleRules}>
      <SchedulePicker />
    </Form.Item>
    <SchedulePreview form={form} />
  </FormSection>
);

export default ScheduleSection;
