import React from "react";
import { SET_SUBMITTED, CANCEL_RIDE } from "reducers/reducer";
import { pushNotification } from "utils/notifications";
import ConfirmationModal from "../ConfirmationModal";
import RideFilterModal from "../RideFilterModal";
import ShareDispatchUrlModal from "../ShareDispatchUrlModal";
import { useDispatchPanel } from "../context";

// The floating modals: cancel confirmation, phone search, share URL and the
// incoming-call confirmation prompt.
const OverlayModals: React.FC = () => {
  const {
    isCancelModalVisible,
    setIsCancelModalVisible,
    ridePageId,
    encrypted_token,
    projects,
    dispatch,
    clearForm,
    isPhoneFilterModalVisible,
    setIsPhoneFilterModalVisible,
    socket,
    isShareModalVisible,
    setIsShareModalVisible,
    isConfirmationModalVisible,
    setIsConfirmationModalVisible,
    getPassenger,
  } = useDispatchPanel();

  return (
    <React.Fragment>
      {isCancelModalVisible && (
        <ConfirmationModal
          onClose={() => {
            setIsCancelModalVisible(undefined);
          }}
          handleConfirm={() => {
            dispatch(
              CANCEL_RIDE({
                requestData: {
                  pageId: ridePageId,
                  userId: encrypted_token?.userId,
                  cudbServiceId: projects?.userServiceId,
                  dispatcher: true,
                },
                callback: (response: any) => {
                  console.log("response", response);
                  pushNotification(
                    "Ride cancelled successfully",
                    "success",
                    "TOP_CENTER",
                    1000
                  );
                  dispatch({ type: SET_SUBMITTED, payload: false });
                  clearForm();
                },
              })
            );
            setIsCancelModalVisible(undefined);
          }}
          message={`Are you sure you want to cancel ride?`}
        />
      )}

      {isPhoneFilterModalVisible?.phone && (
        <RideFilterModal
          socket={socket}
          phone={isPhoneFilterModalVisible?.phone}
          onClose={() => {
            setIsPhoneFilterModalVisible(undefined);
          }}
        />
      )}

      {isShareModalVisible && (
        <ShareDispatchUrlModal
          onClose={() => {
            setIsShareModalVisible(false);
          }}
          socket={socket}
        />
      )}

      {isConfirmationModalVisible?.reservation && (
        <ConfirmationModal
          onClose={() => {
            setIsConfirmationModalVisible(undefined);
          }}
          handleConfirm={() => {
            getPassenger(
              undefined,
              isConfirmationModalVisible?.reservation?.phoneNumber
            );
            setIsConfirmationModalVisible(undefined);
          }}
          message={`Incoming call: ${isConfirmationModalVisible?.reservation?.phoneNumber}`}
        />
      )}
    </React.Fragment>
  );
};

export default OverlayModals;
