class UniqueQueue<T> {
  private queue: T[] = [];

  enqueue(item: T): void {
    if (!this.queue.includes(item)) {
      this.queue.push(item);
    }
  }

  dequeue(): T | undefined {
    return this.queue.shift();
  }

  isAtTop(item: T): boolean {
    return this.queue.length > 0 && this.queue[0] === item;
  }

  addOrPop(item: T): void {
    if (this.isAtTop(item)) {
      this.dequeue();
    } else {
      this.enqueue(item);
    }
  }

  clear(): void {
    this.queue = [];
  }

  getQueue(): T[] {
    return this.queue;
  }
}

