import React from "react";
import { Badge, Button, Segmented, Tooltip } from "antd";
import {
  EnvironmentOutlined,
  FilterOutlined,
  ScheduleOutlined,
  SortAscendingOutlined,
  SyncOutlined,
  UndoOutlined,
  UnorderedListOutlined,
} from "@ant-design/icons";
import "./filters/filters.scss";

export type DashboardView = "table" | "board";

interface Props {
  view: DashboardView;
  onViewChange: (view: DashboardView) => void;
  loading: boolean;
  onToggleMap?: () => void;
  mapVisible?: boolean;
  onToggleFilters: () => void;
  filtersOpen?: boolean;
  activeFilterCount?: number;
  onRefresh: () => void;
  onReset: () => void;
  onSort: () => void;
  sortCount?: number;
  columnSettings: React.ReactNode;
}

const Toolbar = ({
  view,
  onViewChange,
  loading,
  onToggleMap,
  mapVisible,
  onToggleFilters,
  filtersOpen,
  activeFilterCount = 0,
  onRefresh,
  onReset,
  onSort,
  sortCount = 0,
  columnSettings,
}: Props) => (
  <div className="mx-dash-toolbar">
    <Segmented
      value={view}
      onChange={(v) => onViewChange(v as DashboardView)}
      options={[
        { value: "table", label: "Table", icon: <UnorderedListOutlined /> },
        { value: "board", label: "Driver board", icon: <ScheduleOutlined /> },
      ]}
    />

    <div className="mx-dash-toolbar__actions">
      <Badge count={activeFilterCount} size="small" offset={[-4, 4]} color="#508afa">
        <Button
          className={`mx-dash-toolbar__btn ${filtersOpen ? "mx-dash-toolbar__btn--on" : ""}`}
          icon={<FilterOutlined />}
          onClick={onToggleFilters}
        >
          Filters
        </Button>
      </Badge>
      {onToggleMap && (
        <Button
          className={`mx-dash-toolbar__btn ${mapVisible ? "mx-dash-toolbar__btn--on" : ""}`}
          icon={<EnvironmentOutlined />}
          onClick={onToggleMap}
        >
          Map
        </Button>
      )}
      <span className="mx-dash-toolbar__divider" />
      <Tooltip title="Refresh">
        <Button
          className="mx-dash-toolbar__btn"
          icon={<SyncOutlined spin={loading} />}
          onClick={onRefresh}
          aria-label="Refresh"
        />
      </Tooltip>
      <Tooltip title="Reset filters">
        <Button
          className="mx-dash-toolbar__btn"
          icon={<UndoOutlined />}
          onClick={onReset}
          aria-label="Reset filters"
        />
      </Tooltip>
      <Tooltip title={sortCount ? `Sorted by ${sortCount} column${sortCount > 1 ? "s" : ""}` : "Sort"}>
        <Badge dot={sortCount > 0} offset={[-4, 4]} color="#508afa">
          <Button
            className="mx-dash-toolbar__btn"
            icon={<SortAscendingOutlined />}
            onClick={onSort}
            aria-label="Sort"
          />
        </Badge>
      </Tooltip>
      <Tooltip title="Show/hide columns">{columnSettings}</Tooltip>
    </div>
  </div>
);

export default Toolbar;
