/**
 * Builds the scheduler-service payload for a recurring booking.
 *
 * The scheduler stores `data` and, on every cron tick, publishes it to
 * createRecurringEventPage, which creates the ride pages for that day and
 * fills in the `<pickupDate>` placeholders. The shapes below are what that
 * service reads, so keep them as they are.
 */
import _ from "lodash";
import moment from "moment-timezone";
import { formatObject, generateUUID } from "utils/appUtil";
import {
  buildNotes,
  cleanObject,
  distributeSecondaryResponders,
  getEquipmentType,
  getStairchairPickupTimes,
} from "../../DispatchPanel/dispatchPipeline";

export const RECURRING_EVENT_TOPIC = `${process.env.REACT_APP_ECO_SYSTEM}/service/scheduler-service/service/dps/createRecurringEventPage`;

/** Far-future end for the scheduler entry; the booking's own dates bound it. */
export const SCHEDULE_TO = 4920566400000;

export interface RecurringBuildContext {
  userId: string;
  connectionId: string;
  accounts: any[];
  projects: any;
  /** Editing keeps the stored `scheduleUdid`; new schedules get a fresh one. */
  existing?: { scheduleUdid?: string };
}

const DIAGNOSIS_OPTIONS = [
  { label: "Short-term memory loss", value: "shortTermMemoryLoss" },
  { label: "Cognitive decline", value: "cognitiveDecline" },
  {
    label: "MRSA (colonized, no wounds). Universal precautions and vehicle decon req'd.",
    value: "mrsa",
  },
  { label: "Contact Precautions", value: "contactPrecautions" },
  { label: "Airborne Precautions", value: "airbornePrecautions" },
  { label: "Droplet Precautions", value: "dropletPrecautions" },
  {
    label:
      "COVID+ Precautions, Universal precautions, PPE and N-95 mask required, Decon vehicle after transfer",
    value: "covidPrecautions",
  },
  { label: "Other", value: "other" },
];

const capitalizeWords = (str = "") =>
  str.toLowerCase().replace(/\b\w/g, (char) => char.toUpperCase());

const toResponder = (responder) => ({
  id: responder?.id,
  beamId: responder?.beamId,
  permission: "write",
});

const removeCountry = (address) => {
  if (!address) return address;
  const parts = address.split(",");
  if (parts.length > 1) parts.pop();
  return parts.join(",").trim();
};

const buildParts = (parts, separator = ", ") => parts.filter(Boolean).join(separator);

/** Daily at 23:55 local (as of Jan 1), expressed in UTC. */
export const recurringCron = () => {
  const originalTime = moment.tz(
    "01/01/2025 23:55",
    "MM/DD/YYYY HH:mm",
    Intl.DateTimeFormat().resolvedOptions().timeZone
  );
  const notifyDate = new Date(originalTime.utc().format("MM/DD/YYYY HH:mm"));
  return `${notifyDate.getMinutes()} ${notifyDate.getHours()} * * *`;
};

/** Form values -> scheduler `data` ({ schedule, events, timezone, ... }). */
export const buildRecurringRequestData = (rawValues: any, ctx: RecurringBuildContext) => {
  const { userId, connectionId, accounts, projects } = ctx;
  const pageId = undefined;
  const values = rawValues["undefined"] ? rawValues["undefined"] : rawValues;

  if (values.pickupLocation) values.pickupLocation.type = "temp-location";
  if (values.dropoffLocation) values.dropoffLocation.type = "temp-location";

  const extendedAttributes: any = {};
  Object.keys(values).forEach((key) => {
    const formattedObj = formatObject(key, key, values[key], [], {});
    if (Array.isArray(formattedObj)) {
      formattedObj.forEach((obj) => _.merge(extendedAttributes, obj));
    } else {
      _.merge(extendedAttributes, formattedObj);
    }
  });

  const selectedAccount = accounts?.find(
    (x) => x?.objectId?.toString() === extendedAttributes?.billingInstitute
  );
  const project: any = Object.values(
    selectedAccount?.info?.page?.folder?.projectComponents || {}
  )?.find((x: any) => x?.components?.[0] === "onMove");
  const sortedAttributes: any = {
    ...extendedAttributes,
    billingInstituteName: selectedAccount?.info?.name,
    project: { id: project?.projectId, type: "project" },
    sharePassengerLink: values.sharePassengerLink,
    overwriteCustomerInQuickbook: values?.overwriteCustomerInQuickbook,
    pricingType: values?.pricingType?.value?.name,
    equipmentType: values?.equipment?.categories?.toString(),
    equipment: values?.equipment?.subCategories?.toString(),
  };

  // Secondary crew is split between the two vehicles only with a different vehicle.
  const equipmentType = values?.differentVehicle
    ? getEquipmentType(values?.equipmentNeeded)
    : null;

  const crewFor = (primary, secondary) => {
    const list = [];
    if (primary?.id) list.push(toResponder(primary));
    if (secondary?.responders?.length > 0) {
      if (equipmentType) {
        list.push(...distributeSecondaryResponders(secondary.responders, equipmentType).primaryResponders);
      } else {
        secondary.responders.forEach((r) => list.push(toResponder(r)));
      }
    }
    return list;
  };
  const stairchairCrewFor = (stairchair, secondary) => {
    const list = [];
    if (stairchair?.id) list.push(toResponder(stairchair));
    if (equipmentType && secondary?.responders?.length > 0) {
      list.push(
        ...distributeSecondaryResponders(secondary.responders, equipmentType).stairchairResponders
      );
    }
    return list;
  };
  /** Secondary crew that stays with the primary vehicle, as stored on the page. */
  const primarySecondary = (secondary) => {
    if (!equipmentType || !(secondary?.responders?.length > 0)) return secondary;
    const { primaryResponders } = distributeSecondaryResponders(secondary.responders, equipmentType);
    return { responders: primaryResponders.map((r) => ({ id: r.id, beamId: r.beamId })) };
  };

  const responders = crewFor(sortedAttributes?.primaryResponder, sortedAttributes?.secondaryResponder);
  const returnResponders = crewFor(
    sortedAttributes?.returnPrimaryResponder,
    sortedAttributes?.returnSecondaryResponder
  );
  const stairchairResponders = stairchairCrewFor(
    sortedAttributes?.stairchairResponder,
    sortedAttributes?.secondaryResponder
  );
  const returnStairchairResponders = stairchairCrewFor(
    sortedAttributes?.returnStairchairResponder,
    sortedAttributes?.returnSecondaryResponder
  );

  let eventRequests = [];
  const uuid = generateUUID();

  const oneWaysortedAttributes = {
    ...sortedAttributes,
    secondaryResponder: primarySecondary(sortedAttributes?.secondaryResponder),
    returnPickupTime: undefined,
  };

  // Only the time of day matters; the service substitutes the real date.
  const hasPickupTime = !!oneWaysortedAttributes?.pickupTime;
  const tempDate = new Date();
  if (hasPickupTime) {
    const tempTime = new Date(oneWaysortedAttributes.pickupTime);
    tempDate.setHours(tempTime.getHours());
    tempDate.setMinutes(tempTime.getMinutes());
  }

  if (values?.usedServiceBefore === "no" || values?.overwriteCustomerInQuickbook) {
    const billingEmail =
      values?.billingType?.includes("privateEmail") ||
      values?.billingType?.includes("creditCardOnFile") ||
      values?.billingType?.includes("creditCardOneTime") ||
      values?.billingType?.includes("snailMail")
        ? values?.billingEmail
        : "accounts@hulpr.ca";

    const customerObject: any = {
      DisplayName: `${capitalizeWords(values.patientFirstName)} ${capitalizeWords(values.patientLastName)}`,
      GivenName: values.patientFirstName,
      FamilyName: values.patientLastName,
      CompanyName: values.insitutionIdForBilling,
      PrimaryPhone: { FreeFormNumber: values.billingPhoneNumber },
      PrimaryEmailAddr: { Address: billingEmail },
      BillAddr: {
        Line1: [
          values.careHomeName?.trim(),
          typeof values.primaryHomeAddress === "string"
            ? values.primaryHomeAddress.trim()
            : (values.primaryHomeAddress?.value?.attributes?.address || "").trim(),
        ]
          .filter(Boolean)
          .join(", "),
      },
      Notes: buildNotes(values, billingEmail),
    };
    oneWaysortedAttributes["quickBooksCustomer"] = cleanObject(customerObject);
  }

  const pickupTimeStamp = tempDate.getTime();
  oneWaysortedAttributes["pickupDate"] = moment(pickupTimeStamp)?.format("MMM-DD");
  oneWaysortedAttributes["pickupTime"] = hasPickupTime
    ? moment(pickupTimeStamp)?.format("HH:mm")
    : "Unknown Time";
  if (oneWaysortedAttributes?.appointmentTime) {
    oneWaysortedAttributes["appointmentTime"] = moment(
      oneWaysortedAttributes?.appointmentTime
    )?.format("HH:mm");
  }
  if (oneWaysortedAttributes?.patientDateOfBirth) {
    oneWaysortedAttributes["patientDateOfBirth"] = moment(
      oneWaysortedAttributes?.patientDateOfBirth
    )?.format("MM/DD/YYYY");
  }
  const fullName = (attrs) =>
    `${attrs?.patientFirstName?.toLowerCase()} ${attrs?.patientLastName?.toLowerCase()}`;
  const titleName = (attrs) =>
    `${attrs?.patientFirstName}${
      attrs?.patientLastName && attrs?.patientLastName !== "" ? " " + attrs?.patientLastName : ""
    }`;

  eventRequests.push({
    userId,
    attributes: {
      uuid: uuid,
      ...oneWaysortedAttributes,
      pickupAddress: oneWaysortedAttributes?.pickupLocation?.attributes?.address,
      dropoffAddress: oneWaysortedAttributes?.dropoffLocation?.attributes?.address,
      patientFullName: fullName(oneWaysortedAttributes),
      schedule: undefined,
    },
    responders,
    submitted: true,
    connectionId,
    unstructuredAttributes: { ...values },
    pageId,
    title: `${titleName(oneWaysortedAttributes)}, <pickupDate> ${
      hasPickupTime ? moment(pickupTimeStamp).format("hh:mm A") : "Unknown Time"
    }`,
    createdAt: pickupTimeStamp || new Date().getTime(),
    cudbServiceId: projects?.userServiceId,
  });

  if (sortedAttributes?.serviceType === "C/R") {
    const updatedReturnSecondaryResponder = primarySecondary(
      sortedAttributes?.returnSecondaryResponder
    );

    const twoWaysortedAttributes = {
      ...sortedAttributes,
      pickupLocationName: sortedAttributes.dropoffLocationName,
      pickupLocation: sortedAttributes.dropoffLocation,
      pickupDoorCode: sortedAttributes.dropoffDoorCode,
      pickupEntranceUnitRoom: sortedAttributes.dropoffEntranceUnitRoom,
      dropoffLocationName: sortedAttributes.pickupLocationName,
      dropoffLocation: sortedAttributes.pickupLocation,
      dropoffDoorCode: sortedAttributes.pickupDoorCode,
      dropoffEntranceUnitRoom: sortedAttributes.pickupEntranceUnitRoom,
      pickupTime: sortedAttributes.returnPickupTime,
      pickupInstructions: sortedAttributes.returnPickupInstructions,
      returnPickupTime: undefined,
      appointmentTime: undefined,
      primaryResponder: sortedAttributes?.returnPrimaryResponder,
      secondaryResponder: updatedReturnSecondaryResponder,
      equipment: sortedAttributes?.returnEquipment,
      vehicle: sortedAttributes?.returnVehicle,
    };

    const hasReturnTime = !!twoWaysortedAttributes.pickupTime;
    const returnDate = new Date();
    if (hasReturnTime) {
      const tempTime = new Date(twoWaysortedAttributes.pickupTime);
      returnDate.setHours(tempTime.getHours());
      returnDate.setMinutes(tempTime.getMinutes());
    }

    const returnTimeStamp = returnDate.getTime();
    twoWaysortedAttributes["pickupDate"] = moment(returnTimeStamp)?.format("MMM-DD");
    twoWaysortedAttributes["pickupTime"] = hasReturnTime
      ? moment(returnTimeStamp)?.format("HH:mm")
      : "Unknown Time";

    if (twoWaysortedAttributes?.patientDateOfBirth) {
      twoWaysortedAttributes["patientDateOfBirth"] = moment(
        twoWaysortedAttributes?.patientDateOfBirth
      )?.format("MM/DD/YYYY");
    }

    eventRequests.push({
      userId,
      attributes: {
        uuid: uuid,
        ...twoWaysortedAttributes,
        pickupAddress: twoWaysortedAttributes?.pickupLocation?.attributes?.address,
        dropoffAddress: twoWaysortedAttributes?.dropoffLocation?.attributes?.address,
        patientFullName: fullName(twoWaysortedAttributes),
        schedule: undefined,
        primaryResponder: sortedAttributes?.returnPrimaryResponder,
        secondaryResponder: updatedReturnSecondaryResponder,
        equipment: sortedAttributes?.returnEquipment,
        vehicle: sortedAttributes?.returnVehicle,
      },
      responders: returnResponders,
      submitted: true,
      connectionId,
      unstructuredAttributes: { ...values },
      pageId: pageId,
      title: `${titleName(twoWaysortedAttributes)}, <pickupDate> ${
        hasReturnTime ? moment(returnTimeStamp).format("hh:mm A") : "Unknown Time"
      }`,
      createdAt: returnTimeStamp || new Date().getTime(),
      cudbServiceId: projects?.userServiceId,
    });
  }

  // Separate stairchair/scoop driver events when "Different vehicle" is selected.
  if (values?.differentVehicle && sortedAttributes?.stairchairResponder?.id) {
    const stairEquipmentType = getEquipmentType(values?.equipmentNeeded);
    if (stairEquipmentType) {
      const stairsLocations = values?.stairsLocations || [];
      const serviceType = sortedAttributes?.serviceType;
      const primaryPickupTime = oneWaysortedAttributes?.pickupTime || "Unknown Time";
      const primaryReturnTime = sortedAttributes?.returnPickupTime
        ? moment(sortedAttributes.returnPickupTime).format("HH:mm")
        : "Unknown Time";

      const { pickupTime: stairchairPickupTime, returnPickupTime: stairchairReturnTime } =
        getStairchairPickupTimes(values, serviceType, stairsLocations, primaryPickupTime, primaryReturnTime);

      const createStairchairEvent = (isReturn = false) => {
        let stairchairAttributes: any;
        const stairchairPickupTimeToUse = isReturn ? stairchairReturnTime : stairchairPickupTime;
        const stairchairVehicle = isReturn
          ? sortedAttributes?.returnStairchairVehicle
          : sortedAttributes?.stairchairVehicle;
        const primaryResponder = isReturn
          ? sortedAttributes?.returnStairchairResponder
          : sortedAttributes?.stairchairResponder;

        let stairchairSecondaryResponder = undefined;
        const secondaryRespondersSource = isReturn
          ? sortedAttributes?.returnSecondaryResponder?.responders
          : sortedAttributes?.secondaryResponder?.responders;
        if (stairEquipmentType && secondaryRespondersSource?.length > 0) {
          const { stairchairResponders: secondaryForStairchair } = distributeSecondaryResponders(
            secondaryRespondersSource,
            stairEquipmentType
          );
          if (secondaryForStairchair.length > 0) {
            stairchairSecondaryResponder = {
              responders: secondaryForStairchair.map((r) => ({ id: r.id, beamId: r.beamId })),
            };
          }
        }

        if (serviceType === "C/R" && isReturn) {
          stairchairAttributes = {
            ...sortedAttributes,
            pickupLocationName: sortedAttributes.dropoffLocationName,
            pickupLocation: sortedAttributes.dropoffLocation,
            pickupDoorCode: sortedAttributes.dropoffDoorCode,
            pickupEntranceUnitRoom: sortedAttributes.dropoffEntranceUnitRoom,
            dropoffLocationName: sortedAttributes.pickupLocationName,
            dropoffLocation: sortedAttributes.pickupLocation,
            dropoffDoorCode: sortedAttributes.pickupDoorCode,
            dropoffEntranceUnitRoom: sortedAttributes.pickupEntranceUnitRoom,
            pickupTime: stairchairPickupTimeToUse,
            pickupInstructions: sortedAttributes.returnPickupInstructions,
            returnPickupTime: undefined,
            appointmentTime: undefined,
            vehicle: stairchairVehicle,
            primaryResponder: primaryResponder,
            secondaryResponder: stairchairSecondaryResponder,
          };
        } else {
          stairchairAttributes = {
            ...sortedAttributes,
            pickupTime: stairchairPickupTimeToUse,
            vehicle: stairchairVehicle,
            primaryResponder: primaryResponder,
            secondaryResponder: stairchairSecondaryResponder,
          };
        }

        const baseDate = sortedAttributes?.pickupDate;
        const stairDate = baseDate ? new Date(baseDate) : new Date();
        if (stairchairPickupTimeToUse && stairchairPickupTimeToUse !== "Unknown Time") {
          const timeParts = stairchairPickupTimeToUse.split(":");
          if (timeParts.length === 2) {
            stairDate.setHours(parseInt(timeParts[0]));
            stairDate.setMinutes(parseInt(timeParts[1]));
          }
        }

        const stairTimeStamp = stairDate.getTime();
        stairchairAttributes["pickupDate"] = moment(stairTimeStamp)?.format("MMM-DD");
        stairchairAttributes["pickupTime"] = stairchairPickupTimeToUse;
        if (stairchairAttributes?.patientDateOfBirth) {
          stairchairAttributes["patientDateOfBirth"] = moment(
            stairchairAttributes?.patientDateOfBirth
          )?.format("MM/DD/YYYY");
        }

        return {
          userId,
          attributes: {
            ...stairchairAttributes,
            pickupAddress: stairchairAttributes?.pickupLocation?.attributes?.address,
            dropoffAddress: stairchairAttributes?.dropoffLocation?.attributes?.address,
            patientFullName: fullName(stairchairAttributes),
            pickupLocationFullName: stairchairAttributes?.pickupLocationName?.toLowerCase(),
            dropoffLocationFullName: stairchairAttributes?.dropoffLocationName?.toLowerCase(),
            uuid: uuid,
            isStairchairDriver: true,
            equipmentType: stairEquipmentType,
            schedule: undefined,
          },
          responders: isReturn ? returnStairchairResponders : stairchairResponders,
          submitted: true,
          connectionId,
          unstructuredAttributes: { ...values },
          pageId: undefined,
          title: `${titleName(stairchairAttributes)}, ${
            stairchairAttributes.pickupTime
              ? `<pickupDate> ${moment(stairTimeStamp).format("hh:mm A")}`
              : `<pickupDate> N/A`
          }`,
          createdAt: stairTimeStamp || new Date().getTime(),
          cudbServiceId: projects?.userServiceId,
        };
      };

      if (serviceType === "O/W") {
        eventRequests.push(createStairchairEvent(false));
      } else if (serviceType === "W/R" || serviceType === "C/R") {
        eventRequests.push(createStairchairEvent(false));
        eventRequests.push(createStairchairEvent(true));
      }
    }
  }

  eventRequests = eventRequests.map((request) => {
    const customMessages = [];
    const {
      pickupTime,
      returnPickupTime,
      serviceType,
      transferType,
      equipmentNeeded,
      patientFirstName,
      patientLastName,
      patientDateOfBirth,
      weight,
      weightUnit,
      oxygen,
      oxygenSupplied,
      pickupLocationName,
      pickupEntranceUnitRoom,
      pickupAddress,
      dropoffLocationName,
      dropoffEntranceUnitRoom,
      dropoffAddress,
      pickupInstructions,
      pickupLocation,
      dropoffLocation,
      waitTime,
      pickupDoorCode,
      dropoffDoorCode,
      escorts,
      DNRform,
      otherDiagnoses,
      appointmentTime,
    } = request.attributes;

    const weightInLbs = weightUnit === "kg" ? weight * 2.20462 : weight;
    const bariatric = weightInLbs > 250;

    const patientName = [patientFirstName, patientLastName].filter(Boolean).join(" ");
    const weightText = weight ? `${weight} ${weightUnit || ""}`.trim() : "";
    const dobText = patientDateOfBirth ? `DOB ${patientDateOfBirth}` : "";

    const pickupInfo = buildParts([
      pickupLocationName,
      pickupEntranceUnitRoom,
      pickupDoorCode ? `Door Code: ${pickupDoorCode}` : null,
      removeCountry(pickupAddress),
    ]);
    const dropoffInfo = buildParts([
      dropoffLocationName,
      dropoffEntranceUnitRoom,
      dropoffDoorCode ? `Door Code: ${dropoffDoorCode}` : null,
      removeCountry(dropoffAddress),
    ]);

    const oxygenDetails = oxygen
      ? `Oxygen ${oxygen}L${oxygenSupplied ? ` supplied by ${oxygenSupplied}` : ""}`
      : "";

    const isStairchairDriver = request.attributes?.isStairchairDriver;
    const msgEquipmentType = getEquipmentType(values?.equipmentNeeded);
    const differentVehicle = values?.differentVehicle;
    const stairsLocations = values?.stairsLocations || [];
    const hasPickup = stairsLocations.includes("Pickup");
    const hasDropoff = stairsLocations.includes("Dropoff");
    const bothSelected = hasPickup && hasDropoff;

    // The primary driver doesn't bring the stair chair / scoop when another vehicle does.
    let filteredEquipmentNeeded = equipmentNeeded;
    if (differentVehicle && !isStairchairDriver && equipmentNeeded) {
      const equipmentArray = Array.isArray(equipmentNeeded)
        ? equipmentNeeded
        : equipmentNeeded.split(", ");
      filteredEquipmentNeeded = equipmentArray
        .filter((eq: string) => eq !== "Bring Stair Chair" && eq !== "Bring Scoop")
        .join(", ");
    }

    const head = (time) =>
      `${time || "Unknown time"} - <pickupDate> - ${serviceType || ""} - ${transferType || ""}`;
    const primaryResponderName =
      values?.primaryResponder?.name || request.attributes?.primaryResponder?.name || "Primary Responder";
    const equipmentName = msgEquipmentType === "Stairchair" ? "Stairchair" : "Scoop";
    const patientDetails =
      weightText || dobText ? ` (${buildParts([weightText, dobText])})` : "";
    const equipmentAndOxygen = `${filteredEquipmentNeeded ? ` - ${filteredEquipmentNeeded}` : ""}${
      oxygenDetails ? `, ${oxygenDetails}` : ""
    } -${bariatric ? " Bariatric -" : ""}`;

    let message = "";
    if (isStairchairDriver && msgEquipmentType) {
      if (bothSelected) {
        message = `${head(pickupTime)} - BRING ${equipmentName} Meet ${primaryResponderName} for ${patientName} at ${pickupInfo}, drive behind ${primaryResponderName} to ${dropoffInfo} to assist with stairs there as well.`;
      } else if (hasPickup) {
        message = `${head(pickupTime)} - BRING ${equipmentName} Meet driver for ${patientName} at ${pickupInfo}`;
      } else if (hasDropoff) {
        message = `${head(pickupTime)} - BRING ${equipmentName} Meet driver for ${patientName} at ${dropoffInfo}`;
      } else {
        message = `${head(pickupTime)} - BRING ${equipmentName} Meet driver for ${patientName}`;
      }
    } else {
      message = `${head(pickupTime)}${equipmentAndOxygen} Pick up ${patientName}${patientDetails} from ${pickupInfo}. Take them to ${dropoffInfo}.`;

      if (appointmentTime) message += ` Appointment is at ${appointmentTime}.`;
      if (waitTime) message += ` Appointment should be approximately ${waitTime} hours.`;
      if (serviceType === "W/R") {
        message += " Please stay with patient for the duration of their appointment.";
      }

      if (values?.diagnoses && Array.isArray(values?.diagnoses) && values?.diagnoses.length > 0) {
        const readableDiagnoses = values.diagnoses
          .map((d) => DIAGNOSIS_OPTIONS.find((opt) => opt.value === d)?.label || d)
          .filter((d) => d !== "Other");
        if (values.diagnoses.includes("other") && otherDiagnoses) {
          readableDiagnoses.push(otherDiagnoses);
        }
        const diagnosisText = readableDiagnoses.join(", ");
        if (diagnosisText) message += ` Diagnosis: ${diagnosisText}.`;
      }

      if (pickupInstructions) message += ` Instructions: ${pickupInstructions}.`;
      if (escorts) message += ` Escorts: ${escorts}.`;
      if (DNRform === true || DNRform === "true" || DNRform === "yes" || DNRform === "Yes") {
        message += ` Ask Nurse for DNR form.`;
      }

      if (differentVehicle && msgEquipmentType) {
        if (bothSelected) {
          message += ` This is a ${equipmentName} transfer. Another Driver will meet you at the Pickup and Dropoff locations with the ${equipmentName}.`;
        } else if (hasPickup) {
          message += ` This is a ${equipmentName} transfer. Another Driver will meet you at Pickup location with the ${equipmentName}.`;
        } else if (hasDropoff) {
          message += ` This is a ${equipmentName} transfer. Another Driver will meet you at Dropoff location with the ${equipmentName}.`;
        }
      }
    }
    customMessages.push({ type: "text", attributes: { body: message } });

    // W/R is a single page carrying both legs.
    if (serviceType === "W/R") {
      let returnMessage = "";
      if (isStairchairDriver && msgEquipmentType) {
        if (bothSelected) {
          returnMessage = `${head(returnPickupTime)} - BRING ${equipmentName} Meet ${primaryResponderName} for ${patientName} at ${dropoffInfo}, drive behind ${primaryResponderName} to ${pickupInfo} to assist with stairs there as well.`;
        } else if (hasPickup) {
          returnMessage = `${head(returnPickupTime)} - BRING ${equipmentName} Meet driver for ${patientName} at ${pickupInfo}`;
        } else if (hasDropoff) {
          returnMessage = `${head(returnPickupTime)} - BRING ${equipmentName} Meet driver for ${patientName} at ${dropoffInfo}`;
        } else {
          returnMessage = `${head(returnPickupTime)} - BRING ${equipmentName} Meet driver for ${patientName}`;
        }
      } else {
        returnMessage = `${head(returnPickupTime)}${equipmentAndOxygen} Pick up ${patientName}${patientDetails} from ${dropoffInfo}. Take them to ${pickupInfo}.`;
      }
      customMessages.push({ type: "text", attributes: { body: returnMessage } });
    }

    // Each page asks its own crew to accept the job.
    if (request.responders && request.responders.length > 0) {
      const place = (body, location) => ({
        type: "place",
        attributes: {
          body,
          attributes: location.attributes,
          display: { type: "marker", color: "blue" },
          coordinates: location.coordinates,
        },
      });

      customMessages.push({
        type: "rsvp",
        attributes: {
          body: "Accept job",
          type: "yes-no",
          options: { option1: "Yes", option2: "No" },
          rsvpTitle: "Accept job",
          callback: {
            topic: `${process.env.REACT_APP_ECO_SYSTEM}/connection/${connectionId}/service/hpd-dps/rsvpReplyEvent`,
            data: {
              type: "cancelPage",
              pickupLocation: place("Pickup location", pickupLocation),
              dropoffLocation: place("Dropoff location", dropoffLocation),
              serviceType,
              waitTime,
            },
          },
        },
      });
    }
    request.customMessages = customMessages;
    request.attributes.customMessages = customMessages;
    return request;
  });

  return {
    schedule: values?.schedule,
    events: eventRequests,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    cudbServiceId: projects?.userServiceId,
    scheduleUdid: ctx.existing ? ctx.existing.scheduleUdid : generateUUID(),
  };
};
