/**
 * Maps Hulpr CSV column names to Beam form field names for bulk upload.
 * Based on the Hulpr CSV → Beam Column mapping spec.
 */

import moment from "moment";

/** Hulpr column name -> Beam field name. Use "-" or omit for columns to skip. */
const HULPR_TO_BEAM: Record<string, string> = {
  "Notes, Updates": "instructions",
  "Patient Name": "patientName",
  "Patient First Name": "patientFirstName",
  "Patient Last Name": "patientLastName",
  "Billing Institution": "billingInstituteName",
  "Service Type": "serviceType",
  "Transfer Type": "transferType",
  "Hulpr Oxygen": "oxygen",
  "Pickup - Location Name": "pickupLocationName",
  "Pickup - Entrance, Unit, Room #": "pickupEntranceUnitRoom",
  "Pickup - Address": "pickupAddress",
  "Pickup - Date": "pickupDate",
  "Pickup - Time": "pickupTime",
  "Appt Time": "appointmentTime",
  "Drop-off - Location Name": "dropoffLocationName",
  "Drop-off - Entrance, Unit, Room #": "dropoffEntranceUnitRoom",
  "Drop-off - Address": "dropoffAddress",
  "Quoted Price": "quotedPrice",
  "Diagnoses, Precautions, Notes": "otherDiagnoses",
  "Escorts/Passengers": "escorts",
  "Instructions for Pickup Ride": "pickupInstructions",
  "Instructions for Return Ride": "returnPickupInstructions",
  "MT #": "MTNumber",
  "DNR Form": "DNRform",
  "Confirmation #": "confirmationNumber",
  "Booking Clerk Name": "bookingClerk",
  "Weight (& height if necessary)": "weight",
  "Patient's Hospital ID# (QHC)": "patientHospitalId",
  "Has the patient used our service before?": "usedServiceBefore",
  "Patient's DOB": "patientDateOfBirth",
  "Phone Number": "patientPhoneNumber",
  "Additional Contact": "additionalContact",
  "Support Worker / Case Worker Contact": "additionalQuickbooksNotes",
  "Billing Email": "billingEmail",
  "Primary (Home) Address": "primaryHomeAddress",
  "Pickup - Door Code": "pickupDoorCode",
  "Drop-off - Door Code": "dropoffDoorCode",
  Equipment: "equipment",
  "Return Pickup - Time": "returnPickupTimeRaw",
};

/** Unicode apostrophes / primes → ASCII for header matching. */
function normalizeHeaderForCompare(key: string): string {
  return (key || "")
    .trim()
    .replace(/[\u2018\u2019\u201A\u201B\u2032\u2035]/g, "'")
    .toLowerCase();
}

/**
 * Normalize header key: trim and match case-insensitively against known Hulpr columns.
 */
function normalizeKey(key: string): string | null {
  const normalized = normalizeHeaderForCompare(key);
  if (!normalized) return null;
  const found = Object.keys(HULPR_TO_BEAM).find(
    (k) => normalizeHeaderForCompare(k) === normalized
  );
  return found || null;
}

/**
 * CSV "Ask nurse for DNR form" / yes / empty → boolean. Exported for schedule message logic.
 */
export function normalizeDnrFormValue(raw: unknown): boolean {
  if (raw === true) return true;
  if (raw === false || raw === null || raw === undefined) return false;
  const s = String(raw).trim().toLowerCase();
  if (!s) return false;
  if (s === "true" || s === "yes" || s === "y" || s === "1") return true;
  if (s === "false" || s === "no" || s === "n" || s === "0") return false;
  if (s.includes("dnr")) return true;
  if (s.includes("ask") && s.includes("nurse")) return true;
  return false;
}

/**
 * Get raw value from row by beam field name (resolves Hulpr column name).
 * Returns string, Date, or number (Excel serial) so parsers can handle each.
 */
function getRowValue(row: Record<string, unknown>, beamField: string): string | Date | number | undefined {
  const hulprKey = Object.entries(HULPR_TO_BEAM).find(
    ([, beam]) => beam === beamField
  )?.[0];
  if (hulprKey) {
    let v = row[hulprKey];
    if (v === undefined || v === null) {
      const nk = normalizeHeaderForCompare(hulprKey);
      const key = Object.keys(row).find((k) => normalizeHeaderForCompare(k) === nk);
      if (key) v = row[key];
    }
    if (v !== undefined && v !== null) {
      if (typeof v === "string" && v.trim() !== "") return v.trim();
      if (v instanceof Date) return v;
      if (typeof v === "number" && !Number.isNaN(v)) return v;
    }
  }
  const v = row[beamField];
  if (v !== undefined && v !== null) {
    if (typeof v === "string" && v.trim() !== "") return v.trim();
    if (v instanceof Date) return v;
    if (typeof v === "number" && !Number.isNaN(v)) return v;
  }
  return undefined;
}

/**
 * Excel serial number epoch (Jan 1, 1970 = 25569 in Excel).
 */
function excelSerialToDate(serial: number): Date {
  const utc = (serial - 25569) * 86400 * 1000;
  return new Date(utc);
}

/**
 * Pickup date: preserve year from Date, Excel serial, ISO, and dated strings.
 * Yearless "Sun, Feb 1" uses current calendar year.
 */
function parsePickupDate(val: string | Date | number | undefined): string | undefined {
  if (val === undefined || val === null) return undefined;
  const currentYear = moment().year();

  if (val instanceof Date) {
    if (Number.isNaN(val.getTime())) return undefined;
    return moment(val).format("YYYY-MM-DD");
  }

  if (typeof val === "number") {
    const d = excelSerialToDate(val);
    if (Number.isNaN(d.getTime())) return undefined;
    return moment(d).format("YYYY-MM-DD");
  }

  const s = String(val).trim();
  if (!s) return undefined;

  const csvDateFormatsYearless = ["ddd, MMM D", "ddd, MMM DD"];
  for (const f of csvDateFormatsYearless) {
    const m = moment(s, f, true);
    if (m.isValid()) {
      m.year(currentYear);
      return m.format("YYYY-MM-DD");
    }
  }

  const csvDateFormatsWithYear = [
    "ddd, MMM D, YYYY",
    "ddd, MMM DD, YYYY",
    "ddd, MMM D, YY",
    "ddd, MMM DD, YY",
  ];
  for (const f of csvDateFormatsWithYear) {
    const m = moment(s, f, true);
    if (m.isValid()) return m.format("YYYY-MM-DD");
  }

  const otherFormats = ["YYYY-MM-DD", "MM/DD/YYYY", "MMM-DD", "MM-DD-YYYY", "DD/MM/YYYY"];
  for (const f of otherFormats) {
    const m = moment(s, f, true);
    if (m.isValid()) return m.format("YYYY-MM-DD");
  }

  const fromIso = moment(s, moment.ISO_8601, true);
  if (fromIso.isValid()) return fromIso.format("YYYY-MM-DD");

  const loose = moment(s);
  if (loose.isValid()) return loose.format("YYYY-MM-DD");

  return undefined;
}

/**
 * DOB: never apply yearless weekday rules; preserve year from Date / Excel / strings.
 */
function parseDateOfBirth(val: string | Date | number | undefined): string | undefined {
  if (val === undefined || val === null) return undefined;

  if (val instanceof Date) {
    if (Number.isNaN(val.getTime())) return undefined;
    return moment(val).format("YYYY-MM-DD");
  }

  if (typeof val === "number") {
    const d = excelSerialToDate(val);
    if (Number.isNaN(d.getTime())) return undefined;
    return moment(d).format("YYYY-MM-DD");
  }

  const s = String(val).trim();
  if (!s) return undefined;

  const otherFormats = [
    "YYYY-MM-DD",
    "MM/DD/YYYY",
    "MMM-DD",
    "MM-DD-YYYY",
    "DD/MM/YYYY",
    "M/D/YYYY",
    "D/M/YYYY",
  ];
  for (const f of otherFormats) {
    const m = moment(s, f, true);
    if (m.isValid()) return m.format("YYYY-MM-DD");
  }

  const fromIso = moment(s, moment.ISO_8601, true);
  if (fromIso.isValid()) return fromIso.format("YYYY-MM-DD");

  const loose = moment(s);
  if (loose.isValid()) return loose.format("YYYY-MM-DD");

  return undefined;
}

/**
 * Parse time from CSV/XLS. Handles:
 * - Date objects (from XLSX)
 * - Excel serial (fraction of day, e.g. 0.583333 = 14:00)
 * - "14:00" (24-hour HH:mm)
 */
function parseTime(val: string | Date | number | undefined): string | undefined {
  if (val === undefined || val === null) return undefined;

  if (val instanceof Date) {
    if (Number.isNaN(val.getTime())) return undefined;
    return moment(val).format("HH:mm");
  }

  if (typeof val === "number") {
    if (val >= 0 && val < 1) {
      const hours = Math.floor(val * 24);
      const minutes = Math.round((val * 24 - hours) * 60);
      return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
    }
    const d = excelSerialToDate(val);
    if (!Number.isNaN(d.getTime())) return moment(d).format("HH:mm");
    return undefined;
  }

  const s = String(val).trim();
  if (!s) return undefined;

  const m = moment(s, ["HH:mm", "HH:mm:ss", "h:mm A", "hh:mm A", "H:mm"], true);
  if (m.isValid()) return m.format("HH:mm");
  return undefined;
}

/**
 * Build a form-like values object from a raw Hulpr CSV row for use with
 * buildEventRequestsFromValues. Resolves billing institute by name when accounts are provided.
 */
export function mapHulprRowToBeamValues(
  row: Record<string, unknown>,
  accounts?: Array<{ objectId?: string; info?: { name?: string } }>
): Record<string, unknown> {
  const get = (beamField: string) => getRowValue(row, beamField);

  const pickupAddress = get("pickupAddress");
  const dropoffAddress = get("dropoffAddress");

  const pickupDateRaw = get("pickupDate") || get("Pickup - Date");
  const pickupDate = parsePickupDate(pickupDateRaw as string | Date | number | undefined);
  const pickupTime = parseTime(get("pickupTime") || get("Pickup - Time"));
  const returnPickupTimeRaw = get("returnPickupTimeRaw") || get("Return Pickup - Time");

  // Return Pickup - Time: Hulpr is time only; Beam expects datetime — combine with Pickup - Date
  let returnPickupTime: string | undefined;
  if (returnPickupTimeRaw && pickupDate) {
    const t = parseTime(returnPickupTimeRaw);
    if (t) {
      const combined = moment(`${pickupDate} ${t}`, "YYYY-MM-DD HH:mm");
      if (combined.isValid()) {
        returnPickupTime = combined.toISOString();
      }
    }
  }

  const values: Record<string, unknown> = {};

  for (const [, beamField] of Object.entries(HULPR_TO_BEAM)) {
    if (beamField === "-" || !beamField) continue;
    if (beamField === "returnPickupTimeRaw") continue; // handled above
    const raw = getRowValue(row, beamField);
    if (raw === undefined || raw === null) continue;
    const str = typeof raw === "string" ? raw.trim() : String(raw).trim();
    if (str === "" && typeof raw !== "number" && !(raw instanceof Date)) continue;

    if (beamField === "pickupDate") {
      const parsed = parsePickupDate(raw as string | Date | number);
      if (parsed) values[beamField] = parsed;
    } else if (beamField === "pickupTime") {
      const parsed = parseTime(raw as string | Date | number);
      if (parsed) values[beamField] = parsed;
    } else if (beamField === "patientDateOfBirth") {
      const parsed = parseDateOfBirth(raw as string | Date | number);
      if (parsed) values[beamField] = parsed;
    } else if (beamField === "appointmentTime") {
      const parsed = parseTime(raw as string | Date | number);
      if (parsed) values[beamField] = parsed;
    } else if (beamField === "DNRform") {
      values[beamField] = normalizeDnrFormValue(raw);
    } else {
      values[beamField] = typeof raw === "string" ? str : raw;
    }
  }

  values.pickupDate = (values.pickupDate as string) || pickupDate;
  // Builder uses new Date(pickupTime) — must be a full datetime string (e.g. YYYY-MM-DDTHH:mm:00)
  const timeOnly = (values.pickupTime as string) || pickupTime;
  if (timeOnly) {
    const datePart = pickupDate || moment().format("YYYY-MM-DD");
    const timePart = /^\d{1,2}:\d{2}$/.test(timeOnly) ? `${timeOnly}:00` : timeOnly;
    values.pickupTime = `${datePart}T${timePart}`;
  }

  const apptTimeOnly =
    (values.appointmentTime as string) || parseTime(get("appointmentTime"));
  if (apptTimeOnly) {
    const datePart =
      (values.pickupDate as string) || pickupDate || moment().format("YYYY-MM-DD");
    const timePart = /^\d{1,2}:\d{2}$/.test(apptTimeOnly) ? `${apptTimeOnly}:00` : apptTimeOnly;
    values.appointmentTime = `${datePart}T${timePart}`;
  }

  if (returnPickupTime) values.returnPickupTime = returnPickupTime;

  values.pickupLocationName = values.pickupLocationName || get("pickupLocationName");
  values.dropoffLocationName = values.dropoffLocationName || get("dropoffLocationName");

  values.pickupLocation = {
    type: "temp-location",
    label: pickupAddress || "",
    value: {
      attributes: { address: pickupAddress || "" },
      coordinates: {
        lat: 0,
        long: 0,
      },
    }
  };
  values.dropoffLocation = {
    type: "temp-location",
    label: dropoffAddress || "",
    value: {
      attributes: { address: dropoffAddress || "" },
      coordinates: {
        lat: 0,
        long: 0,
      },
    }
  };

  // Billing institution: resolve name to account objectId
  const billingInstituteName = values.billingInstituteName as string | undefined;
  if (billingInstituteName && Array.isArray(accounts) && accounts.length > 0) {
    const account = accounts.find(
      (acc) =>
        (acc?.info?.name || "").trim().toLowerCase() ===
        billingInstituteName.trim().toLowerCase()
    );
    if (account?.objectId) {
      values.billingInstitute = account.objectId.toString();
    }
  }

  return values;
}

/**
 * Normalize CSV/Excel row keys to match Hulpr column names (first row of file may have slight variations).
 */
export function normalizeRowKeys(row: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(row)) {
    const normalized = normalizeKey(key);
    if (normalized) {
      out[normalized] = value;
    }
    out[key] = value;
  }
  return out;
}
