import React, { FC, useEffect, useRef, useState } from "react";
import { Layout } from "antd";

import Header from "./Header";
import SideBar from "./SideBar";
import { CFO_MENU_ITEMS, menuLabel } from "./menu";
import { Domain, EntityKind, TransactionFilter } from "./types";
import DashboardScreen from "./screens/DashboardScreen";
import EntityScreen from "./screens/EntityScreen";
import TransactionsScreen, { TransactionPreset } from "./screens/TransactionsScreen";
import ReportsScreen from "./screens/ReportsScreen";

import "../../School3/Dashboard/Dashboard.scss";
import "./CFODashboard.scss";

/**
 * The CFO dashboard page: header across the top, icon rail down the
 * left, one screen at a time in the content pane.
 *
 * Four screens: Dashboard (the big picture), Transactions (every ledger
 * line and the payment schedule behind one filter), Reports (AR / AP
 * aging and reminders) and the Directory (players, teams, events,
 * coaches, staff and vendors behind one select). Dashboard and Reports
 * drill into Transactions by handing it a filter preset.
 *
 * Laid out with flex rather than the fixed header + rail the other
 * dashboards use, so the same look needs no viewport-sized magic
 * numbers and the content pane is the only thing that scrolls.
 */
const CFODashboardWrapper: FC<{ socket?: ISocket }> = ({ socket }) => {
  const [screen, setScreen] = useState<CFO_MENU_ITEMS>(CFO_MENU_ITEMS.Dashboard);
  const [domain, setDomain] = useState<Domain>("sport");
  const [entityKind, setEntityKind] = useState<EntityKind>("players");
  const [preset, setPreset] = useState<TransactionPreset | null>(null);
  const content = useRef<HTMLDivElement>(null);

  /* A new screen starts at the top, not wherever the last one was scrolled to. */
  useEffect(() => {
    if (content.current) content.current.scrollTop = 0;
  }, [screen, domain]);

  const switchDomain = (next: Domain) => {
    setDomain(next);
    setPreset(null);
    setScreen(CFO_MENU_ITEMS.Dashboard);
  };

  /** Lands on Transactions with the given filters applied. */
  const openTransactions = (filter: Partial<TransactionFilter>) => {
    setPreset({ filter, nonce: Date.now() });
    setScreen(CFO_MENU_ITEMS.Transactions);
  };

  const renderScreen = () => {
    switch (screen) {
      case CFO_MENU_ITEMS.Dashboard:
        return <DashboardScreen domain={domain} onOpenTransactions={openTransactions} socket={socket} />;
      case CFO_MENU_ITEMS.Transactions:
        return <TransactionsScreen domain={domain} preset={preset} />;
      case CFO_MENU_ITEMS.Reports:
        return <ReportsScreen domain={domain} onOpenTransactions={openTransactions} />;
      case CFO_MENU_ITEMS.Directory:
        return (
          <EntityScreen key={entityKind} kind={entityKind} onKindChange={setEntityKind} domain={domain} />
        );
      default:
        return (
          <div className="cfo-placeholder">
            <h2>{menuLabel(screen, domain)}</h2>
          </div>
        );
    }
  };

  return (
    <div className="cfo-shell">
      <Header domain={domain} onDomainChange={switchDomain} />

      <div className="cfo-shell__body">
        <div className="cfo-shell__rail">
          <SideBar screen={screen} setScreen={setScreen} domain={domain} />
        </div>

        <div className="cfo-shell__content" ref={content}>
          <div className="beam-modal analytics-summary-modal">
            <Layout className="main-layout exec-layout">
              {renderScreen()}
            </Layout>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CFODashboardWrapper;
