import React, { FC, useMemo, useState } from "react";
import { Badge, Button, Card, Col, DatePicker, Row, Table, Tooltip } from "antd";
import { ColumnsType } from "antd/lib/table";
import {
  ArrowDownOutlined,
  ArrowUpOutlined,
  BellOutlined,
  SearchOutlined,
  TeamOutlined,
} from "@ant-design/icons";
import moment, { Moment } from "moment";

import { AgingBucket, Domain, DunningAlert, LedgerAction, LedgerSide, TransactionFilter } from "../types";
import { ALERTS, DAY, DOMAIN_LABELS, LEDGER_ROWS, NOW } from "../mockData";
import {
  AGING_LABELS,
  AGING_ORDER,
  AccountAging,
  DUNNING_META,
  DUNNING_ORDER,
  ProjectReceivables,
  agingByAccount,
  buildSchedule,
  computeAging,
  computeKpis,
  formatMoney,
  receivablesByProject,
  withinWindow,
  TimeWindow,
} from "../selectors";
import { LedgerSideCard } from "../CashPanels";
import AlertCenter from "../AlertCenter";
import ActionModals, { ActionTarget } from "../ActionModals";
import ChartFrame, { ChartView, ChartViewToggle } from "../charts/ChartFrame";
import StackedBarChart, { StackItem } from "../charts/StackedBarChart";
import { CHART_COLORS } from "../charts/theme";

const { RangePicker } = DatePicker;

const BUCKET_TONE: Record<AgingBucket, string> = {
  current: "#1F9D55",
  "1-30": "#FBAE16",
  "31-60": "#FF5F25",
  "61+": "#E5484D",
};

const STAGE_TONE: Record<string, string> = {
  info: "#1F9D55",
  warning: "#FBAE16",
  danger: "#FF5F25",
  critical: "#E5484D",
};

const DOT_CLASS: Record<string, string> = {
  info: "success",
  warning: "warning",
  danger: "error",
  critical: "error",
};

const RECEIVABLE_SERIES = [
  { key: "collected", label: "Collected", color: CHART_COLORS.green },
  { key: "current", label: "Current AR", color: CHART_COLORS.blue },
  { key: "overdue", label: "Overdue AR", color: CHART_COLORS.red },
];

const DEFAULT_RANGE: TimeWindow = { from: NOW - 365 * DAY, to: NOW };

const rangeText = (window: TimeWindow) =>
  `${moment(window.from).format("D MMM YYYY")} - ${moment(window.to).format("D MMM YYYY")}`;

interface Props {
  domain: Domain;
  onOpenTransactions: (preset: Partial<TransactionFilter>) => void;
}

/**
 * AR and AP reports: each side's exposure with its aging, the accounts
 * that make the exposure up, receivables by team, and the reminder
 * machinery - the cadence every payment goes through and the live
 * dunning alerts. Everything drills into the Transactions screen.
 */
const ReportsScreen: FC<Props> = ({ domain, onOpenTransactions }) => {
  const [range, setRange] = useState<TimeWindow>(DEFAULT_RANGE);
  const [receivablesView, setReceivablesView] = useState<ChartView>("chart");
  const [action, setAction] = useState<LedgerAction | null>(null);
  const [actionTarget, setActionTarget] = useState<ActionTarget | null>(null);

  const labels = DOMAIN_LABELS[domain];
  const allRows = LEDGER_ROWS[domain];
  const rows = useMemo(() => allRows.filter((row) => withinWindow(row, range)), [allRows, range]);

  const kpis = useMemo(() => computeKpis(rows), [rows]);
  const agingAr = useMemo(() => computeAging(rows, "ar"), [rows]);
  const agingAp = useMemo(() => computeAging(rows, "ap"), [rows]);
  const accountsAr = useMemo(() => agingByAccount(rows, "ar"), [rows]);
  const accountsAp = useMemo(() => agingByAccount(rows, "ap"), [rows]);
  const receivables = useMemo(() => receivablesByProject(rows), [rows]);
  const schedule = useMemo(() => buildSchedule(allRows, ALERTS[domain], NOW), [allRows, domain]);

  const stageCounts = DUNNING_ORDER.map((bucket) => ({
    bucket,
    count: schedule.filter((item) => item.stage === bucket).length,
  }));

  const receivableItems = useMemo<StackItem[]>(
    () =>
      receivables.map((p: ProjectReceivables) => ({
        id: p.projectId,
        name: p.name,
        values: { collected: p.collected, current: p.current, overdue: p.overdue },
        total: p.total,
        selectable: p.projectId !== "other",
      })),
    [receivables]
  );

  /* ---- drill-downs ---- */

  const openAging = (side: LedgerSide) => (bucket: AgingBucket | null) => {
    if (bucket) onOpenTransactions({ side, aging: bucket, range });
  };

  const openAccount = (side: LedgerSide) => (account: AccountAging) =>
    onOpenTransactions({ side, search: account.entity, projectIds: [account.projectId], range });

  const rowBehind = (alert: DunningAlert) =>
    allRows.find((row) => row.entity === alert.entity && row.project === alert.project);

  const inspectAlert = (alert: DunningAlert) => onOpenTransactions({ search: alert.entity });

  const notifyFromAlert = (alert: DunningAlert) => {
    const match = rowBehind(alert);
    setAction("notify");
    setActionTarget({ level: "individual", label: alert.entity, rows: match ? [match] : [] });
  };

  const toWindow = (values: [Moment | null, Moment | null] | null): TimeWindow | null =>
    values && values[0] && values[1]
      ? { from: values[0].startOf("day").valueOf(), to: values[1].endOf("day").valueOf() }
      : null;

  /* ---- aging table ---- */

  const agingColumns = (side: LedgerSide): ColumnsType<AccountAging> => [
    {
      title: side === "ar" ? "Account" : "Payee",
      key: "entity",
      fixed: "left",
      width: 200,
      render: (_: unknown, account) => (
        <div className="cfo-cell">
          <div className="cfo-cell__main">{account.entity}</div>
          <div className="cfo-cell__sub">{account.entityRole}</div>
        </div>
      ),
    },
    { title: labels.navSingular.team + " / event", dataIndex: "project", key: "project", width: 200 },
    ...AGING_ORDER.map((bucket) => ({
      title: AGING_LABELS[bucket],
      key: bucket,
      align: "right" as const,
      width: 120,
      sorter: (a: AccountAging, b: AccountAging) => a.buckets[bucket] - b.buckets[bucket],
      render: (_: unknown, account: AccountAging) =>
        account.buckets[bucket] > 0 ? (
          <span style={{ color: BUCKET_TONE[bucket] }}>{formatMoney(account.buckets[bucket])}</span>
        ) : (
          <span className="cfo-muted">-</span>
        ),
    })),
    {
      title: "Total",
      key: "total",
      align: "right",
      width: 130,
      sorter: (a, b) => a.total - b.total,
      defaultSortOrder: "descend",
      render: (_: unknown, account) => <strong>{formatMoney(account.total)}</strong>,
    },
    {
      title: "Share",
      key: "share",
      align: "right",
      width: 90,
      render: (_: unknown, account) => <span className="cfo-pct">{account.sharePct}%</span>,
    },
    {
      title: "",
      key: "open",
      width: 56,
      fixed: "right",
      render: (_: unknown, account) => (
        <Tooltip title="Open transactions">
          <Button type="text" icon={<SearchOutlined />} onClick={() => openAccount(side)(account)} />
        </Tooltip>
      ),
    },
  ];

  const agingTable = (side: LedgerSide, accounts: AccountAging[]) => (
    <Table<AccountAging>
      rowKey="key"
      size="small"
      dataSource={accounts}
      columns={agingColumns(side)}
      scroll={{ x: 1100 }}
      pagination={{ pageSize: 8, showSizeChanger: false }}
      rowClassName={(account) =>
        account.buckets["61+"] > 0 ? "cfo-row--61+" : account.buckets["31-60"] > 0 ? "cfo-row--31-60" : ""
      }
    />
  );

  return (
    <div className="school-overview cfo-reports">
      <Row justify="space-between" align="middle" className="overview-header" gutter={[0, 12]}>
        <Col>
          <h2 className="overview-title">AR &amp; AP Reports</h2>
          <p className="overview-subtitle">
            {labels.label} · {rangeText(range)} · {accountsAr.length} receivable and {accountsAp.length} payable
            accounts with a balance
          </p>
        </Col>
        <Col>
          <RangePicker
            allowClear={false}
            value={[moment(range.from), moment(range.to)]}
            format="D MMM YYYY"
            disabledDate={(current) => !!current && current.valueOf() > moment().endOf("day").valueOf()}
            onChange={(values) => {
              const next = toWindow(values as any);
              if (next) setRange(next);
            }}
          />
        </Col>
      </Row>

      <h3 className="section-heading">Accounts receivable</h3>

      <Row gutter={[20, 20]}>
        <Col xs={24} xl={8}>
          <LedgerSideCard
            side="ar"
            title="Receivable exposure"
            icon={<ArrowDownOutlined style={{ color: CHART_COLORS.green }} />}
            currency="USD"
            stats={[
              { label: "Net collected", value: kpis.netCollected, tone: "in" },
              { label: "Current AR", value: kpis.currentAr },
              { label: "Overdue AR", value: kpis.overdueAr, tone: "due" },
            ]}
            aging={agingAr}
            activeBucket={null}
            onSelect={openAging("ar")}
          />
        </Col>
        <Col xs={24} xl={16}>
          <Card
            className="report-card cfo-ledger"
            bordered={false}
            title={
              <span className="report-card-title">
                <ArrowDownOutlined style={{ color: CHART_COLORS.green }} /> AR aging by account
              </span>
            }
            extra={<span className="report-card-date">Most exposed first</span>}
            bodyStyle={{ padding: 12 }}
          >
            <div className="scrollable-table">{agingTable("ar", accountsAr)}</div>
          </Card>
        </Col>
      </Row>

      <h3 className="section-heading">Accounts payable</h3>

      <Row gutter={[20, 20]}>
        <Col xs={24} xl={8}>
          <LedgerSideCard
            side="ap"
            title="Payable exposure"
            icon={<ArrowUpOutlined style={{ color: CHART_COLORS.orange }} />}
            tag={{ text: "AP mocked", hint: "No accounts-payable source exists in the platform yet - these figures are placeholders." }}
            currency="USD"
            stats={[
              { label: "Disbursed", value: kpis.disbursedAp, tone: "out" },
              { label: "Committed", value: kpis.committedAp },
              { label: "Overdue AP", value: kpis.overdueAp, tone: "due" },
            ]}
            aging={agingAp}
            activeBucket={null}
            onSelect={openAging("ap")}
          />
        </Col>
        <Col xs={24} xl={16}>
          <Card
            className="report-card cfo-ledger"
            bordered={false}
            title={
              <span className="report-card-title">
                <ArrowUpOutlined style={{ color: CHART_COLORS.orange }} /> AP aging by payee
              </span>
            }
            extra={<span className="report-card-date">Most exposed first</span>}
            bodyStyle={{ padding: 12 }}
          >
            <div className="scrollable-table">{agingTable("ap", accountsAp)}</div>
          </Card>
        </Col>
      </Row>

      <h3 className="section-heading">Receivables by {labels.navSingular.team.toLowerCase()}</h3>

      <Row gutter={[20, 20]}>
        <Col xs={24}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <TeamOutlined style={{ color: CHART_COLORS.blue }} /> Collected, current and overdue by{" "}
                {labels.navSingular.team.toLowerCase()}
              </span>
            }
            extra={
              <span className="cfo-chart__extra">
                <span className="report-card-date">Click a bar to open its transactions</span>
                <ChartViewToggle view={receivablesView} onChange={setReceivablesView} />
              </span>
            }
          >
            <ChartFrame<ProjectReceivables>
              view={receivablesView}
              legend={RECEIVABLE_SERIES}
              data={receivables}
              rowKey={(p) => p.projectId}
              ariaLabel={`Collected, current and overdue balances by ${labels.navSingular.team.toLowerCase()}`}
              columns={[
                { key: "name", title: labels.navSingular.team, render: (p) => p.name },
                { key: "collected", title: "Collected", align: "right", render: (p) => formatMoney(p.collected, "USD") },
                { key: "current", title: "Current AR", align: "right", render: (p) => formatMoney(p.current, "USD") },
                { key: "overdue", title: "Overdue AR", align: "right", render: (p) => formatMoney(p.overdue, "USD") },
                { key: "total", title: "Total", align: "right", render: (p) => formatMoney(p.total, "USD") },
                {
                  key: "collectedPct",
                  title: "Collected %",
                  align: "right",
                  render: (p) => <span className="cfo-pct">{p.total > 0 ? Math.round((p.collected / p.total) * 100) : 0}%</span>,
                },
              ]}
            >
              {(api) => (
                <StackedBarChart
                  items={receivableItems}
                  series={RECEIVABLE_SERIES}
                  currency="USD"
                  api={api}
                  selected={null}
                  onSelect={(id) => onOpenTransactions({ side: "ar", projectIds: [id], range })}
                />
              )}
            </ChartFrame>
          </Card>
        </Col>
      </Row>

      <h3 className="section-heading">Reminders</h3>

      <Row gutter={[20, 20]}>
        <Col xs={24} lg={10}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <BellOutlined style={{ color: "#FBAE16" }} /> Reminder cadence
              </span>
            }
            extra={<span className="report-card-date">Per configuration</span>}
          >
            <ul className="notification-list">
              {stageCounts.map(({ bucket, count }) => {
                const meta = DUNNING_META[bucket];
                return (
                  <li key={bucket}>
                    <span className={`notif-dot ${DOT_CLASS[meta.tone]}`} />
                    <div className="cfo-alert__body">
                      <p className="notif-title">{meta.label}</p>
                      <span className="notif-time">{bucket}</span>
                    </div>
                    <Badge
                      count={count}
                      showZero
                      style={{ backgroundColor: count > 0 ? STAGE_TONE[meta.tone] : "#C5D2E9" }}
                    />
                  </li>
                );
              })}
            </ul>
            <p className="report-footnote">
              Stages are read in hours; the stored configuration holds days (14 days = T+336h).
            </p>
          </Card>
        </Col>
        <Col xs={24} lg={14}>
          <AlertCenter alerts={ALERTS[domain]} now={NOW} onInspect={inspectAlert} onNotify={notifyFromAlert} />
        </Col>
      </Row>

      <ActionModals
        action={action}
        target={actionTarget}
        currency="USD"
        onClose={() => {
          setAction(null);
          setActionTarget(null);
        }}
      />
    </div>
  );
};

export default ReportsScreen;
