import React, { FC } from "react";

import { Discounts, PromoCode, Waiver } from "../../types";
import { newId } from "../../paymentConfig";
import {
  AmountRuleFields,
  DateField,
  FormRow,
  NullableNumberField,
  NumberField,
  RowList,
  SubHeading,
  SwitchField,
  TextField,
} from "../fields";
import { SectionProps } from "./types";

const DiscountsSection: FC<SectionProps> = ({ config, patch, disabled }) => {
  const d = config.discounts;
  const { currency } = config;
  const patchD = (changes: Partial<Discounts>) => patch({ discounts: { ...d, ...changes } });
  const patchSibling = (changes: Partial<Discounts["sibling"]>) =>
    patchD({ sibling: { ...d.sibling, ...changes } });

  return (
    <>
      <SwitchField
        label="Sibling discount"
        checked={d.sibling.enabled}
        disabled={disabled}
        onChange={(enabled) => patchSibling({ enabled })}
      />
      {d.sibling.enabled && (
        <FormRow>
          <AmountRuleFields
            value={d.sibling}
            currency={currency}
            valueLabel="Discount value"
            disabled={disabled}
            onChange={(rule) => patchSibling(rule)}
          />
          <NumberField
            label="Applies from child number"
            min={1}
            step={1}
            value={d.sibling.appliesFromChild}
            disabled={disabled}
            onChange={(appliesFromChild) => patchSibling({ appliesFromChild })}
          />
        </FormRow>
      )}

      <SubHeading>Waivers (staff, military, …)</SubHeading>
      <RowList<Waiver>
        items={d.waivers}
        disabled={disabled}
        addLabel="Add waiver"
        empty="No waivers."
        create={() => ({ _id: newId("waiver"), name: "", amountType: "percentage", value: 0 })}
        onChange={(waivers) => patchD({ waivers })}
        renderRow={(row, update) => (
          <FormRow>
            <TextField label="Waiver name" required value={row.name} disabled={disabled} onChange={(name) => update({ name })} />
            <AmountRuleFields value={row} currency={currency} required disabled={disabled} onChange={(rule) => update(rule)} />
          </FormRow>
        )}
      />

      <SubHeading>Promo codes</SubHeading>
      <RowList<PromoCode>
        items={d.promoCodes}
        disabled={disabled}
        addLabel="Add promo code"
        empty="No promo codes."
        create={() => ({ _id: newId("promo"), code: "", amountType: "percentage", value: 0, expiry: null, maxUses: null })}
        onChange={(promoCodes) => patchD({ promoCodes })}
        renderRow={(row, update) => (
          <FormRow>
            <TextField label="Code" required value={row.code} disabled={disabled} onChange={(code) => update({ code: code.toUpperCase() })} />
            <AmountRuleFields value={row} currency={currency} required disabled={disabled} onChange={(rule) => update(rule)} />
            <NullableNumberField label="Max uses" min={1} value={row.maxUses} disabled={disabled} onChange={(maxUses) => update({ maxUses })} />
            <DateField label="Expires" value={row.expiry} disabled={disabled} onChange={(expiry) => update({ expiry })} />
          </FormRow>
        )}
      />
    </>
  );
};

export default DiscountsSection;
