import moment from "moment";
import { RideRow, SortOrder } from "../types";

type Comparator = (a: RideRow, b: RideRow) => number;

/** "07:30" -> 450. Unparseable parts count as 0, matching the old behaviour. */
const toMinutes = (time?: string) => {
  const [hours, minutes] = `${time}`.split(":").map(Number);
  return (hours || 0) * 60 + (minutes || 0);
};

const isUnknownTime = (time?: string) =>
  !time || time === "Unknown Time" || time.trim() === "";

/** Empty values sort last regardless of direction. */
const compareText = (key: string): Comparator => (a, b) => {
  const aVal = `${a[key] ?? ""}`.trim();
  const bVal = `${b[key] ?? ""}`.trim();
  if (!aVal && !bVal) return 0;
  if (!aVal) return 1;
  if (!bVal) return -1;
  return aVal.localeCompare(bVal);
};

const parsePickupDate = (value?: string) => {
  if (!value) return undefined;
  const date = moment(value, "MMM-DD");
  return date.isValid() ? date.valueOf() : 0;
};

const COMPARATORS: Record<string, Comparator> = {
  patientName: (a, b) => a.patientName?.localeCompare(b?.patientName) || 0,
  driverNameFull: compareText("driverNameFull"),
  vehicleName: (a, b) => a.vehicleName?.localeCompare(b?.vehicleName) || 0,
  transferType: (a, b) => a.transferType?.localeCompare(b?.transferType) || 0,
  equipmentNeeded: compareText("equipmentNeeded"),
  description: compareText("description"),
  pickupTime: (a, b) => {
    const aUnknown = isUnknownTime(a.pickupTime);
    const bUnknown = isUnknownTime(b.pickupTime);
    if (aUnknown && bUnknown) return 0;
    if (aUnknown) return 1;
    if (bUnknown) return -1;
    return toMinutes(a.pickupTime) - toMinutes(b.pickupTime);
  },
  pickupDate: (a, b) => {
    const aDate = parsePickupDate(a.pickupDate);
    const bDate = parsePickupDate(b.pickupDate);
    if (aDate === undefined && bDate === undefined) return 0;
    if (aDate === undefined) return 1;
    if (bDate === undefined) return -1;
    return aDate - bDate;
  },
};

// When the user picks driver then time, date is slotted in between so rides
// group by driver and then order chronologically within each driver.
const GROUPING_PRIORITY: Record<string, number> = {
  driverNameFull: 1,
  pickupDate: 2,
  pickupTime: 3,
};

const resolveSortOrders = (sortOrders: SortOrder[]) => {
  const groupByDriver =
    sortOrders[0]?.columnKey === "driverNameFull" && sortOrders[1]?.columnKey === "pickupTime";
  if (!groupByDriver) return sortOrders;
  return [...sortOrders].sort(
    (a, b) => (GROUPING_PRIORITY[a.columnKey] ?? 999) - (GROUPING_PRIORITY[b.columnKey] ?? 999)
  );
};

const shiftStartMinutes = (row: RideRow): number | undefined => {
  const start = row.timeSlots?.[0]?.time?.[0];
  const time = typeof start === "string" ? start.split(" ")[1] : undefined;
  return time ? toMinutes(time) : undefined;
};

/**
 * Shift sort key: a shift row uses its start time, an assigned ride inherits
 * its driver's shift start (so it stays with its driver), and anything else
 * falls back to its own pickup time.
 */
const buildShiftTimeLookup = (data: RideRow[]) => {
  const driverShiftStart = new Map<string, number>();
  data.forEach((row) => {
    if (row.isShift && row.driverId && !driverShiftStart.has(row.driverId)) {
      const start = shiftStartMinutes(row);
      if (start !== undefined) driverShiftStart.set(row.driverId, start);
    }
  });

  return (row: RideRow): number => {
    if (row.isShift) return shiftStartMinutes(row) ?? Infinity;
    if (row.driverId && driverShiftStart.has(row.driverId)) {
      return driverShiftStart.get(row.driverId);
    }
    return row.pickupTime ? toMinutes(row.pickupTime) : Infinity;
  };
};

const sameDriverRides = (a: RideRow, b: RideRow) =>
  a.driverId && a.driverId === b.driverId && !a.isShift && !b.isShift;

const comparePickupWithinDriver = (a: RideRow, b: RideRow) =>
  a.pickupTime && b.pickupTime ? toMinutes(a.pickupTime) - toMinutes(b.pickupTime) : undefined;

export const applyMultiColumnSort = (data: RideRow[], sortOrders: SortOrder[]): RideRow[] => {
  if (!data?.length || !sortOrders?.length) return data;

  const orders = resolveSortOrders(sortOrders).filter(
    (so) => so.columnKey === "shift" || COMPARATORS[so.columnKey]
  );
  if (!orders.length) return data;
  const sortingByShift = orders.some((so) => so.columnKey === "shift");
  const shiftTime = sortingByShift ? buildShiftTimeLookup(data) : undefined;

  return [...data].sort((a, b) => {
    // Unless sorting by shift, shift rows keep their relative order at the end.
    if (!sortingByShift) {
      if (a.isShift && b.isShift) return 0;
      if (a.isShift) return 1;
      if (b.isShift) return -1;
    }

    for (const { columnKey, order } of orders) {
      const dir = (n: number) => (order === "ascend" ? n : -n);

      if (columnKey !== "shift") {
        const result = COMPARATORS[columnKey](a, b);
        if (result !== 0) return dir(result);
        continue;
      }

      const aTime = shiftTime(a);
      const bTime = shiftTime(b);

      if (aTime === Infinity && bTime === Infinity) {
        const within = sameDriverRides(a, b) ? comparePickupWithinDriver(a, b) : undefined;
        if (within) return dir(within);
        continue;
      }
      if (aTime === Infinity) return dir(1);
      if (bTime === Infinity) return dir(-1);
      if (aTime !== bTime) return dir(aTime - bTime);

      // Same shift start: a driver's shift row leads their rides.
      if (a.isShift && !b.isShift && a.driverId === b.driverId) return -1;
      if (b.isShift && !a.isShift && a.driverId === b.driverId) return 1;
      if (sameDriverRides(a, b)) {
        const within = comparePickupWithinDriver(a, b);
        if (within) return dir(within);
      }
    }
    return 0;
  });
};

/** Default order when no explicit sort is set: creation date, then pickup time. */
export const applyDefaultSort = (data: RideRow[]): RideRow[] =>
  [...data].sort((a, b) => {
    const aTime = new Date(a.createdAt).getTime();
    const bTime = new Date(b.createdAt).getTime();
    if (aTime === bTime || (isNaN(aTime) && isNaN(bTime))) {
      return a.pickupTime?.localeCompare(b.pickupTime) || 0;
    }
    return (aTime || 0) - (bTime || 0);
  });
