// Dedicated fetch client for the AI Scheduler service.
// Not built on the shared Api class: Api.fetch() merges custom headers into the
// top level of the fetch options (not under `headers`), so GET/PUT/DELETE calls
// silently drop them — and every scheduler call needs X-Org-Id.

const BASE =
  process.env.REACT_APP_AI_SCHEDULER_API || "https://ai.beam.live/api/scheduler";

export class SchedulerApiError extends Error {
  status: number;
  body: any;

  constructor(status: number, body: any) {
    super(
      (body && (body.detail || body.message)) || `Scheduler API error (HTTP ${status})`
    );
    this.name = "SchedulerApiError";
    this.status = status;
    this.body = body;
  }
}

export function getErrorMessage(e: any): string {
  if (e instanceof SchedulerApiError) return e.message;
  if (e?.message === "Failed to fetch") return "Scheduler service unreachable";
  return e?.message || "Unexpected scheduler error";
}

export async function schedulerRequest<T>(
  orgId: string,
  method: "GET" | "POST" | "PUT" | "DELETE",
  path: string,
  body?: unknown
): Promise<T> {
  const response = await fetch(`${BASE}${path}`, {
    method,
    headers: {
      "Content-Type": "application/json",
      "X-Org-Id": orgId,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });

  const text = await response.text();
  let parsed: any;
  try {
    parsed = text ? JSON.parse(text) : undefined;
  } catch {
    parsed = text;
  }

  if (!response.ok) {
    throw new SchedulerApiError(response.status, parsed);
  }
  return parsed as T;
}
