import React, { useEffect, useState } from "react";
import { Modal, Row, Col, Select, Slider, Button, Card } from "antd";
import CheckableTag from "antd/lib/tag/CheckableTag";
import "./index.scss";

import { formatForRedis } from "utils/appUtil";
import { useDispatch } from "react-redux";
import { GET_AGGREGATE } from "../../../reducers/reducer";

const { Option } = Select;

const FilterByModal = ({ isModalVisible, setIsModalVisible, onChange, filterOptions }) => {
  const [filters, setFilters] = useState<any>({
    // expertise: undefined,
    yearsOfExperience: filterOptions?.yearsOfExperience || { min: 0, max: 100 },
    // region: undefined,
    hourlyRate: filterOptions?.hourlyRate || { min: 0, max: 500 },
    dailyRate: filterOptions?.dailyRate || { min: 0, max: 5000 },
    availabilityDays: filterOptions?.availabilityDays || ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
    timeFilter: filterOptions?.timeFilter || undefined
  });
  const [timeFilterValue, setTimeFilterValue] = useState<any>(filterOptions?.timeFilter?.value);
  const [timeFilter, setTimeFilter] = useState<string>(filterOptions?.timeFilter?.key || undefined);
  const [timeFilterOptions, setTimeFilterOptions] = useState<any[]>([]);
  const [timeFilterLoading, setTimeFilterLoading] = useState<boolean>(false);

  const dispatch = useDispatch();
  
  const handleTimeFilter = (type) => {
    if (timeFilter === type) return;
    setTimeFilterValue(undefined);
    setTimeFilterOptions([]);
  //  getPageAggregateBds(type);
    getUsersByRole(type);
    setTimeFilter(type);
  };


  const getUsersByRole = (typeFilter) => {
   
    let searchQuery = `@serviceId:{'${formatForRedis(
      (localStorage.getItem('coachServiceId') || 'cudb-live')
    )}'}`;
  
    setTimeFilterLoading(true);
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          roleId: "$..admin.profile.roleId",
          coach: "$..persistent.static.coach",
          type: "$..persistent.static.coach.type",
          [typeFilter]: `$..persistent.static.coach.bio.location.attributes.${typeFilter}`,
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      groupBy: {
        properties: [`@${typeFilter}`],
        reducers: [
          {
            func: "COUNT",
            arguments: [],
            name: "count",
          },
        ],
      },
      filter: {
        expression: `exists(@roleId) && (@roleId === '${localStorage.getItem("coachRoleId")}') && exists(@type) && (@type === 'coach') && exists(@${typeFilter})`,
      },
      anyStatus: false,
    };

   
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          let options = [];
          response?.map((aggregateBy) => {
            if (aggregateBy[Object.keys(aggregateBy)[0]]) {
              options.push({
                label: aggregateBy[Object.keys(aggregateBy)[0]],
                value: aggregateBy[Object.keys(aggregateBy)[0]],
              });
            }
          });
          setTimeFilterOptions(options);

        setTimeFilterLoading(false);
        },
      })
    );
  };

  const days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

  const handleCancel = () => setIsModalVisible(false);
  const handleOk = () => {
    setIsModalVisible(false);
    onChange(filters);
  };

  const updateFilter = (key, value) => setFilters((prev) => ({ ...prev, [key]: value }));

  return (
    <Modal
      title="Filter Coaches"
      visible={isModalVisible}
      onOk={handleOk}
      onCancel={handleCancel}
      width="450px"
      className="beam-modal"
      footer={null}
      destroyOnClose
    >
  
  <div className="ml-2 mr-2">
      {/* <Row >
        <Col span={24}>
          <h5>Select Expertise</h5>
          <Select
            className="w-full small-select mt-1"
            placeholder="Select Expertise"
            onChange={(value) => updateFilter("expertise", value)}
          >
            <Option value="expertise1">Expertise 1</Option>
            <Option value="expertise2">Expertise 2</Option>
            <Option value="expertise3">Expertise 3</Option>
          </Select>
        </Col>
      </Row>

      <hr /> */}
      <Row >
        <Col span={24} >
          <h5>Years of Experience</h5>
          <Slider
            range
            max={100}
            value={[filters.yearsOfExperience.min, filters.yearsOfExperience.max]}
            onChange={(value) =>
              updateFilter("yearsOfExperience", { min: value[0], max: value[1] })
            }
          />
        </Col>
      </Row>

      <hr />

{/*    
      <Row >
        <Col span={24}>
          <h5>Select Region</h5>
          <Select
            className="w-full"
            showSearch
            placeholder="Type to search region"
            onChange={(value) => updateFilter("region", value)}
          >
            <Option value="region1">Region 1</Option>
            <Option value="region2">Region 2</Option>
            <Option value="region3">Region 3</Option>
          </Select>
        </Col>
      </Row>

      <hr /> */}

     
      <Row >
        <Col span={24}>
          <h5>Hourly Rate</h5>
          <Slider
            range
            max={100}
            value={[filters.hourlyRate.min, filters.hourlyRate.max]}
            onChange={(value) => updateFilter("hourlyRate", { min: value[0], max: value[1] })}
          />
        </Col>
      </Row>

      <hr />

    
      <Row >
        <Col span={24}>
          <h5>Daily Rate</h5>
          <Slider
            range
            max={500}
            value={[filters.dailyRate.min, filters.dailyRate.max]}
            onChange={(value) => updateFilter("dailyRate", { min: value[0], max: value[1] })}
          />
        </Col>
      </Row>

      <hr />

     
      <Row >
        <Col span={24}>
          <h5>Availability Days</h5>
          <div className="days-container">
            {days.map((day) => (
              <CheckableTag
                key={day}
                checked={filters.availabilityDays.includes(day)}
                onChange={(checked) => {
                  const updatedDays = checked
                    ? [...filters.availabilityDays, day]
                    : filters.availabilityDays.filter((d) => d !== day);
                  updateFilter("availabilityDays", updatedDays);
                }}
                className="day-tag"
              >
                {day}
              </CheckableTag>
            ))}
          </div>
        </Col>
      </Row>

      <Col className="gutter-row-1" sm={24} md={10}>
          <Card className="filter-card-coach mt-2">
            <Row className="d-flex flex-wrap mt-3" id="filters">
              {/* <div
              // sm={4}
              >
                <h5 className="mb-0">Filters</h5>
              </div> */}
              <div
                // sm={4}
                onClick={() => {
                  handleTimeFilter("state");
                }}
              >
                <Button
                  className={`beam-btn w-70 ${
                    timeFilter === "state" ? "green-btn cover" : ""
                  }`}
                >
                  State
                </Button>
              </div>
              <div
                // sm={4}
                onClick={() => {
                  handleTimeFilter("city");
                }}
              >
                <Button
                  className={`beam-btn w-70 ${
                    timeFilter === "city" ? "green-btn cover" : ""
                  }`}
                >
                  City
                </Button>
              </div>
              <div
                // sm={4}
                onClick={() => {
                  handleTimeFilter("county");
                }}
              >
                <Button
                  className={`beam-btn w-70 ${
                    timeFilter === "county" ? "green-btn cover" : ""
                  }`}
                >
                  County
                </Button>
              </div>
              <div
                // sm={4}
                onClick={() => {
                  handleTimeFilter("zip");
                }}
              >
                <Button
                  className={`beam-btn w-70 ${
                    timeFilter === "zip" ? "green-btn cover" : ""
                  }`}
                >
                  Zip
                </Button>
              </div>
            </Row>
            <Row className="mt-3">
              <Col xs={24}>
                <Select
                  className="w-full"
                  placeholder="Select ID"
                  loading={timeFilterLoading}
                  allowClear
                  options={timeFilterOptions}
                  value={timeFilterValue}
                  onChange={(value) => {
                    setTimeFilterValue(value);
                    updateFilter("timeFilter", {
                      key: timeFilter,
                      value
                    })
              //      setAreaPagePaths(value);
                  }}
                ></Select>
              </Col>
            </Row>
          </Card>
        </Col>
        

      <Row className="action-grp mt-3">
        <Col span={12} className="pr-2">
          <Button
            className="beam-btn orange-btn bordered w-full"
            onClick={() =>
              setFilters({
                expertise: undefined,
                yearsOfExperience: { min: 0, max: 100 },
                // region: undefined,
                hourlyRate: { min: 0, max: 500 },
                dailyRate: { min: 0, max: 5000 },
                availabilityDays: [],
                timeFilter: undefined
              })
            }
          >
            Reset
          </Button>
        </Col>
        <Col span={12} className="pl-2">
          <Button className="beam-btn green-btn cover w-full" onClick={handleOk}>
            Save
          </Button>
        </Col>
      </Row>
      </div>
    </Modal>
  );
};

export default FilterByModal;
