/** Invoice-ID project segment, per the V1001-MCLSC-INV2609-014 shape. */
const PROJECT_CODES: Record<string, string> = {
  "p-sp-01": "SPU12",
  "p-sp-02": "SPU14",
  "p-sp-03": "SPCMP",
  "p-sp-04": "SPTRN",
  "p-sp-05": "SPELT",
  "p-sp-06": "SPHOL",
  "p-sp-07": "SPSHW",
  "p-ed-01": "EDG07",
  "p-ed-02": "EDROB",
  "p-ed-03": "EDSTM",
  "p-ed-04": "EDMUS",
  "p-ed-05": "EDSCI",
  "p-ed-06": "EDTRP",
};

const projectOf = (id: string) =>
  PROJECTS.find((project) => project.id === id) as ProjectSummary;

/**
 * A ledger row before the derived fields are filled in. `outstanding` is
 * never written by hand — it falls out of the other figures so the grid
 * and the KPI cards cannot drift apart.
 */
interface RowSpec {
  side?: "ar" | "ap";
  projectId: string;
  entity: string;
  entityRole: string;
  fee: number;
  cadence?: LedgerRow["cadence"];
  adjustments?: Adjustment[];
  form?: LedgerRow["form"];
  method?: LedgerRow["method"];
  collected: number;
  pastDue?: number;
  pastDueHours?: number;
  refund?: RefundRecord;
  flags?: LedgerFlag[];
  /** How far back the row's last financial movement sits. */
  daysAgo: number;
}

const sumAdjustments = (adjustments: Adjustment[]) =>
  adjustments.reduce((acc, adjustment) => acc + adjustment.amount, 0);

const round2 = (value: number) => Number(value.toFixed(2));

const build = (specs: RowSpec[], domain: Domain): LedgerRow[] =>
  specs.map((spec, index) => {
    const project = projectOf(spec.projectId);
    const adjustments = spec.adjustments || [];
    const invoiced = round2(spec.fee - sumAdjustments(adjustments));
    const pastDue = spec.pastDue || 0;
    const refunded = spec.refund ? spec.refund.amount : 0;

    return {
      key: `${domain}-${index + 1}`,
      side: spec.side || "ar",

      projectId: spec.projectId,
      project: project.name,
      projectKind: project.kind,

      entityId: `${spec.projectId}-e${index + 1}`,
      entity: spec.entity,
      entityRole: spec.entityRole,

      currency: "USD",
      serviceFee: spec.fee,
      cadence: spec.cadence || "seasonal",
      adjustments,
      invoicedServiceFee: invoiced,

      form: spec.form || "card",
      method: spec.method || "installment",
      invoiceId: `V1001-${PROJECT_CODES[spec.projectId]}-INV2609-${String(
        index + 1
      ).padStart(3, "0")}`,

      collected: spec.collected,
      /**
       * Whatever the contract still owes. Arrears are reported separately
       * in `pastDue`, and a refunded amount is no longer collectable, so
       * both come off the invoiced figure.
       */
      outstanding: round2(
        Math.max(0, invoiced - spec.collected - pastDue - refunded)
      ),
      pastDue,
      pastDueHours: spec.pastDueHours || 0,

      refund: spec.refund || null,
      flags: spec.flags || [],

      lastActivityAt: NOW - spec.daysAgo * DAY,
    };
  });

