import React, { FC } from "react";
import { Form, Input, Radio } from "antd";

import { CardSettings, InvoiceSettings } from "../../types";
import { AddressFields, AmountRuleFields, FormRow, SubHeading, SwitchField, TextField } from "../fields";
import { SectionProps } from "./types";

const CollectionSection: FC<SectionProps> = ({ config, patch, disabled }) => {
  const invoice = config.invoice;
  const patchInvoice = (changes: Partial<InvoiceSettings>) =>
    patch({ invoice: { ...invoice, ...changes } });
  const patchBrand = (changes: Partial<InvoiceSettings["brand"]>) =>
    patchInvoice({ brand: { ...invoice.brand, ...changes } });
  const patchBank = (changes: Partial<InvoiceSettings["bank"]>) =>
    patchInvoice({ bank: { ...invoice.bank, ...changes } });
  const patchRecipient = (changes: Partial<InvoiceSettings["recipient"]>) =>
    patchInvoice({ recipient: { ...invoice.recipient, ...changes } });
  const patchCard = (changes: Partial<CardSettings>) =>
    patch({ card: { ...config.card, ...changes } });

  return (
    <>
      <Form.Item>
        <Radio.Group
          value={config.collectionMethod}
          disabled={disabled}
          onChange={(e) => patch({ collectionMethod: e.target.value })}
        >
          <Radio value="invoice">Invoice (a PDF invoice is shared with the customer, who pays it)</Radio>
          <Radio value="card">Credit Card (charged online)</Radio>
        </Radio.Group>
      </Form.Item>

      {config.collectionMethod === "invoice" && (
        <>
          <SubHeading>Brand &amp; contact</SubHeading>
          <FormRow>
            <TextField label="Brand / company name" required value={invoice.brand.name} disabled={disabled} onChange={(name) => patchBrand({ name })} />
            <TextField label="Website" value={invoice.brand.website} disabled={disabled} onChange={(website) => patchBrand({ website })} />
            <Form.Item label="Accent color">
              <Input
                value={invoice.brand.accentColor}
                disabled={disabled}
                placeholder="#1f6feb"
                onChange={(e) => patchBrand({ accentColor: e.target.value })}
                suffix={
                  <span
                    className="cfo-config-form__swatch"
                    style={{ background: invoice.brand.accentColor || "transparent" }}
                  />
                }
              />
            </Form.Item>
          </FormRow>
          <FormRow>
            <TextField label="Contact email" value={invoice.brand.contactEmail} disabled={disabled} onChange={(contactEmail) => patchBrand({ contactEmail })} />
            <TextField label="Contact phone (e.g. +15125550100)" value={invoice.brand.contactPhone} disabled={disabled} onChange={(contactPhone) => patchBrand({ contactPhone })} />
            <Form.Item label="Logo URL" extra="Printed in the invoice header.">
              <Input
                value={invoice.brand.logo ? invoice.brand.logo.url : ""}
                disabled={disabled}
                placeholder="https://…/logo.png"
                onChange={(e) =>
                  patchBrand({ logo: e.target.value ? { id: invoice.brand.logo ? invoice.brand.logo.id : "", url: e.target.value } : null })
                }
                suffix={
                  invoice.brand.logo && invoice.brand.logo.url ? (
                    <img className="cfo-config-form__logo" src={invoice.brand.logo.url} alt="" />
                  ) : undefined
                }
              />
            </Form.Item>
          </FormRow>

          <SubHeading>Billing address</SubHeading>
          <AddressFields
            value={invoice.billingAddress}
            disabled={disabled}
            onChange={(billingAddress) => patchInvoice({ billingAddress })}
          />

          <SubHeading>Bank &amp; remittance</SubHeading>
          <FormRow>
            <TextField label="Bank name" value={invoice.bank.bankName} disabled={disabled} onChange={(bankName) => patchBank({ bankName })} />
            <TextField label="Account holder" value={invoice.bank.accountHolder} disabled={disabled} onChange={(accountHolder) => patchBank({ accountHolder })} />
            <TextField label="Account number" value={invoice.bank.accountNumber} disabled={disabled} onChange={(accountNumber) => patchBank({ accountNumber })} />
          </FormRow>
          <FormRow>
            <TextField label="Routing number" value={invoice.bank.routingNumber} disabled={disabled} onChange={(routingNumber) => patchBank({ routingNumber })} />
            <TextField label="IBAN" value={invoice.bank.iban} disabled={disabled} onChange={(iban) => patchBank({ iban })} />
            <TextField label="SWIFT / BIC" value={invoice.bank.swift} disabled={disabled} onChange={(swift) => patchBank({ swift })} />
          </FormRow>
          <TextField
            label="Payment instructions printed on the invoice"
            rows={2}
            value={invoice.bank.instructions}
            disabled={disabled}
            onChange={(instructions) => patchBank({ instructions })}
          />

          <SubHeading hint="The party the invoice is addressed to. Leave empty when invoices are addressed to each payer.">
            Recipient (bill to)
          </SubHeading>
          <FormRow>
            <TextField label="Recipient name (company or person)" value={invoice.recipient.name} disabled={disabled} onChange={(name) => patchRecipient({ name })} />
            <TextField label="Attention / contact person" value={invoice.recipient.attention} disabled={disabled} onChange={(attention) => patchRecipient({ attention })} />
            <TextField label="Tax ID / VAT number" value={invoice.recipient.taxId} disabled={disabled} onChange={(taxId) => patchRecipient({ taxId })} />
          </FormRow>
          <FormRow>
            <TextField label="Recipient email" value={invoice.recipient.email} disabled={disabled} onChange={(email) => patchRecipient({ email })} />
            <TextField label="Recipient phone (e.g. +15125550100)" value={invoice.recipient.phone} disabled={disabled} onChange={(phone) => patchRecipient({ phone })} />
          </FormRow>
          <AddressFields
            searchLabel="Recipient address"
            value={invoice.recipient.address}
            disabled={disabled}
            onChange={(address) => patchRecipient({ address })}
          />
          <TextField
            label="Notes printed on the invoice (e.g. PO number, reference)"
            rows={2}
            value={invoice.recipient.notes}
            disabled={disabled}
            onChange={(notes) => patchRecipient({ notes })}
          />
        </>
      )}

      {config.collectionMethod === "card" && (
        <>
          <SwitchField
            label="Save the card on file for auto-pay"
            checked={config.card.saveCardForAutoPay}
            disabled={disabled}
            onChange={(saveCardForAutoPay) => patchCard({ saveCardForAutoPay })}
          />
          <SwitchField
            label="Card surcharge"
            checked={!!config.card.surcharge}
            disabled={disabled}
            onChange={(on) => patchCard({ surcharge: on ? { amountType: "fixed", value: 0 } : null })}
          />
          {config.card.surcharge && (
            <FormRow>
              <AmountRuleFields
                value={config.card.surcharge}
                currency={config.currency}
                valueLabel="Surcharge value"
                disabled={disabled}
                onChange={(surcharge) => patchCard({ surcharge })}
              />
            </FormRow>
          )}
        </>
      )}
    </>
  );
};

export default CollectionSection;
