import React from "react";
import { Form, FormInstance, Tooltip } from "antd";
import { scrollWithinContainer } from "../../common/ui";
import {
  SectionKey,
  sectionAnchor,
  sectionIndex,
  useSectionStatus,
} from "../../DispatchPanel/BookingProgress";
import { SCHEDULE_SECTION_ID } from "./ScheduleSection";
import { formatTime, summarizeSchedule, validateSchedule } from "./recurrence";

export const SUMMARY_BAR_CLASS = "mx-recurring-bar";

// Recurring bookings have no pickup date; the schedule decides the dates.
const NOT_USED = ["pickup date"];

type StepKey = SectionKey | "schedule";

const STEPS: { key: StepKey; title: string }[] = [
  { key: "patient", title: "Patient" },
  { key: "trip", title: "Trip" },
  { key: "billing", title: "Billing" },
  { key: "assignment", title: "Assignment" },
  { key: "schedule", title: "Schedule" },
];

export const SCHEDULE_STEP_INDEX = sectionIndex("assignment") + 1;

const anchorFor = (key: StepKey) =>
  key === "schedule" ? SCHEDULE_SECTION_ID : sectionAnchor(key);

/** Missing items per step, live from the form. */
export const useRecurringStatus = (form: FormInstance): Record<StepKey, string[]> => {
  const booking = useSectionStatus(form);
  const schedule = Form.useWatch("schedule", form);
  const scheduleError = validateSchedule(schedule);
  return {
    ...booking,
    trip: booking.trip.filter((label) => !NOT_USED.includes(label)),
    schedule: scheduleError ? [scheduleError.toLowerCase()] : [],
  };
};

/** Sticky header: step chips that jump to each section, plus a one-line summary. */
const RecurringSummaryBar = ({
  form,
  status,
}: {
  form: FormInstance;
  status: Record<StepKey, string[]>;
}) => {
  const firstName = Form.useWatch("patientFirstName", form);
  const lastName = Form.useWatch("patientLastName", form);
  const schedule = Form.useWatch("schedule", form);
  const pickupTime = formatTime(Form.useWatch("pickupTime", form));
  const patient = [firstName, lastName].filter(Boolean).join(" ");

  const scrollTo = (key: StepKey) =>
    scrollWithinContainer(document.getElementById(anchorFor(key)), {
      offset: 8,
      stickySelector: `.${SUMMARY_BAR_CLASS}`,
    });

  return (
    <div className={SUMMARY_BAR_CLASS}>
      <div className="mx-progress">
        {STEPS.map((step, i) => {
          const missing = status[step.key] || [];
          const done = missing.length === 0;
          return (
            <Tooltip key={step.key} title={done ? "Complete" : `Missing: ${missing.join(", ")}`}>
              <span
                className={`mx-progress__step ${done ? "mx-progress__step--done" : ""}`}
                onClick={() => scrollTo(step.key)}
              >
                <span className="mx-progress__index">{done ? "✓" : i + 1}</span>
                {step.title}
                {!done && <span className="mx-progress__missing">{missing.length} left</span>}
              </span>
            </Tooltip>
          );
        })}
      </div>
      <div className="mx-recurring-bar__summary">
        <strong>{patient || "New patient"}</strong>
        <span>{validateSchedule(schedule) ? "Schedule not set yet" : summarizeSchedule(schedule, pickupTime)}</span>
      </div>
    </div>
  );
};

export default RecurringSummaryBar;
