import { useCallback, useMemo } from "react";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { formatForRedis } from "utils/appUtil";
import {
  CREATE_SCHEDULE,
  DELETE_SCHEDULE,
  GET_AGGREGATE,
  UPDATE_SCHEDULE,
} from "../../../../../reducers/reducer";

// The schedule sagas and GET_AGGREGATE never call back when the request
// throws, so every call resolves `undefined` after this long instead.
export const REQUEST_TIMEOUT_MS = 20000;

/**
 * The schedule APIs resolve the parsed body on success and the error
 * message (a string, or undefined) on failure; timeouts resolve undefined.
 */
export const isScheduleOk = (response: any) =>
  response !== undefined && typeof response !== "string";

export const useScheduleApi = () => {
  const dispatch = useDispatch();
  return useMemo(() => {
    const call = (action: any, request: any) =>
      new Promise<any>((resolve) => {
        const timer = setTimeout(() => resolve(undefined), REQUEST_TIMEOUT_MS);
        dispatch(
          action({
            request,
            callback: (response) => {
              clearTimeout(timer);
              resolve(response);
            },
          })
        );
      });
    return {
      create: (request: any) => call(CREATE_SCHEDULE, request),
      update: (request: any) => call(UPDATE_SCHEDULE, request),
      remove: (request: any) => call(DELETE_SCHEDULE, request),
    };
  }, [dispatch]);
};

/** Raw schedule records: { id, data, patientFullName }. */
export interface RecurringRecord {
  id: string;
  data: any;
  patientFullName?: string;
}

/**
 * Loads the org's recurring schedules, optionally filtered by patient name.
 * Resolves undefined when the request fails or times out.
 */
export const useRecurringQuery = () => {
  const dispatch = useDispatch();
  const { projects } = useSelector((state: RootState) => state.auth);

  return useCallback(
    (filterText = "") =>
      new Promise<RecurringRecord[] | undefined>((resolve) => {
        let text = filterText.trim().toLowerCase();
        if (/[-']/.test(text)) text = formatForRedis(text);
        const request: any = {
          select: {
            index: {
              searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:schedule:status`,
              searchQuery: `@partitions:{'org\\:${formatForRedis(
                projects?.userServiceId
              )}}@partitions:{type\\:recurringEvent}`,
              searchOptions: "TIMEOUT 5000",
            },
            load: {
              id: "$.objectId",
              data: "$.data",
              patientFullName: "$..patientFullName",
            },
          },
          apply: { expression: "", name: "" },
          result: {},
          filter: {
            expression: text
              ? `exists(@patientFullName) && contains(lower(@patientFullName), '${text}')`
              : "",
          },
          anyStatus: false,
        };
        const timer = setTimeout(() => resolve(undefined), REQUEST_TIMEOUT_MS);
        dispatch(
          GET_AGGREGATE({
            requestData: request,
            callback: (response) => {
              clearTimeout(timer);
              resolve(Array.isArray(response) ? response : []);
            },
          })
        );
      }),
    [dispatch, projects?.userServiceId]
  );
};
