/**
 * This function takes a string argument and returns an integer.
 * If the given integer is null or empty or an invalid integer the provided default value is returned.
 * The default value if omitted or invalid is defaulted to 0.
 *
 * @param {string} mayBeNumber
 * @param {Number} defaultVal
 *
 * @returns {Number}
 */
export function getIntDefaultIfInValid(
  mayBeNumber: string,
  defaultVal: number = 0
): number {
  return mayBeNumber ? parseInt(mayBeNumber, 10) || 0 : defaultVal || 0;
}

export function generateUUID(): string {
  var d = new Date().getTime();
  var d2 =
    (typeof performance !== "undefined" &&
      performance.now &&
      performance.now() * 1000) ||
    0; //Time in microseconds since page-load or 0 if unsupported
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    var r = Math.random() * 16;
    if (d > 0) {
      r = (d + r) % 16 | 0;
      d = Math.floor(d / 16);
    } else {
      r = (d2 + r) % 16 | 0;
      d2 = Math.floor(d2 / 16);
    }
    return (c === "x" ? r : (r & 0x3) | 0x8).toString(16);
  });
}

export function popupCenter(url: string, title: string, w: number, h: number) {
  const dualScreenLeft =
    window.screenLeft !== undefined ? window.screenLeft : window.screenX;
  const dualScreenTop =
    window.screenTop !== undefined ? window.screenTop : window.screenY;

  const width = window.innerWidth
    ? window.innerWidth
    : document.documentElement.clientWidth;
  const height = window.innerHeight
    ? window.innerHeight
    : document.documentElement.clientHeight;

  const systemZoom = width / window.screen.availWidth;
  const left = (width - w) / 2 / systemZoom + dualScreenLeft;
  const top = (height - h) / 2 / systemZoom + dualScreenTop;

  const newWindow = window.open(
    url,
    title,
    "scrollbars=no,status=no,location=no,toolbar=no,menubar=no,width=" +
    w +
    ", height=" +
    h +
    ", top=" +
    top +
    ", left=" +
    left
  );
  if (newWindow) {
    newWindow.focus();
  }
}

export function formatForRedis(text: string) {
  return text.replace(/-|_|\+|\.|'/g, function (x) {
    return `\\${x}`;
  });
}

export function attributeKeyGenerator(attributeKey: string) {
  const temp = attributeKey.replace(/([A-Z])/g, " $1").toLowerCase();
  return temp.charAt(0).toUpperCase() + temp.slice(1);
}

function toCamelCase(inputString) {
  return inputString
    ?.toLowerCase()
    .replace(/(?:^\w|[A-Z]|\b\w)/g, function (word, index) {
      return index === 0 ? word.toLowerCase() : word.toUpperCase();
    })
    .replace(/\s+/g, "");
}

export function dateToCron(date: Date, daysOfWeek: string[]): string {
  const minutes = date.getMinutes();
  const hours = date.getHours();
  const daysOfWeekMap: { [key: string]: number } = {
    'Sunday': 0,
    'Monday': 1,
    'Tuesday': 2,
    'Wednesday': 3,
    'Thursday': 4,
    'Friday': 5,
    'Saturday': 6,
  };
  const dayOfWeekNumbers = daysOfWeek
    .map(day => daysOfWeekMap[day])
    .join(',');
  return `${minutes} ${hours} * 1-12 ${dayOfWeekNumbers}`;
}

export function cronToDate(cron: string): { date: Date, daysOfWeek: string[] } {
  const cronParts = cron.split(' ');
  if (cronParts.length !== 5) {
    throw new Error('Invalid cron format');
  }
  const [minutes, hours, dayOfMonth, month, dayOfWeek] = cronParts;
  const date = new Date();
  date.setMinutes(parseInt(minutes, 10));
  date.setHours(parseInt(hours, 10));
  const daysOfWeek = dayOfWeek.split(',').map((d) => {
    switch (parseInt(d, 10)) {
      case 0: return 'Sunday';
      case 1: return 'Monday';
      case 2: return 'Tuesday';
      case 3: return 'Wednesday';
      case 4: return 'Thursday';
      case 5: return 'Friday';
      case 6: return 'Saturday';
      default: return 'Invalid day';
    }
  });
  return { date, daysOfWeek };
}

const getFieldType = (originalName, obj, cadSections) => {
  let prefix = "";
  if (originalName.includes("-")) {
    const x = originalName.split("-");
    prefix = `${x?.[0]}.`;
    originalName = x?.[1];
  }
  let field = obj;
  cadSections?.map((section) => {
    section?.Cols?.map((col) => {
      if (col?.name === originalName) {
        field = col;
      }
    });
  });
  return field?.type;
}

export function formatObject(
  originalName: any,
  name: any,
  obj: any,
  cadSections: any,
  cadExtendedSections: any,
  type: string = ""
) {
  if (Array.isArray(obj)) {
    console.log('=-=-=-=-=-=-=-=-=- multiple-choice', { obj, name });
    if (cadExtendedSections?.account?.length && getFieldType(originalName, obj, cadExtendedSections?.account) === 'relation' || getFieldType(originalName, obj, cadExtendedSections?.account) === 'service') {
      return {
        [name]: [...obj]
      };
    }
    const formatted: any = obj.map((value, index) => {
      if (value.option) {
        return Array.isArray(value.option) ? value.option[0] : value.option;
      }
      if (typeof value === "string") {
        return value;
      }
      else {
        let tags = {};
        Object.keys(value).map((key) => {
          if (key !== "tag") {
            let keyName;
            if (type !== 'service') {
              if (value.tag) {
                keyName = `${value.tag[0].toLowerCase() + value.tag.slice(1)}${key[0].toUpperCase() + key.slice(1)
                  }`;
              } else {
                keyName = `${key[0].toLowerCase() + key.slice(1)}${index}`;
              }
            } else {
              keyName = key;
            }

            _.merge(
              tags,
              formatObject(
                key,
                keyName,
                value[key],
                cadSections,
                cadExtendedSections,
                type
              )
            );
          }
        });
        return tags;
      }
    });

    if (typeof formatted?.[0] === "string") {
      let prefix = "";
      if (originalName.includes("-")) {
        const x = originalName.split("-");
        prefix = `${x?.[0]}.`;
        originalName = x?.[1];
      }
      let field;
      cadSections?.map((section) => {
        section.Rows.map((row) => {
          row?.Cols?.map((col) => {
            if (col?.name === originalName) {
              field = col;
            }
          });
        });
      });
      if (name.includes("question")) {
        const fieldLabelFormatted = toCamelCase(field?.label);
        if (fieldLabelFormatted) name = fieldLabelFormatted;
      }
      const regex = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?~]/g;
      name = name.replace(regex, "");
      name = `${prefix}${name}`;
      return {
        //  [name]: formatted.join(", "),
        // NEED TO DISCUSS WITH MUZZ
        [name]: formatted,
      };
    } else {
      const result = _.assign.apply(_, formatted);
      return result;
    }
  } else {
    let prefix = "";
    if (originalName.includes("-")) {
      const x = originalName.split("-");
      prefix = `${x?.[0]}.`;
      originalName = x?.[1];
    }
    let field = obj;
    cadSections?.map((section) => {
      section.Rows.map((row) => {
        row?.Cols?.map((col) => {
          if (col?.name === originalName) {
            field = col;
          }
        });
      });
    });

    if (name?.includes("question")) {
      const fieldLabelFormatted = toCamelCase(field?.label);
      if (fieldLabelFormatted) name = fieldLabelFormatted;
    }
    const regex = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?~]/g;
    name = name.replace(regex, "");
    name = `${prefix}${name}`;


    // console.log('=-=-=-=-=-=-=-=-=- obj', { obj, name, field });
    if (obj && obj !== "") {
      switch (field?.type) {
        case "relation":
          return {
            [name]: [...obj]
          };
        case QuestionaireType.Service:
          return {
            [name]: obj
          };
        case "event":
          return {
            [name]: {
              type: "event",
              ...obj,
            },
          };
        case "customer-search":
          return {
            [name]: obj,
          };
        case "dispatchType":
          return {
            [name]: {
              type: "dispatchType",
              ...obj,
              date: obj.date
                ? moment(obj.date)?.format("MM/DD/YYYY")
                : undefined,
              dateTimestamp: obj.date
                ? moment(obj.date)?.toDate().getTime()
                : undefined,
              time: obj.time ? moment(obj.time)?.format("HH:mm") : undefined,
              timeTimestamp: obj.time
                ? moment(obj.time)?.toDate().getTime()
                : undefined,
            },
          };
        case "rideType":
          return {
            [name]: {
              type: "rideType",
              ...obj,
              date: obj.date
                ? moment(obj.date)?.format("MM/DD/YYYY")
                : undefined,
              dateTimestamp: obj.date
                ? moment(obj.date)?.toDate().getTime()
                : undefined,
              time: obj.time ? moment(obj.time)?.format("HH:mm") : undefined,
              timeTimestamp: obj.time
                ? moment(obj.time)?.toDate().getTime()
                : undefined,
            },
          };
        case "fareType":
          return {
            [name]: {
              type: "fareType",
              ...obj,
            },
          };
        case "notifyType":
          return {
            [name]: {
              type: "notifyType",
              ...obj,
            },
          };
        case "payType":
          return {
            [name]: {
              type: "payType",
              ...obj,
            },
          };
        case "fixed-asset":
          return {
            [name]: {
              type: "incident-location",
              attributes: {
                title: obj?.asset?.name,
              },
              coordinates: {
                lat: obj?.asset?.location?.coordinates?.[1],
                long: obj?.asset?.location?.coordinates?.[0],
              },
            },
          };
        case "responder":
        case "responder-extended":
          return [{
            [name]: {
              type: "responder",
              ...obj,
            },
          },
          obj?.selectedPayment && {
            'payment': {
              type: 'payment',
              scheduleType: 'fixed',
              amount: obj?.selectedPayment?.price
            }
          }
          ];
        case "vehicleType":
          return {
            [name]: {
              type: "vehicleType",
              ...obj,
            },
          };
        case "vehicle":
          return {
            [name]: {
              type: "vehicle",
              ...obj,
            },
          };
        case "location":
        case "gps":
          return {
            [name]: {
              attributes: {
                address: obj.label,
              },
              coordinates: obj?.value?.coordinates,
              type: "location",
            },
          };
        case "incident-location":
          return {
            [name]: {
              attributes: {
                address: obj.label,
              },
              coordinates: obj?.value?.coordinates,
              type: "incident-location",
            },
          };
        case "temp-location":
          return {
            [name]: {
              attributes: {
                address: obj.label,
              },
              coordinates: obj?.value?.coordinates,
              type: "temp-location",
            },
          };
        case "media":
        case "capture":
        case "file":
        case "signature":
          // if(Array.isArray(obj.files)){
          //   return obj?.files?.map((file, index)=>{
          //     return {
          //       [`${index + 1}.${name}`]: {
          //         ...file,
          //         type: "media",
          //       },
          //     };
          //   })
          // }
          // else{
          return {
            [name]: {
              files: obj.files,
              type: "media",
            },
          };
        // }
        case "project":
          return {
            [name]: {
              id: obj?.toString(),
              type: "project",
            },
          };
        case "date":
          if (moment(obj, "MMDDYYYY", true).isValid()) {
            return {
              [name]: moment(obj, "MMDDYYYY")?.format("MM/DD/YYYY"),
            };
          } else {
            return {
              [name]: moment(obj)?.format("MM/DD/YYYY"),
            };
          }
        case "time":
          return {
            [name]: moment(obj)?.format("HH:mm"),
          };
        case "multiple-choice":
          return {
            [name]: obj?.option || obj,
          };
        case "task-picker":
          return {
            [name]: {
              ...obj,
              type: "task",
            },
          };
        case "payment":
          return {
            [name]: {
              ...obj,
              type: "payment",
            },
          };
        case "category":
          return {
            [name]: obj?.subCategories?.toString()
          };
        case "calendar":
          return {
            [name]: {
              type: "dispatchType",
              value: "schedule",
              date: moment(obj.start)?.format("MM/DD/YYYY"),
              time: moment(obj.start)?.format("HH:mm"),
              dateTimestamp: moment(obj.start)?.toDate().getTime(),
              timeTimestamp: moment(obj.start)?.toDate().getTime(),
            },
          };
      }
    }
    return {
      [name]: obj?.toString(),
    };
  }
}

export const MIN_LAT = -85.05112878;
export const MAX_LAT = 85.05112878;
export const MIN_LON = -180;
export const MAX_LON = 180;

export const decodeGeoHash = (hash: number, bitDepth?: number) => {
  const bbox = decodeBBoxInt(hash, bitDepth);
  return convertBBoxToLatLong(bbox);
};

export const getBit = (bits: number, position: number): number => {
  return (bits / Math.pow(2, position)) & 0x01;
};

export const convertBBoxToLatLong = (bbox) => {
  const lat = (bbox[0] + bbox[2]) / 2;
  const lon = (bbox[1] + bbox[3]) / 2;
  const latErr = bbox[2] - lat;
  const lonErr = bbox[3] - lon;
  return {
    latitude: lat,
    longitude: lon,
    error: { latitude: latErr, longitude: lonErr },
  };
}

export const decodeBBoxInt = (hashInt: number, bitDepth = 52) => {
  let maxLat = MAX_LAT,
    minLat = MIN_LAT,
    maxLon = MAX_LON,
    minLon = MIN_LON;

  let latBit = 0,
    lonBit = 0;
  const step = bitDepth / 2;

  for (let i = 0; i < step; i++) {
    lonBit = getBit(hashInt, (step - i) * 2 - 1);
    latBit = getBit(hashInt, (step - i) * 2 - 2);

    if (latBit === 0) {
      maxLat = (maxLat + minLat) / 2;
    } else {
      minLat = (maxLat + minLat) / 2;
    }

    if (lonBit === 0) {
      maxLon = (maxLon + minLon) / 2;
    } else {
      minLon = (maxLon + minLon) / 2;
    }
  }
  return [minLat, minLon, maxLat, maxLon];
}

