import { useEffect, useMemo, useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { SocketTopics } from "constants/enums";
import {
  getAggregateBdsPublishTopic,
  getAggregateBdsSubscriptionTopic,
  getUsersSubscriptionTopic,
} from "hooks/MQTTConstants";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "reducers/reducer";
import { generateUUID } from "utils/appUtil";
import { wrapRequestPayload } from "../../../../../../helpers/request/RequestPayload";
import { AreaFilterType, EntityFilterType, SelectOption } from "../types";
import { buildAreaOptionsRequest, buildUsersByRoleRequest } from "../utils/queries";

const isUserFilter = (type: EntityFilterType) => type === "dispatcher" || type === "responder";

/** Options for the entity select (institute/vehicle/user) and the area select. */
export const useFilterOptions = (
  socket: ISocket,
  entityType: EntityFilterType,
  areaType: AreaFilterType
) => {
  const dispatch = useDispatch();
  const { encrypted_token, projects, adminUserRoles, accounts, userRequests } = useSelector(
    (state: RootState) => state.auth
  );
  const requestId = useRef(generateUUID()).current;
  const userRequestKey = `${requestId}:${entityType}`;

  const ctx = useMemo(
    () => ({
      userId: encrypted_token?.userId,
      adminUserId: projects?.adminUserId,
      userServiceId: projects?.userServiceId,
    }),
    [encrypted_token?.userId, projects?.adminUserId, projects?.userServiceId]
  );

  // Results of user searches arrive through these topics into `userRequests`.
  useEffect(() => {
    if (!projects?.adminUserId || !encrypted_token?.connectionId) return;
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getUsersSubscriptionTopic(encrypted_token.connectionId, projects.userServiceId)
    );
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getAggregateBdsSubscriptionTopic(encrypted_token.connectionId)
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.adminUserId, projects?.userServiceId, encrypted_token?.connectionId]);

  useEffect(() => {
    if (!isUserFilter(entityType) || !adminUserRoles || !encrypted_token?.connectionId) return;
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getAggregateBdsPublishTopic(encrypted_token.connectionId),
      wrapRequestPayload(
        buildUsersByRoleRequest(ctx, adminUserRoles, entityType as "dispatcher" | "responder"),
        userRequestKey
      )
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entityType, adminUserRoles, encrypted_token?.connectionId, ctx.userServiceId]);

  const entityOptions: SelectOption[] = useMemo(() => {
    switch (entityType) {
      case "project":
        return (accounts || []).map((a) => ({ label: a.info.name, value: a.objectId }));
      case "vehicle":
        return (projects?.projects || [])
          .filter((p) => p?.type === "vehicle")
          .map((p) => ({ label: p.name, value: p.id }));
      default:
        return (userRequests?.[userRequestKey] || []).map((u) => ({
          label: `${u.fullName}: ${u.email}`,
          value: u.id,
        }));
    }
  }, [entityType, accounts, projects?.projects, userRequests, userRequestKey]);

  const entityLoading = isUserFilter(entityType) && !userRequests?.[userRequestKey];

  const [areaOptions, setAreaOptions] = useState<SelectOption[]>([]);
  const [areaLoading, setAreaLoading] = useState(false);

  useEffect(() => {
    if (!ctx.userId) return;
    let cancelled = false;
    setAreaOptions([]);
    setAreaLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: buildAreaOptionsRequest(ctx, areaType),
        callback: (response) => {
          if (cancelled) return;
          setAreaLoading(false);
          const options = (response || [])
            .map((row) => row[Object.keys(row)[0]])
            .filter(Boolean)
            .map((value) => ({ label: value, value }));
          setAreaOptions(options);
        },
      })
    );
    return () => {
      cancelled = true;
    };
  }, [areaType, ctx, dispatch]);

  return { entityOptions, entityLoading, areaOptions, areaLoading };
};
