import { useCallback, useEffect, useRef, useState } from "react";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { ExtendedBioTopics, SocketTopics, UserTopics } from "constants/enums";
import useSocketActions from "../../../../../hooks/socketActions";
import { generateUUID } from "utils/appUtil";

// Shared data access for the admin-profile collections edited from the
// Pricing and Equipment screens:
//   /persistent/static/admin/<collection>/items/<uuid>

export type AdminCollection = "pricingManagement" | "equipmentManagement";

const REQUEST_TIMEOUT_MS = 15000;

export const collectionPath = (collection: AdminCollection) =>
  `/persistent/static/admin/${collection}`;

export const itemPath = (collection: AdminCollection, id: string) =>
  `${collectionPath(collection)}/items/${id}`;

/** Trimmed, case-insensitive key used for duplicate-name checks. */
export const nameKey = (name: any) => `${name ?? ""}`.trim().toLowerCase();

/** Stable per-mount id so our socket callbacks don't replace other components'. */
export const useComponentUuid = (componentUuid?: string) =>
  useRef(componentUuid || generateUUID()).current;

/**
 * Sends JSON-patch changes to the admin user. Resolves true when the reply
 * arrives and false if none arrives in time, so callers can always reset
 * their saving state.
 */
export const useAdminUserUpdate = (socket: ISocket, componentUuid?: string) => {
  const { projects } = useSelector((state: RootState) => state.auth);
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const uuid = useComponentUuid(componentUuid);
  const waiting = useRef<{ resolve: (ok: boolean) => void; timer: any }[]>([]);

  useEffect(
    () => () => {
      waiting.current.forEach((w) => clearTimeout(w.timer));
      waiting.current = [];
    },
    []
  );

  return useCallback(
    (changes: any[]) =>
      new Promise<boolean>((resolve) => {
        socket.subscribeToSurvey(
          SocketTopics.SurveyTopics,
          ExtendedBioTopics.UpdateUserBio,
          () => {
            const next = waiting.current.shift();
            if (next) {
              clearTimeout(next.timer);
              next.resolve(true);
            }
          },
          uuid
        );
        const entry = { resolve, timer: undefined as any };
        entry.timer = setTimeout(() => {
          waiting.current = waiting.current.filter((w) => w !== entry);
          resolve(false);
        }, REQUEST_TIMEOUT_MS);
        waiting.current.push(entry);
        socket.publishToServiceIdSurvey(
          SocketTopics.SurveyTopics,
          UserTopics.UpdateUser,
          updateUserRequestPayloadV2(projects?.adminUserId, changes),
          ExtendedBioTopics.UpdateUserBio,
          projects?.userServiceId
        );
      }),
    [socket, projects, uuid]
  );
};

export type LoadStatus = "idle" | "ok" | "error";

/**
 * Loads the items of an admin collection. GetUserBio is a shared topic, so
 * replies are only accepted while our own request is pending and when they
 * don't look like another collection (`isForeign`).
 */
export const useAdminItems = <T extends { _id: string; name?: string }>(
  socket: ISocket,
  collection: AdminCollection,
  isForeign: (item: any) => boolean,
  componentUuid?: string
) => {
  const { projects } = useSelector((state: RootState) => state.auth);
  const { getUserRequestPayload } = useSocketActions();
  const uuid = useComponentUuid(componentUuid);
  const [items, setItems] = useState<T[]>([]);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<LoadStatus>("idle");
  const pending = useRef(false);
  const timer = useRef<any>();
  const mounted = useRef(true);
  // undefined until a load succeeds; false when the collection has no `items` yet.
  const containerExists = useRef<boolean | undefined>(undefined);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(timer.current);
    };
  }, []);

  const reload = useCallback(() => {
    if (!projects?.adminUserId) return;
    pending.current = true;
    setLoading(true);
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.GetUserBio,
      (resp) => {
        if (!pending.current || !mounted.current) return;
        const raw = resp?.data?.[0]?.[0];
        const isObject = !!raw && typeof raw === "object" && !Array.isArray(raw);
        const list = (isObject ? Object.values(raw) : []).filter(
          (x: any) => x && typeof x === "object"
        ) as T[];
        if (list.some(isForeign)) return;
        pending.current = false;
        clearTimeout(timer.current);
        containerExists.current = isObject;
        setItems(list.sort((a, b) => `${a.name || ""}`.localeCompare(`${b.name || ""}`)));
        setStatus("ok");
        setLoading(false);
      },
      uuid
    );
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(
        projects?.adminUserId,
        "$",
        `$.persistent.static.admin.${collection}.items`
      ),
      ExtendedBioTopics.GetUserBio,
      projects?.userServiceId
    );
    clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      if (!pending.current || !mounted.current) return;
      pending.current = false;
      setLoading(false);
      setStatus("error");
    }, REQUEST_TIMEOUT_MS);
  }, [socket, projects, collection, uuid]);

  /**
   * Only true after a successful load that found no `items` container. Never
   * true while loading or after a failed load, so we can't wipe existing data.
   */
  const needsContainer = () =>
    !pending.current && status === "ok" && containerExists.current === false;

  const markContainerCreated = () => {
    containerExists.current = true;
  };

  return { items, loading, status, reload, needsContainer, markContainerCreated };
};
