import { useCallback } from "react";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";
import { RootState } from "reducers/rootReducer";
import { formatForRedis } from "utils/appUtil";
import { PERMISSION_TYPES, USER_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import type { PillTone } from "../../common/ui";

// Shared by the Driver and Dispatcher lists. Users are loaded from the
// userNameIndex and filtered by admin role; the driver editor and the
// profile screen read the same `user` object shape ({ id, status, live,
// roleId, schoolBus }).

export const REQUEST_TIMEOUT_MS = 15000;
export const SEARCH_MIN_LENGTH = 3;

export interface StaffRow {
  key: string;
  name: string;
  initials: string;
  customId?: string;
  beamId?: string;
  email?: string;
  phone?: string;
  roleName?: string;
  flag?: string;
  operationLocation?: string;
  licenseNumber?: string;
  licenseType?: string;
  licenseExpiry?: string;
  /** Raw aggregate record, passed to EditDriverModal as `student`. */
  user: any;
}

const hasPermission = (role: any, permission: string) =>
  (role?.permissions || []).indexOf(permission) !== -1;

/** Role filters per list, unchanged from the original screens. */
const ROLE_FILTERS: { [type: string]: (role: any) => boolean } = {
  [USER_TYPES.Responder]: (r) => hasPermission(r, PERMISSION_TYPES.OnMove),
  [USER_TYPES.Dispatcher]: (r) =>
    hasPermission(r, PERMISSION_TYPES.Cad) || hasPermission(r, PERMISSION_TYPES.Admin),
};

/** Full-text clause for first/last name and Beam ID (words shorter than 3 chars are ignored). */
const formatUserFilterText = (text: string) => {
  const words = text
    .trim()
    .split(" ")
    .filter((word) => word.length >= SEARCH_MIN_LENGTH)
    .map((word) => `*${formatForRedis(word)}*`);
  if (!words.length) return "";
  const names = words.map((w) => `@firstName:(${w})|@lastName:(${w})|`).join("");
  return `(${names}@beamIds:{${words.join("|")}})`;
};

export const getInitials = (name: string) =>
  name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase())
    .join("") || "?";

const fullName = (profile: any) =>
  [profile?.firstName, profile?.lastName].filter(Boolean).join(" ").trim();

export const toStaffRow = (x: any, roles: any[]): StaffRow => {
  const operationStart: any = Object.values(x?.schoolBus?.locationList || {}).find(
    (l: any) => l?.locationType === "operationStart"
  );
  const name = fullName(x?.live?.profile) || "Unnamed user";
  return {
    key: x?.id,
    name,
    initials: getInitials(name),
    customId: x?.live?.alternativeIds?.customId,
    beamId: x?.live?.beamIds?.[0],
    email: x?.live?.alternativeIds?.email,
    phone: x?.live?.alternativeIds?.phone,
    roleName: roles?.find((r) => r?._id === x?.roleId)?.name,
    flag: x?.status?.name,
    operationLocation: operationStart?.location?.attributes?.address,
    licenseNumber: x?.schoolBus?.license?.licenseNumber,
    licenseType: x?.schoolBus?.license?.licenseType,
    licenseExpiry: x?.schoolBus?.license?.expiryDate,
    user: x,
  };
};

/**
 * Loads users whose admin role matches `type`, optionally narrowed by a
 * server-side name/Beam ID search. Resolves null on timeout (GET_AGGREGATE
 * doesn't call back on errors).
 */
export const useStaffQuery = (type: string, userRole?: any) => {
  const dispatch = useDispatch();
  const { encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );

  return useCallback(
    (searchText = "") =>
      new Promise<StaffRow[] | null>((resolve) => {
        const roles: any[] = (adminUserRoles || []).filter(ROLE_FILTERS[type] || (() => false));
        // No matching roles would produce an invalid `() ` filter expression.
        if (!roles.length) {
          resolve([]);
          return;
        }
        let searchQuery = `@serviceId:{'${formatForRedis(projects?.userServiceId)}'}`;
        if (searchText.trim().length >= SEARCH_MIN_LENGTH) {
          searchQuery += formatUserFilterText(searchText);
        }
        const timer = setTimeout(() => resolve(null), REQUEST_TIMEOUT_MS);
        dispatch(
          GET_AGGREGATE({
            requestData: {
              select: {
                index: {
                  searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
                  searchQuery,
                  searchOptions: "TIMEOUT 5000",
                },
                list: {
                  objectIds: userRole === "driver" ? [encrypted_token?.userId] : undefined,
                },
                load: {
                  id: "$.objectId",
                  status: "$.nonpersistent.static.live.status",
                  live: "$.persistent.static.live",
                  roleId: "$..admin.profile.roleId",
                  schoolBus: "$..schoolBus",
                },
              },
              apply: { expression: "", name: "" },
              result: {},
              filter: {
                expression: `exists(@roleId) && (${roles
                  .map((r) => `@roleId === '${r._id}'`)
                  .join("||")})`,
              },
              anyStatus: false,
            },
            callback: (response: any[]) => {
              clearTimeout(timer);
              resolve(
                (response || [])
                  .map((x) => toStaffRow(x, adminUserRoles || []))
                  .sort((a, b) => a.name.localeCompare(b.name))
              );
            },
          })
        );
      }),
    [dispatch, type, userRole, encrypted_token?.userId, projects?.userServiceId, adminUserRoles]
  );
};

/** Flag colours written to /nonpersistent/static/live/status/name. */
export const FLAG_COLORS: { [name: string]: string } = {
  green: "#40CC52",
  amber: "#FBAE16",
  yellow: "#FBAE16",
  red: "#FF5F25",
  blue: "#508AFA",
  purple: "#463BBD",
  gray: "#91A5C6",
  grey: "#91A5C6",
  black: "#000000",
  brown: "#964B00",
  aqua: "#00FFFF",
  orange: "#FF8C00",
};

/** Stored as "MM/DD/YYYY HH:mm:ss" by the driver editor; older values may be ISO. */
export const LICENSE_EXPIRY_FORMAT = "MM/DD/YYYY HH:mm:ss";

export const parseLicenseExpiry = (raw: any) => {
  if (!raw) return undefined;
  const strict = moment(raw, LICENSE_EXPIRY_FORMAT, true);
  if (strict.isValid()) return strict;
  const loose = moment(new Date(raw));
  return loose.isValid() ? loose : undefined;
};

export const licenseStatus = (raw: any): { tone: PillTone; label: string } | undefined => {
  const expiry = parseLicenseExpiry(raw);
  if (!expiry) return undefined;
  const days = expiry.clone().startOf("day").diff(moment().startOf("day"), "days");
  if (days < 0) return { tone: "red", label: "Expired" };
  if (days <= 30) return { tone: "amber", label: `Expires in ${days} ${days === 1 ? "day" : "days"}` };
  return { tone: "green", label: `Valid to ${expiry.format("MMM D, YYYY")}` };
};
