import React, { FC, useEffect, useRef, useState } from "react";
import { Input, Button, Row, Col, Form } from "antd";
import { DownloadOutlined } from "@ant-design/icons";
import { QRCodeCanvas } from "qrcode.react";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import LocationInput from "common/LocationInput";
import { pushNotification } from "utils/notifications";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import {
  shareDispatchUrlPublishTopic,
  shareDispatchUrlSubscriptionTopic,
} from "hooks/MQTTConstants";

// Generates a booking link tied to a fixed pickup point (e.g. a hotel), shows
// it as a QR code to download, and sends it by email or SMS. Whoever opens
// the link gets that place prefilled — and locked — as their pickup.
const ShareLocationQr: FC<{ socket?: ISocket }> = ({ socket }) => {
  const { encrypted_token, projects } = useSelector(
    (state: RootState) => state.auth
  );
  const [name, setName] = useState("");
  const [address, setAddress] = useState<any>();
  const [url, setUrl] = useState<string>();
  const [generating, setGenerating] = useState(false);
  const [sending, setSending] = useState(false);
  const [channel, setChannel] = useState<"email" | "phone">("email");
  const [recipient, setRecipient] = useState("");
  const [error, setError] = useState("");
  const qrRef = useRef<HTMLDivElement>(null);
  // Generate and send share one reply topic; this says which one is waiting.
  const pendingRef = useRef<"generate" | "send" | undefined>();

  const connectionId = encrypted_token?.connectionId;

  useEffect(() => {
    if (!socket || !connectionId) return;
    const topic = shareDispatchUrlSubscriptionTopic(connectionId);
    const onReply = ({ response }: any) => {
      const pending = pendingRef.current;
      pendingRef.current = undefined;
      if (pending === "generate") {
        setGenerating(false);
        if (response?.status && response?.data?.url) {
          setUrl(response.data.url);
        } else {
          setError(response?.data?.details || "Could not generate QR code");
        }
      } else if (pending === "send") {
        setSending(false);
        if (response?.status) {
          pushNotification("Link shared successfully", "success", "TOP_CENTER", 1000);
          setRecipient("");
        } else {
          setError(response?.data?.details || "Could not share link");
        }
      }
    };
    socket.subscribeToEvent(SocketTopics.SubscribePageTopics, topic, onReply);
    return () => {
      socket.unSubscribeToEvent(SocketTopics.SubscribePageTopics, topic, onReply);
    };
  }, [socket, connectionId]);

  const buildLocation = () => ({
    name: name.trim(),
    address: address?.value?.attributes?.address || address?.label,
    coordinates: address?.value?.coordinates,
    placeId: address?.value?.place_id || undefined,
  });

  const validate = () => {
    if (!name.trim()) return "Please enter the location name";
    if (!address?.value?.coordinates) return "Please select the location address";
    return "";
  };

  const publish = (extra: any) => {
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      shareDispatchUrlPublishTopic(connectionId),
      wrapRequestPayload({
        userId: encrypted_token?.userId,
        cudbServiceId: projects?.userServiceId,
        location: buildLocation(),
        ...extra,
      })
    );
  };

  const generate = () => {
    const message = validate();
    setError(message);
    if (message) return;
    setGenerating(true);
    pendingRef.current = "generate";
    publish({ skipNotification: true });
  };

  const send = () => {
    const message =
      validate() ||
      (!recipient.trim()
        ? `Please enter ${channel === "email" ? "an email" : "a phone number"}`
        : "");
    setError(message);
    if (message) return;
    setSending(true);
    pendingRef.current = "send";
    publish({ notificationChannels: { [channel]: recipient.trim() } });
  };

  // The printable QR: the code with the place's name and address under it.
  const download = () => {
    const qrCanvas = qrRef.current?.querySelector("canvas");
    if (!qrCanvas) return;
    const padding = 24;
    const textHeight = 64;
    const canvas = document.createElement("canvas");
    canvas.width = qrCanvas.width + padding * 2;
    canvas.height = qrCanvas.height + padding * 2 + textHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(qrCanvas, padding, padding);
    ctx.fillStyle = "#000";
    ctx.textAlign = "center";
    const textTop = padding + qrCanvas.height + 28;
    ctx.font = "bold 20px Arial";
    ctx.fillText(name.trim(), canvas.width / 2, textTop, canvas.width - padding);
    ctx.font = "13px Arial";
    ctx.fillText(
      buildLocation().address || "",
      canvas.width / 2,
      textTop + 24,
      canvas.width - padding
    );

    const link = document.createElement("a");
    link.href = canvas.toDataURL("image/png");
    link.download = `${name.trim().replace(/[^\w-]+/g, "_") || "pickup"}_qr_code.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <Form layout="vertical" className="auth-form" requiredMark={false}>
      <Form.Item label="Location name" className="mb-3">
        <Input
          placeholder="e.g. Grand Plaza Hotel"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setUrl(undefined);
          }}
        />
      </Form.Item>
      <Form.Item label="Location address" className="mb-4">
        <LocationInput
          placeholder="Location address"
          value={address}
          onChange={(location) => {
            setAddress(location);
            setUrl(undefined);
          }}
        />
      </Form.Item>

      {!url && (
        <Button
          className="beam-btn green-btn cover w-full"
          loading={generating}
          onClick={generate}
        >
          Generate QR code
        </Button>
      )}

      {url && (
        <React.Fragment>
          <div ref={qrRef} className="d-flex flex-column align-items-center">
            <QRCodeCanvas value={url} size={220} level="M" />
            <p className="mt-2 mb-0">
              <strong>{name}</strong>
            </p>
          </div>
          <Button
            className="beam-btn w-full mt-3"
            icon={<DownloadOutlined />}
            onClick={download}
          >
            Download QR code
          </Button>

          <Row className="mt-4">
            <Col span={8}>
              <Button
                onClick={() => setChannel("email")}
                className={`beam-btn ${channel === "email" ? "green-btn cover" : ""}`}
              >
                Email
              </Button>
            </Col>
            <Col span={8}>
              <Button
                onClick={() => setChannel("phone")}
                className={`beam-btn ${channel === "phone" ? "green-btn cover" : ""}`}
              >
                SMS
              </Button>
            </Col>
          </Row>
          <Row className="mt-3">
            <Col span={24}>
              <Input
                type={channel === "email" ? "email" : "text"}
                placeholder={channel === "email" ? "Email" : "Phone number (include +)"}
                value={recipient}
                onChange={(e) => setRecipient(e.target.value)}
              />
            </Col>
          </Row>
          <Button
            className="beam-btn green-btn cover w-full mt-3"
            loading={sending}
            onClick={send}
          >
            Send
          </Button>
        </React.Fragment>
      )}

      {error && <p className="error mt-2">{error}</p>}
    </Form>
  );
};

export default ShareLocationQr;
