import React from "react";
import { Row, Col, Button } from "antd";
import { useDispatchPanel } from "../context";

const DispatchActions: React.FC = () => {
  const {
    ridePageId,
    webBooker,
    ridePageStatus,
    searching,
    blocked,
    estimatedFare,
    clearForm,
    setIsCancelModalVisible,
    submitPageId,
  } = useDispatchPanel();

  return (
    <Row className="action-grp mt-3">
      <Col span={ridePageId ? (webBooker ? 8 : 6) : 12} className="px-2">
        <Button
          className="beam-btn yellow-btn bordered w-full w-full"
          onClick={() => {
            clearForm();
            localStorage.removeItem("lastRideId");
          }}
        >
          Clear
        </Button>
      </Col>

      {ridePageId && (
        <Col span={webBooker ? 8 : 6} className="px-2">
          <Button
            className="beam-btn orange-btn bordered w-full w-full"
            onClick={() => {
              setIsCancelModalVisible(true);
            }}
            disabled={ridePageStatus === "black"}
          >
            Cancel
          </Button>
        </Col>
      )}

      <Col span={ridePageId ? (webBooker ? 8 : 6) : 12} className="pl-2">
        <Button
          className="beam-btn green-btn cover w-full"
          htmlType="submit"
          loading={searching}
          disabled={
            blocked ||
            ridePageStatus === "green" ||
            (webBooker && !estimatedFare)
          }
          onClick={() => {
            submitPageId.current = true;
          }}
        >
          {ridePageId ? "Update" : "Dispatch"}
        </Button>
      </Col>

      {ridePageId && !webBooker && (
        <Col span={6} className="pl-3">
          <Button
            className="beam-btn yellow-btn bordered w-full"
            htmlType="submit"
            loading={searching}
            disabled={blocked}
            onClick={() => {
              submitPageId.current = false;
            }}
          >
            New
          </Button>
        </Col>
      )}
    </Row>
  );
};

export default DispatchActions;
