/**
 * CFO Dashboard — sidebar menu.
 *
 * A private string enum rather than an entry in `utils/PageTypes`: the
 * CFO set is not shared with any other dashboard.
 *
 * Four rail entries instead of one per entity group: the finance screens
 * (Dashboard, Transactions, Reports) and a single Directory entry whose
 * screen picks the group (players, teams, events, coaches, staff,
 * vendors) with a select.
 */
import { Domain, EntityKind } from "./types";
import { DOMAIN_LABELS } from "./mockData";

export enum CFO_MENU_ITEMS {
  Dashboard = "dashboard",
  Transactions = "transactions",
  Reports = "reports",
  Directory = "directory",
}

export interface CfoMenuDef {
  id: CFO_MENU_ITEMS;
  /** SVG rendered through react-svg, like every other dashboard rail. */
  src: string;
  label: (domain: Domain) => string;
  hint: string;
}

export interface CfoMenuGroup {
  id: string;
  /** Small caption over the group; omitted for the first group. */
  caption?: string;
  items: CfoMenuDef[];
}

export const CFO_MENU_GROUPS: CfoMenuGroup[] = [
  {
    id: "finance",
    items: [
      {
        id: CFO_MENU_ITEMS.Dashboard,
        src: "/images/school-dashboard-icon.svg",
        label: () => "Dashboard",
        hint: "Revenue, profit, customer groups and exposure",
      },
      {
        id: CFO_MENU_ITEMS.Transactions,
        src: "/images/school-schedule-icon.svg",
        label: () => "Transactions",
        hint: "Every ledger line and the payment schedule",
      },
      {
        id: CFO_MENU_ITEMS.Reports,
        src: "/images/school-documents-icon.svg",
        label: () => "Reports",
        hint: "AR / AP aging, reminders and alerts",
      },
    ],
  },
  {
    id: "directory",
    caption: "People",
    items: [
      {
        id: CFO_MENU_ITEMS.Directory,
        src: "/images/school-students-icon.svg",
        label: () => "Directory",
        hint: "Players, teams, events, coaches, staff and vendors",
      },
    ],
  },
];

export const CFO_MENU_DEFS: CfoMenuDef[] = CFO_MENU_GROUPS.reduce<CfoMenuDef[]>(
  (all, group) => all.concat(group.items),
  []
);

export const menuLabel = (id: CFO_MENU_ITEMS, domain: Domain): string => {
  const def = CFO_MENU_DEFS.find((item) => item.id === id);
  return def ? def.label(domain) : id;
};

/* ------------------------------------------------------------------ */
/* Directory groups                                                    */
/* ------------------------------------------------------------------ */

export interface DirectoryOption {
  value: EntityKind;
  label: string;
}

export interface DirectoryGroup {
  label: string;
  options: DirectoryOption[];
}

/** The select inside the Directory screen: customers, then events, then payees. */
export const directoryGroups = (domain: Domain): DirectoryGroup[] => {
  const labels = DOMAIN_LABELS[domain];
  return [
    {
      label: "Customers",
      options: [
        { value: "players", label: labels.nav.players },
        { value: "teams", label: labels.nav.teams },
      ],
    },
    {
      label: "Events",
      options: [{ value: "events", label: "Events" }],
    },
    {
      label: "Payees",
      options: [
        { value: "coaches", label: labels.nav.coaches },
        { value: "staff", label: "Staff" },
        { value: "vendors", label: "Vendors" },
      ],
    },
  ];
};

export const directoryLabel = (kind: EntityKind, domain: Domain): string => {
  const match = directoryGroups(domain)
    .reduce<DirectoryOption[]>((all, group) => all.concat(group.options), [])
    .find((option) => option.value === kind);
  return match ? match.label : kind;
};
