import moment from "moment";
import { getShiftType } from "../shiftTypes";

/** Jobs closer than this to the new pickup are treated as a clash. */
export const JOB_BUFFER_MIN = 90;
const DAY_MIN = 24 * 60;

export type Availability =
  | "on-shift"
  | "on-call"
  | "available"
  | "off-shift"
  | "not-scheduled"
  | "time-off";

export const AVAILABILITY_META: Record<
  Availability,
  { label: string; tone: "green" | "amber" | "blue" | "gray" | "red"; base: number }
> = {
  "on-shift": { label: "On shift", tone: "green", base: 100 },
  "on-call": { label: "On call", tone: "amber", base: 70 },
  available: { label: "Available", tone: "blue", base: 60 },
  "off-shift": { label: "Off shift", tone: "gray", base: 20 },
  "not-scheduled": { label: "Not scheduled", tone: "gray", base: 10 },
  "time-off": { label: "Time off", tone: "red", base: -100 },
};

export interface DriverRecord {
  id: string;
  name: string;
  /** Same object ResponderInput builds; used to produce form values. */
  obj?: Record<string, any>;
}

export interface SlotInterval {
  /** Minutes from the start of the day; end may exceed 1440 for overnight. */
  start: number;
  end: number;
  shiftType: string;
  locationType?: string;
}

export interface DayJob {
  pageId: string;
  pickupMin?: number;
  label: string;
  status?: string;
  driverIds: string[];
  raw?: any;
}

export interface DriverEvaluation {
  driver: DriverRecord;
  availability: Availability;
  slots: SlotInterval[];
  coveringSlot?: SlotInterval;
  jobs: DayJob[];
  conflicts: DayJob[];
  scheduledHours: number;
  score: number;
  reasons: string[];
}

/** "09:30", "9:30 PM" -> minutes after midnight; anything else -> undefined. */
export const toMinutes = (time?: string): number | undefined => {
  const match = /^\s*(\d{1,2}):(\d{2})(?:\s*([ap])\.?m\.?)?/i.exec(time || "");
  if (!match) return undefined;
  let hours = Number(match[1]) % 24;
  const minutes = Number(match[2]);
  const meridiem = match[3]?.toLowerCase();
  if (meridiem === "p" && hours < 12) hours += 12;
  if (meridiem === "a" && hours === 12) hours = 0;
  return minutes < 60 ? hours * 60 + minutes : undefined;
};

export const formatMinutes = (min: number) => {
  const m = ((min % DAY_MIN) + DAY_MIN) % DAY_MIN;
  return `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
};

/**
 * Converts persisted slots ("YYYY-MM-DD HH:mm" pairs) into minute ranges on
 * the row's day. Like the roster editor (Shift/shiftUtils.parseSlot), only the
 * HH:mm and the start-to-end day offset are trusted: copied rosters can keep
 * the source week's dates inside `time`.
 */
export const toSlotIntervals = (slots: any[] = []): SlotInterval[] =>
  (Array.isArray(slots) ? slots : [])
    .map((s) => {
      const [rawStart, rawEnd] = Array.isArray(s?.time) ? s.time : [];
      if (typeof rawStart !== "string" || typeof rawEnd !== "string") return null;
      const [startDay, startHm] = rawStart.split(" ");
      const [endDay, endHm] = rawEnd.split(" ");
      const start = toMinutes(startHm);
      let end = toMinutes(endHm);
      if (start === undefined || end === undefined) return null;
      const dayOffset = moment(endDay, "YYYY-MM-DD").diff(moment(startDay, "YYYY-MM-DD"), "days");
      if (dayOffset >= 1) end += DAY_MIN;
      if (end <= start) end += DAY_MIN;
      return { start, end, shiftType: s.shiftType, locationType: s.locationType };
    })
    .filter(Boolean)
    .sort((a, b) => a.start - b.start);

/**
 * Several rosters may cover the same day. Merge every roster's row for the
 * day so no driver is lost (the dashboard used to read only the first).
 */
export const mergeShiftRows = (rosters: any[], day: number): Record<string, any[]> => {
  const key = moment(day).format("YYYY-MM-DD");
  const merged: Record<string, any[]> = {};
  rosters.forEach((roster) => {
    const rows = roster?.info?.shift ?? roster;
    if (!Array.isArray(rows)) return;
    const row = rows.find((r) => r?.key === key);
    if (!row) return;
    Object.keys(row).forEach((driverId) => {
      if (driverId === "key" || driverId === "date" || !Array.isArray(row[driverId])) return;
      merged[driverId] = [...(merged[driverId] || []), ...row[driverId]];
    });
  });
  return merged;
};

const describeSlot = (slot: SlotInterval) =>
  `${formatMinutes(slot.start)}–${formatMinutes(slot.end)}${slot.end > DAY_MIN ? " (+1d)" : ""}${
    slot.locationType ? ` · ${slot.locationType}` : ""
  }`;

export interface EvaluateOptions {
  slotsByDriver: Record<string, any[]>;
  timeOffDriverIds: Set<string>;
  jobs: DayJob[];
  day: number;
  /** Pickup of the job being assigned, if known. */
  pickupMin?: number;
  /** The job being assigned; excluded from its drivers' workload. */
  pageId?: string;
}

export const evaluateDriver = (
  driver: DriverRecord,
  { slotsByDriver, timeOffDriverIds, jobs, day, pickupMin, pageId }: EvaluateOptions
): DriverEvaluation => {
  const slots = toSlotIntervals(slotsByDriver[driver.id]);
  const driverJobs = jobs
    .filter((j) => j.pageId !== pageId && j.driverIds.includes(driver.id))
    .sort((a, b) => (a.pickupMin ?? DAY_MIN) - (b.pickupMin ?? DAY_MIN));

  const assignableSlots = slots.filter((s) => getShiftType(s.shiftType).assignable);
  const coveringSlot =
    pickupMin === undefined
      ? assignableSlots[0]
      : slots.find((s) => s.start <= pickupMin && pickupMin < s.end);

  let availability: Availability;
  if (timeOffDriverIds.has(driver.id)) availability = "time-off";
  else if (coveringSlot?.shiftType === "Shift") availability = "on-shift";
  else if (coveringSlot?.shiftType === "On Call") availability = "on-call";
  else if (coveringSlot?.shiftType === "Available") availability = "available";
  else if (slots.length > 0) availability = "off-shift";
  else availability = "not-scheduled";

  const conflicts =
    pickupMin === undefined
      ? []
      : driverJobs.filter(
          (j) => j.pickupMin !== undefined && Math.abs(j.pickupMin - pickupMin) < JOB_BUFFER_MIN
        );

  const reasons: string[] = [];
  if (availability === "time-off") reasons.push("Approved time off");
  if (coveringSlot) reasons.push(`${getShiftType(coveringSlot.shiftType).label} ${describeSlot(coveringSlot)}`);
  else if (slots.length > 0 && availability !== "time-off") {
    reasons.push(`Scheduled ${slots.map(describeSlot).join(", ")}`);
  }
  conflicts.forEach((c) =>
    reasons.push(`Clash: ${c.label} at ${formatMinutes(c.pickupMin)}`)
  );

  const scheduledHours =
    Math.round((slots.reduce((sum, s) => sum + (s.end - s.start), 0) / 60) * 10) / 10;

  const score =
    AVAILABILITY_META[availability].base - conflicts.length * 45 - driverJobs.length * 4;

  return {
    driver,
    availability,
    slots,
    coveringSlot,
    jobs: driverJobs,
    conflicts,
    scheduledHours,
    score,
    reasons,
  };
};

/** Best candidates first; ties broken by lighter workload, then name. */
export const rankDrivers = (drivers: DriverRecord[], options: EvaluateOptions) =>
  drivers
    .map((d) => evaluateDriver(d, options))
    .sort(
      (a, b) =>
        b.score - a.score ||
        a.jobs.length - b.jobs.length ||
        a.driver.name.localeCompare(b.driver.name)
    );

export const isRecommended = (e: DriverEvaluation) =>
  e.availability !== "time-off" &&
  e.conflicts.length === 0 &&
  ["on-shift", "on-call", "available"].includes(e.availability);

/** Turns a dashboard ride row (or search result) into a DayJob. */
export const rowToDayJob = (row: any): DayJob => {
  const profile = row?.action?.page?.profile || {};
  const secondary = (profile?.secondaryResponder?.responders || [])
    .map((r: any) => r?.id?.toString())
    .filter(Boolean);
  return {
    pageId: `${row.key}`,
    pickupMin: toMinutes(row.pickupTime),
    label: `${row.patientName || "Ride"}`.trim(),
    status: row.pageStatus,
    driverIds: [row.driverId, ...secondary].filter(Boolean),
    raw: row,
  };
};

/** Value shape ResponderInput emits for a single responder. */
export const toResponderValue = (driver: DriverRecord) => ({
  type: "responder",
  value: driver.id,
  id: driver.id,
  ...(driver.obj || {}),
  name: driver.obj?.name ?? driver.name,
  valueName: driver.obj?.name ?? driver.name,
});

/** Adds a driver to a ResponderInput `multiple` value. */
export const addToResponderList = (current: any, driver: DriverRecord) => {
  const responders = [...(current?.responders || [])];
  if (!responders.some((r) => `${r.id}` === driver.id)) {
    responders.push({ id: driver.id, ...(driver.obj || {}), name: driver.obj?.name ?? driver.name });
  }
  return { type: "responder", responders, values: responders.map((r) => `${r.id}`) };
};

/* ------------------------------------------------------------- planning */

export interface PlanProposal {
  job: DayJob;
  evaluation: DriverEvaluation;
}

export interface PlanResult {
  proposals: PlanProposal[];
  unplanned: { job: DayJob; reason: string }[];
}

/**
 * Suggests a driver for every unassigned job. Jobs are placed in pickup
 * order and each placement counts towards later ones, so the plan avoids
 * clashes and spreads work instead of giving everything to the top driver.
 * Deterministic: same inputs, same plan.
 */
export const planAssignments = (
  unassigned: DayJob[],
  drivers: DriverRecord[],
  options: Omit<EvaluateOptions, "pickupMin" | "pageId">
): PlanResult => {
  const planned: DayJob[] = [];
  const proposals: PlanProposal[] = [];
  const unplanned: PlanResult["unplanned"] = [];

  [...unassigned]
    .sort((a, b) => (a.pickupMin ?? Infinity) - (b.pickupMin ?? Infinity))
    .forEach((job) => {
      if (job.pickupMin === undefined) {
        unplanned.push({ job, reason: "No pickup time — can't check shifts or clashes" });
        return;
      }
      const ranked = rankDrivers(drivers, {
        ...options,
        jobs: [...options.jobs, ...planned],
        pickupMin: job.pickupMin,
        pageId: job.pageId,
      });
      const best = ranked.find(isRecommended);
      if (!best) {
        const onShiftThen = ranked.filter(
          (e) => e.coveringSlot && getShiftType(e.coveringSlot.shiftType).assignable
        );
        unplanned.push({
          job,
          reason: !onShiftThen.length
            ? "No driver is on shift at that time"
            : onShiftThen.every((e) => e.availability === "time-off")
            ? "Everyone on shift then has approved time off"
            : `Everyone on shift then already has a job within ${JOB_BUFFER_MIN} min`,
        });
        return;
      }
      proposals.push({ job, evaluation: best });
      planned.push({ ...job, driverIds: [best.driver.id] });
    });

  return { proposals, unplanned };
};
