import { formatForRedis } from "utils/appUtil";
import { colorRideStatusMapping } from "../constants";

// The filter mutators: each updates the relevant ref-based query fragment
// (pagePaths / pageIndex / loadPaths) and re-runs the page search.
export const useDashboardFilters = (d: any) => {
  const setProjectPagePaths = (value: any) => {
    d.setProjectFilterValue(value);
    switch (d.projectFilter) {
      case "project":
        d.pagePaths.current.project = value
          ? `exists(@iotAssetConfigId) && @iotAssetConfigId === '${value}'`
          : undefined;
        d.pagePaths.current.user = undefined;
        d.activeFiltersRef.current.project = value || undefined;
        d.activeFiltersRef.current.user = undefined;
        d.setProjectFilterLoading(true);
        break;
      case "manager":
      case "responder":
      case "dispatcher":
        d.loadPaths.current = [
          {
            key: "user",
            value: `$.persistent.static.metadata.members.users.${value}`,
          },
        ];
        d.pagePaths.current.user = value ? `exists(@user)` : undefined;
        d.pagePaths.current.project = undefined;
        d.activeFiltersRef.current.user = value || undefined;
        d.activeFiltersRef.current.project = undefined;
        d.setProjectFilterLoading(true);
        break;
    }

    d.searchPage();
  };

  const setStatusPagePaths = (value: any) => {
    d.pageIndex.current.status = value
      ? `@rideStatus:{${colorRideStatusMapping[value]}}`
      : "-@rideStatus:{advance}";
    d.pageIndex.current.phone = undefined;
    d.activeFiltersRef.current.phone = undefined;
    d.setStatusFilterLoading(true);
    d.selectedColor.current = value;
    d.setStatusSelected(value);
    d.searchPage();
  };

  const setPhonePagePaths = (value: any) => {
    d.pageIndex.current.phone = value
      ? `@passengerPhoneNumber:{${formatForRedis(value)}}`
      : undefined;
    d.activeFiltersRef.current.phone = value || undefined;
    d.setStatusFilterLoading(true);
    d.pageIndex.current.status = undefined;
    d.selectedColor.current = "lime";
    d.setStatusSelected("lime");
    d.searchPage();
  };

  const setShowHailPaths = (value: any) => {
    d.showHail.current = value;
    d.setStatusFilterLoading(true);
    d.searchPage();
  };

  const setAreaPagePaths = (value: any) => {
    d.setTimeFilterValue(value);
    d.pagePaths.current.time = value
      ? `exists(@${d.timeFilter}) && @${d.timeFilter} === '${value}'`
      : undefined;
    d.activeFiltersRef.current.area = value
      ? { field: d.timeFilter, value }
      : undefined;
    d.setTimeFilterLoading(true);

    d.searchPage();
  };

  const setTimePagePaths = (value: any) => {
    d.startDate.current = value.startTimestamp;
    d.endDate.current = value.endTimestamp;
    if (d.startDate.current && d.endDate.current) {
      const start = new Date(d.startDate.current);
      start.setHours(0);
      start.setMinutes(1);
      const end = new Date(d.endDate.current);
      end.setHours(23);
      end.setMinutes(59);
      d.pageIndex.current.time = `@createdAt:[${start.getTime()},+inf]@createdAt:[-inf, ${end.getTime()}]`;
      d.setTimeFilterLoading(true);
      d.searchPage();
    } else if (!d.startDate.current && !d.startDate.current) {
      d.pageIndex.current.time = "";
      d.setTimeFilterLoading(true);
      d.searchPage();
    }
  };

  const handleProjectFilter = (type: any) => {
    if (
      d.projectFilter === type ||
      !d.projects?.projects ||
      !d.adminRoles.current
    )
      return;
    d.setProjectFilterValue(undefined);
    d.setProjectFilterOptions([]);
    const options = [];
    switch (type) {
      case "project":
        d.projects?.projects?.map((project: any) => {
          options.push({ label: project.name, value: project.id });
        });
        d.setProjectFilterOptions(options);
        break;
      case "manager":
        d.getUsersByRole(d.adminRoles.current, "manager");
        break;
      case "dispatcher":
        d.getUsersByRole(d.adminRoles.current, "dispatcher");
        break;
      case "responder":
        d.getUsersByRole(d.adminRoles.current, "responder");
        break;
    }
    d.setProjectFilter(type);
  };

  const handleTimeFilter = (type: any) => {
    if (d.timeFilter === type) return;
    d.setTimeFilterValue(undefined);
    d.setTimeFilterOptions([]);
    d.getPageAggregateBds(type);
    d.setTimeFilter(type);
  };

  return {
    setProjectPagePaths,
    setStatusPagePaths,
    setPhonePagePaths,
    setShowHailPaths,
    setAreaPagePaths,
    setTimePagePaths,
    handleProjectFilter,
    handleTimeFilter,
  };
};
