import React from "react";

// The DispatchPanel is a large, tightly-coupled form. Rather than drill dozens
// of props through every sub-section, the orchestrator (index.tsx) assembles a
// single "bag" of state, setters, refs and actions and exposes it here. Section
// components read what they need via `useDispatchPanel()`.
export const DispatchPanelContext = React.createContext<any>(null);

export const useDispatchPanel = () => React.useContext(DispatchPanelContext);
