import React, { FC, useState, useEffect, useRef } from "react";
import { useHistory } from "react-router-dom";
import { Row, Col, Button, Collapse, Image, Checkbox } from "antd";
import { ReactSVG } from "react-svg";
import _ from "lodash";
import { Form } from "antd";
import { useLocation } from "react-router-dom";
import { QuestionaireType, SocketTopics, UserTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import {
  getProjectsRequestPublishTopic,
  getProjectsSubscriptionTopic,
  getRespondersSubscriptionTopic,
  getAssetsSubscriptionTopic,
  getCreateEventPageSubscriptionTopic,
  getCreateEventPagePublishTopic,
  getPageRequestPublishTopic,
  getPageSubscriptionTopic,
  getAdminRolesTopic,
  getSearchMessageSubscriptionTopic,
} from "hooks/MQTTConstants";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import {
  SET_CURRENT_PROJECT,
  SET_SUBMITTED,
  ADD_OTHER_LOCATION,
} from "reducers/reducer";
import { pushNotification } from "utils/notifications";
import moment from "moment";
import UploadCSVModal from "./UploadCSVModal";
import useSocketActions from "../../../../hooks/socketActions";
import MultiInput from "../../../../common/MultiInput";
import RenderFields from "../../../../common/RenderFields";
import { formatObject } from "utils/appUtil";
import csvDownload from "json-to-csv-export";
import { attributeKeyGenerator } from "utils/appUtil";
import ConfirmationModal from "../../../../common/Confirmation";
import { generateUUID } from "utils/appUtil";
import Geocode from "react-geocode";
import { GET_AGGREGATE, DECRYPT_TOKEN } from "../../../../reducers/reducer";
import { formatForRedis } from "utils/appUtil";

Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

const { Panel } = Collapse;

let customerSearchTimeout;
const DispatchPanel: FC<{
  socket: ISocket;
  params: any;
  date?: Date;
  selectedCustomerId?: string;
  selectedProjectId?: string;
  onEventCreated?: any;
}> = ({
  socket,
  params,
  date,
  onEventCreated,
  selectedCustomerId,
  selectedProjectId,
}) => {
    const [nine11Form] = Form.useForm();
    const [error, setError] = useState<string>("");
    const { screens, setScreens } = params;
    const { search } = useLocation();
    const history = useHistory();
    const { messages, encrypted_token, page } = useSelector(
      (state: RootState) => state.auth
    );
    const projects = useSelector(
      (state: RootState) => state.auth.projects,
      (a, b) => {
        return JSON.stringify(a) === JSON.stringify(b);
      }
    );
    const dispatch = useDispatch();
    const { getUserRequestPayload, handleMessages } = useSocketActions();
    const [adminRoles, setAdminRoles] = useState();
    const selectedResponders = useSelector(
      (state: RootState) => state.auth.selectedResponders,
      (a, b) => {
        return JSON.stringify(a) === JSON.stringify(b);
      }
    );
    const submitted = useSelector(
      (state: RootState) => state.auth.submitted,
      (a, b) => {
        return JSON.stringify(a) === JSON.stringify(b);
      }
    );

    const [searching, setSearching] = useState<boolean>(false);
    const [pageId, setPageId] = useState<any>();
    const [assistModalVisible, setAssistModalVisible] = useState<boolean>(false);
    const [assistPageId, setAssistPageId] = useState<any>();
    const [cadSections, setCadSections] = useState([]);
    const [conditionalCadSections, setConditionalCadSections] = useState([]);
    const [cadExtendedSections, setCadExtendedSections] = useState({
      what: [],
      account: [],
      where: [],
      who: [],
      when: [],
      why: [],
    });

    const [serviceData, setServiceData] = useState<any>([]);
    const sectionIcons = {
      what: "/images/pause-icon.svg",
      account: "/images/account-icon.svg",
      where: "/images/geo-icon.svg",
      who: "/images/user1-icon.svg",
      when: "/images/clock.svg",
      why: "/images/why.svg",
    };
    const [uploadModalVisible, setUploadModalVisible] = useState<boolean>(false);
    const [projectName, setProjectName] = useState<any>();
    const [formValues, setFormValues] = useState<any>();
    const formRef = useRef(null);
    const eventRequests = useRef([]);

    const onSubmitHandler = (values: Nine11Values) => {
      setUploadModalVisible(false);
      const userId = encrypted_token?.userId;
      const connectionId = encrypted_token?.connectionId;
      const projectId = selectedProjectId || encrypted_token?.projectId;
      if (serviceData?.value?.length) {
        values["undefined"][serviceData?.itemName[1]] = serviceData?.value;
      }
      const tempValues = { ...values };
      console.log("values", values);
      if (values["undefined"]) {
        values = { ...values["undefined"], ...values };
        delete values["undefined"];
      }
      const extendedAttributes = {};
      const indexPrefix = {};
      let i = 1;
      Object.keys(values).map((key) => {
        const tempValue = values[key];
        if (key.includes("-")) {
          let x = key.split("-");
          if (!indexPrefix?.[x?.[0]]) {
            indexPrefix[x[0]] = i;
            i++;
          }
          key = `${indexPrefix[x[0]]}-${x?.[1]}`;
        }
        const formattedObj = formatObject(
          key,
          key,
          tempValue,
          [...cadSections, ...conditionalCadSections],
          cadExtendedSections,
          serviceData?.value?.length ? QuestionaireType.Service : ""
        );
        if (Array.isArray(formattedObj)) {
          formattedObj?.map((obj) => {
            _.merge(extendedAttributes, obj);
          });
        } else {
          _.merge(extendedAttributes, formattedObj);
        }
      });
      const projectKey = Object.keys(extendedAttributes).find((key) => {
        return extendedAttributes?.[key]?.type === "project";
      });
      const selectedProject =
        projectId && projectId !== ""
          ? projectId
          : extendedAttributes[projectKey]?.id;
      const project = projects?.projects?.find((x) => {
        return x.id === selectedProject;
      });
      const sortedAttributes: any = {
        ...extendedAttributes,
        projectName: project?.name,
        [projectKey || "incidentType"]: {
          id: project?.id,
          type: "project",
        },
      };
      let responders = selectedResponders.map((responder) => {
        return {
          id: responder.id,
          beamId: responder.title,
        };
      });
      const tempResponder: any = Object.values(sortedAttributes).find(
        (value: any) => {
          return value?.type === "responder";
        }
      );
      if (tempResponder) {
        responders = [...responders, ...[tempResponder]];
      }
      // temp fix
      const title =
        projectName === "Lighthouse Beloved Community CLT Financial Application"
          ? sortedAttributes?.["1.applicantName"]
          : new Date().toLocaleString();
      let tasks;
      let invitation = true;
      let createdAt = new Date().getTime();
      Object.keys(sortedAttributes).map((key) => {
        if (sortedAttributes?.[key]?.type === "media") {
          sortedAttributes?.[key]?.files?.map((file, index) => {
            sortedAttributes[`${index + 1}.${key}`] = {
              ...file,
              type: "media",
            };
          });
          delete sortedAttributes[key];
        }
        if (sortedAttributes?.[key]?.type === "task") {
          tasks = sortedAttributes?.[key]?.tasks;
          delete sortedAttributes?.[key];
        }
        if (sortedAttributes?.[key]?.type === "dispatchType") {
          if (sortedAttributes?.[key]?.value === "schedule") {
            sortedAttributes["scheduleDate"] = sortedAttributes?.[key]?.date;
            sortedAttributes["scheduleTime"] = sortedAttributes?.[key]?.time;
            const incidentLocation = Object.keys(sortedAttributes).find((key) => {
              return sortedAttributes?.[key]?.type === "incident-location";
            });
            let eventDescription = "";
            Object.keys(sortedAttributes).map((key) => {
              if (typeof sortedAttributes[key] === "string") {
                eventDescription += `${attributeKeyGenerator(key)}: ${sortedAttributes[key]
                  }\n`;
              }
            });
            const tempDate = new Date(sortedAttributes?.[key]?.dateTimestamp);
            const tempTime = new Date(sortedAttributes?.[key]?.timeTimestamp);
            tempDate.setHours(tempTime.getHours());
            tempDate.setMinutes(tempTime.getMinutes());
            createdAt = tempDate.getTime();

            if (sortedAttributes.notify) {
              sortedAttributes["notify"].utcDateTime = new Date(
                tempDate.getTime()
              ).toUTCString();
              if (sortedAttributes?.notify?.customTime) {
                sortedAttributes.notify.notifyTime =
                  sortedAttributes.notify.customTime.toString();
              }
            }
            sortedAttributes["eventSchedule"] = {
              type: "event",
              dateTime: tempDate.getTime(),
              description: eventDescription,
              location: sortedAttributes[incidentLocation]?.coordinates
                ? {
                  attributes: sortedAttributes[incidentLocation]?.attributes,
                  coordinates: sortedAttributes[incidentLocation]?.coordinates,
                }
                : undefined,
              repeat: false,
              notifyTime: sortedAttributes.notify
                ? new Date(
                  tempDate.getTime() -
                  sortedAttributes?.notify?.notifyTime * 60000
                ).getTime()
                : undefined,
              notifyVia: sortedAttributes?.notify?.notifyVia,
              title,
            };
            invitation = false;
          } else {
            delete sortedAttributes.notify;
          }
          if (sortedAttributes?.[key]?.value === "deadline") {
            sortedAttributes["deadlineDate"] = sortedAttributes?.[key]?.date;
            sortedAttributes["deadlineTime"] = sortedAttributes?.[key]?.time;
            sortedAttributes["deadlineRSVP"] = {
              type: "rsvp",
              subType: "calendar",
              rsvpTitle: `Schedule visit before ${sortedAttributes?.[key]?.date} ${sortedAttributes?.[key]?.time} deadline`,
              startDate: new Date().getTime(),
              endDate: new Date(sortedAttributes?.[key]?.date).getTime(),
            };
            invitation = false;
          }
          delete sortedAttributes?.[key];
        }
      });

      console.log("sorted attributes", sortedAttributes);

      setError(undefined);
      setSearching(true);

      eventRequests.current = [];

      if (tasks && tasks.length > 0) {
        tasks.map((task) => {
          let incidentLocationKey = "taskEventLocation";
          Object.keys(sortedAttributes).map((key) => {
            if (sortedAttributes?.[key]?.type === "incident-location") {
              incidentLocationKey = key;
            }
          });
          if (
            (task.locationType === "manual" || task.locationType === "lbs") &&
            task.location?.coordinates?.lat &&
            task.location?.coordinates?.lat !== 0
          ) {
            sortedAttributes[incidentLocationKey] = {
              type: "incident-location",
              ...task.location,
            };
          }
          eventRequests.current.push({
            userId,
            attributes: {
              taskName: task.name,
              taskDescription: task.description,
              taskDate: task.dateTime
                ? moment(task.dateTime)?.format("MM/DD/YYYY")
                : undefined,
              taskTime: task.dateTime
                ? moment(task.dateTime)?.format("hh:mm A")
                : undefined,
              taskEvent: task.dateTime
                ? {
                  type: "event",
                  dateTime: new Date(task.dateTime).getTime(),
                  description: task.description,
                  location: sortedAttributes[incidentLocationKey]?.coordinates
                    ? {
                      attributes:
                        sortedAttributes[incidentLocationKey]?.attributes,
                      coordinates:
                        sortedAttributes[incidentLocationKey]?.coordinates,
                    }
                    : undefined,
                  repeat: false,
                  title: task.name,
                }
                : undefined,
              ...sortedAttributes,
              shareCustomerLink: true,
            },
            responders,
            assets: [],
            connectionId,
            pageId: undefined,
            submitted: true,
            unstructuredAttributes: { ...tempValues },
            title,
            invitation,
            assistPageId,
            createdAt,
            cudbServiceId: encrypted_token?.cudbServiceId,
            url: window.location.href,
          });
        });
      } else if (serviceData?.value?.length) {
        serviceData?.value.map((cat: any) => {
          cat?.services?.map((service: any, index) => {
            let eventMessage = '';
            Object.keys(service).map(key => {
              if (typeof service[key] === 'string') {
                eventMessage += `${attributeKeyGenerator(key)}: ${service[key]
                  }\n`;
              }
            });
            const temp = {
              ...cat,
              services: [
                { ...service }
              ]
            };
            const tempAttributes = {
              ...cat,
              ...service
            };
            delete tempAttributes?.['services'];

            eventRequests.current.push({
              userId,
              attributes: {
                serviceEvent: service.scheduleDate
                  ? {
                    type: "event",
                    dateTime: moment(`${service.scheduleDate} ${service.scheduleTime}`, "YYYY-MM-DD HH:mm").valueOf(),
                    description: eventMessage,
                    repeat: false,
                    title: `${service?.projectName} ${service?.scheduleDate} ${service?.scheduleTime}`,
                  }
                  : undefined,
                ...sortedAttributes,
                ...tempAttributes,

                shareCustomerLink: true
              },
              responders: service?.intakeStaffId ? [{
                id: service?.intakeStaffId,
                beamId: service?.intakeStaffBeamId,
              }] : service?.fulfillmentStaffId ? [{
                id: service?.fulfillmentStaffId,
                beamId: service?.fulfillmentStaffBeamId,
              }] : [],
              assets: [],
              connectionId,
              pageId,
              submitted: true,
              unstructuredAttributes: {
                "undefined": {
                  ...tempValues["undefined"],
                  [serviceData?.itemName[1]]: [{
                    ...temp
                  }]
                }
              },
              title: `${service?.projectName} ${service?.scheduleDate} ${service?.scheduleTime}`,
              invitation,
              assistPageId: undefined,
              createdAt: moment(`${service.scheduleDate} ${service.scheduleTime}`, "YYYY-MM-DD HH:mm").valueOf(),
              cudbServiceId: encrypted_token?.cudbServiceId,
              url: window.location.href,
            });
          })
        });
      } else {
        eventRequests.current.push({
          userId,
          attributes: { ...sortedAttributes, shareCustomerLink: true },
          responders,
          assets: [],
          connectionId,
          pageId,
          submitted: true,
          unstructuredAttributes: { ...tempValues },
          title,
          invitation,
          assistPageId,
          createdAt,
          cudbServiceId: encrypted_token?.cudbServiceId,
          url: window.location.href,
        });
      }

      eventRequests.current?.map((request) => {
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getCreateEventPagePublishTopic(connectionId),
          wrapRequestPayload(request)
        );
      });
    };

    useEffect(() => {
      if (submitted) {
        onEventCreated && onEventCreated(nine11Form.getFieldsValue());
        if (submitted.status) {
          setSearching(false);
          setPageId(undefined);
          setAssistPageId(undefined);
          pushNotification(
            "Event page submitted successfully",
            "success",
            "TOP_CENTER",
            1000
          );
          localStorage.removeItem("form");
          localStorage.removeItem("active");
          setTimeout(() => {
            nine11Form.resetFields();
          }, 500);
          setScreens({
            ...screens,
            map: false,
          });
          const query = new URLSearchParams(search);
          query.delete("pageId");
          history.replace({
            search: query.toString(),
          });
          dispatch({ type: SET_SUBMITTED, payload: false });
        } else if (submitted.status === false) {
          setSearching(false);
          pushNotification(
            submitted?.data?.details || "Request failed",
            "error",
            "TOP_CENTER",
            3000
          );
          dispatch({ type: "SET_ONLY_SUBMITTED", payload: false });
        }
      }
    }, [
      dispatch,
      history,
      nine11Form,
      screens,
      search,
      searching,
      setScreens,
      submitted,
    ]);

    useEffect(() => {
      if (projects?.sections) {
        // const query = new URLSearchParams(search);
        const projectId = selectedProjectId || encrypted_token?.projectId;
        const project = projects?.projects?.find((x) => {
          return x.id === projectId;
        });
        setProjectName(project?.name);

        const assistPage = encrypted_token?.assistPageId;
        const connectionId = encrypted_token?.connectionId;
        if (assistPage) {
          setAssistModalVisible(true);
          socket.subscribeToEvent(
            SocketTopics.SubscribePageTopics,
            getSearchMessageSubscriptionTopic(assistPage, connectionId)
          );
          getMessages(assistPage);
        }
        let sections =
          projectId && projectId !== ""
            ? projects?.sections?.[1]?.[0]?.[projectId] || []
            : projects?.sections?.[0]?.[0];
        let conditionalSections =
          sections.filter((section) => {
            return section.conditional === true;
          }) || [];

        sections =
          sections.filter((section) => {
            return (
              section.conditional === undefined || section.conditional === false
            );
          }) || [];
        setCadSections(sections);
        setConditionalCadSections(conditionalSections);
        let dispatchTypeField;
        let customerSearchField;
        sections.map((section) => {
          section?.Rows.map((row) => {
            row?.Cols?.map((col) => {
              if (col?.type === "dispatchType") {
                dispatchTypeField = col;
              }
              if (col?.type === "customer-search") {
                customerSearchField = col;
              }
            });
          });
        });
        if (dispatchTypeField && date) {
          nine11Form.setFieldsValue({
            undefined: {
              [dispatchTypeField.name]: {
                type: "dispatchType",
                value: "schedule",
                date,
                time: date,
              },
            },
          });
        }
        if (customerSearchField && selectedCustomerId) {
          getCustomer({
            itemName: [customerSearchField.name],
            value: selectedCustomerId,
          });
        }
      }
      if (projects?.adminUserId) {
        getAdminRoles(projects?.adminUserId, projects?.userServiceId);
      }
      const query = new URLSearchParams(search);
      const tempPageId = query.get("pageId");
      if (tempPageId) {
        setPageId(tempPageId);
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getPageRequestPublishTopic(encrypted_token?.connectionId),
          wrapRequestPayload(
            {
              objectId: tempPageId,
              paths: ["$"],
              returnPaths: ["$"],
            },
            tempPageId
          )
        );
      }
    }, [projects]);

    const getAdminRoles = (adminUserId, cudbServiceId) => {
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.SearchInUser,
        getUserRequestPayload(adminUserId, "$", "$..role"),
        getAdminRolesTopic(encrypted_token?.connectionId),
        cudbServiceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        getAdminRolesTopic(encrypted_token?.connectionId),
        (response) => {
          setAdminRoles(response.data?.[0]?.[0]);
        }
      );
    };

    useEffect(() => {
      if (socket.client) {
        const query = new URLSearchParams(search);
        const userId = query.get("userId");
        const connectionId = query.get("connectionId");
        const projectId = query.get("projectId");
        const pageId = query.get("pageId");
        const assistPageId = query.get("assistPageId");
        const cudbServiceId = query.get("cudbServiceId");
        const token = query.get("token");
        if (token) {
          dispatch(
            DECRYPT_TOKEN({
              data: { payload: token },
              callback: (data) => { },
            })
          );
        } else {
          dispatch({
            type: "ADD_ENCRYPTED_TOKEN",
            payload: {
              connectionId,
              userId,
              projectId,
              pageId,
              assistPageId,
              cudbServiceId,
            },
          });
        }
      }
    }, [search, socket.client]);

    useEffect(() => {
      if (encrypted_token) {
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          getProjectsSubscriptionTopic(encrypted_token?.connectionId)
        );
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          getRespondersSubscriptionTopic(encrypted_token?.connectionId)
        );
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          getAssetsSubscriptionTopic(encrypted_token?.connectionId)
        );
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          getCreateEventPageSubscriptionTopic(encrypted_token?.connectionId)
        );
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          getPageSubscriptionTopic(encrypted_token?.connectionId)
        );
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getProjectsRequestPublishTopic(encrypted_token?.connectionId),
          wrapRequestPayload({
            userId: encrypted_token?.userId,
            cudbServiceId: encrypted_token?.cudbServiceId,
          })
        );
      }
    }, [encrypted_token]);

    useEffect(() => {
      if (page) {
        const query = new URLSearchParams(search);
        const pageId = query.get("pageId");
        console.log("page here", page);
        if (pageId !== page.objectId && !page.dashboard) return;
        nine11Form.setFieldsValue(
          page?.persistent?.static?.profile?.unstructuredAttributes ?? {}
        );
        setPageId(page.objectId);
      }
    }, [page]);

    const onProjectChange = (projectId) => {
      dispatch({ type: SET_CURRENT_PROJECT, payload: projectId });
      const values = nine11Form.getFieldsValue();
      Object.keys(values["undefined"] || {}).map((key) => {
        if (values["undefined"]?.[key]?.type === "task-picker") {
          nine11Form.setFieldsValue({
            undefined: {
              ...values["undefined"],
              [key]: undefined,
            },
          });
        }
      });
    };

    const getCustomer = (value) => {
      const { itemName, value: customer } = value;
      if (customer) {
        const customerObj = customer?.info?.customer;
        Object.keys(customerObj).map((x) => {
          if (customerObj?.[x]?.type === "location") {
            customerObj[x] = {
              type: "location",
              label: customerObj?.[x]?.attributes?.address,
              value: {
                description: customerObj?.[x]?.attributes?.address,
                placeId: "",
                coordinates: customerObj?.[x]?.coordinates,
              },
            };
          }
        });
        nine11Form.setFieldsValue({
          undefined: {
            [itemName?.[0] || itemName?.[1]]:
              customer?.info?.id,
            ...customer?.info?.customer,
            relation: customer?.info?.customer?.relation || []
          },
        });
      }
    };

    const getMessages = (pageId) => {
      const requestId = generateUUID();
      localStorage.setItem("requestId", requestId);
      localStorage.setItem("requestService", "summary");
      const messageRequest: any = {
        select: {
          index: {
            searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:message:createdAt`,
            searchQuery: `@pageId:{${pageId.toString()}}@type:{'place'}`,
            searchOptions: "TIMEOUT 100",
          },
          load: { object: "$" },
        },
        operations: [
          {
            sortBy: {
              properties: [
                {
                  field: "@createdAt",
                  order: "DESC",
                },
              ],
            },
          },
        ],
        result: {
          pagination: {
            offset: 0,
            limit: 1,
          },
        },
        sortBy: {
          properties: [
            {
              field: "@createdAt",
              order: "DESC",
            },
          ],
          max: 10000,
        },
      };
      dispatch(
        GET_AGGREGATE({
          requestData: messageRequest,
          callback: (response) => {
            console.log("message response", response);
            handleMessages(requestId, response);
          },
        })
      );
    };

    const reverseGeocode = (locationFieldName: string, marker: any) => {
      Geocode.fromLatLng(marker.coordinates.lat, marker.coordinates.long).then(
        (response) => {
          const values = nine11Form.getFieldsValue();
          nine11Form.setFieldsValue({
            undefined: {
              ...values["undefined"],
              [locationFieldName]: {
                label: marker.attributes.address,
                value: {
                  ...response?.results?.[0],
                  coordinates: marker.coordinates,
                },
                type: "incident-location",
              },
            },
          });
          addOtherLocation({
            [locationFieldName]: {
              label: marker.attributes.address,
              value: {
                ...response?.results?.[0],
                coordinates: marker.coordinates,
              },
              type: "incident-location",
            },
          });
          setScreens({
            ...screens,
            map: true,
            form: window.innerWidth >= 700,
          });
        },
        (error) => {
          console.error(error);
        }
      );
    };

    useEffect(() => {
      if (messages && messages.length > 0) {
        let locationField;
        Object.keys(cadExtendedSections).map((section) => {
          cadExtendedSections[section].map((row) => {
            row?.Cols?.map((col) => {
              if (col?.type === "incident-location") {
                locationField = col;
              }
            });
          });
        });
        cadSections?.map((section) => {
          section.Rows.map((row) => {
            row?.Cols?.map((col) => {
              if (col?.type === "incident-location") {
                locationField = col;
              }
            });
          });
        });
        if (locationField) {
          reverseGeocode(locationField?.name, messages?.[0]?.data);
        }
      }
    }, [messages]);

    const addOtherLocation = (location) => {
      dispatch({ type: ADD_OTHER_LOCATION, payload: location });

      nine11Form.setFieldsValue({
        incidentType: undefined,
      });

      dispatch({
        type: SET_CURRENT_PROJECT,
        payload: undefined,
      });
    };
    const onServiceChange = (data) => {
      setServiceData(data);
    }

    const generateCSVFile = () => {
      const headers: string[] = ["title", "location-lat", "location-long"];
      // const query = new URLSearchParams(search);
      const projectId = selectedProjectId || encrypted_token?.projectId;
      let sections =
        projectId && projectId !== ""
          ? projects?.sections?.[1]?.[0]?.[projectId] || []
          : projects?.sections?.[0]?.[0];
      sections.forEach((section: any) => {
        section.Rows.forEach((row: any) => {
          row.Cols.forEach((col: any) => {
            headers.push(col.name);
          });
        });
      });
      headers.push("dispatchType");
      headers.push("dispatchDate");
      headers.push("dispatchTime");
      headers.push("&nbsp;");
      const dataToConvert = {
        data: [],
        filename: "event_template",
        delimiter: ",",
        headers: headers,
      };
      csvDownload(dataToConvert);
    };

    return (
      <div className="main-column ride-dispatch-panel mobile-responsive mr-4">
        {uploadModalVisible && (
          <UploadCSVModal
            onClose={() => {
              setUploadModalVisible(false);
            }}
            adminRoles={adminRoles}
            onSubmitHandler={onSubmitHandler}
          />
        )}
        <div className="main-content">
          <Form
            className="auth-form"
            name="register-form"
            initialValues={JSON.parse(localStorage.getItem("form") || "{}")}
            // initialValues={{}}
            id="register-form"
            layout="vertical"
            form={nine11Form}
            onFinish={onSubmitHandler}
            requiredMark={false}
            onValuesChange={(value, allValues) => {
              localStorage.setItem("form", JSON.stringify(allValues));
              // console.log("on value changes", value);
              // setFormValues(allValues);
            }}
          >
            <div className="main-header">
              <div className="d-flex">
                {/* temp solution */}
                {projectName ===
                  "Lighthouse Beloved Community CLT Financial Application" && (
                    <Image
                      height={50}
                      width={35}
                      src="https://media.staging.beam.live/106749_original.png"
                      preview={false}
                    />
                  )}
                <h3 className="ml-3">{projectName || "Event creator"}</h3>
              </div>
              <div className="d-flex">
                {/* {!date && (
                <React.Fragment>
                  <UploadOutlined
                    onClick={() => {
                      setUploadModalVisible(true);
                    }}
                    style={{
                      color: "#869cbd",
                      fontSize: 20,
                      cursor: "pointer",
                      marginRight: 0,
                    }}
                  />

                  <CloudDownloadOutlined
                    onClick={() => {
                      generateCSVFile();
                    }}
                    style={{
                      color: "#869cbd",
                      fontSize: 20,
                      cursor: "pointer",
                      marginLeft: "1rem",
                    }}
                  />
                </React.Fragment>
              )} */}

                <Button className="beam-btn map-icon" style={{ padding: 0 }}>
                  <ReactSVG
                    src="/images/map.svg"
                    onClick={() => {
                      setScreens({
                        ...screens,
                        map: true,
                        form: window.innerWidth >= 700,
                      });
                    }}
                  />
                </Button>
              </div>
            </div>
            <div className="main-cards mt-3" ref={formRef}>
              <Collapse
                activeKey={[
                  "account",
                  "where",
                  "what",
                  "who",
                  "when",
                  "why",
                  ...cadSections?.map((section) => {
                    return section.sectionName;
                  }),
                ]}
                bordered={false}
                className="simple-collapse"
                onChange={(active) => {
                  localStorage.setItem("active", JSON.stringify(active));
                }}
              >
                {cadSections?.map((section, i) => (
                  <Panel
                    header={
                      <div className="d-flex">
                        {sectionIcons?.[section.sectionName.toLowerCase()] && (
                          <ReactSVG
                            src={
                              sectionIcons?.[section.sectionName.toLowerCase()]
                            }
                          />
                        )}
                        <h5 className="ml-3">{section.sectionName}</h5>
                      </div>
                    }
                    key={section.sectionName}
                  >
                    <div className="sub-cards-2">
                      {section?.Rows.map((row, j) => (
                        <Row className={j > 0 ? "mt-3" : ""} key={j}>
                          <React.Fragment>
                            {!row.isMulti &&
                              row?.Cols.map((col, k) => (
                                <Col
                                  span={col.ColSize}
                                  className="pr-2"
                                  xs={24}
                                  sm={col.ColSize}
                                  key={k}
                                >
                                  <RenderFields
                                    data={col}
                                    projects={projects}
                                    addOtherLocation={addOtherLocation}
                                    onProjectChange={onProjectChange}
                                    onCustomerSearch={getCustomer}
                                    adminRoles={adminRoles}
                                    customerDisabled={
                                      selectedCustomerId !== undefined &&
                                      selectedCustomerId !== ""
                                    }
                                    dispatchDisabled={date !== undefined}
                                    conditionalSections={conditionalCadSections}
                                    socket={socket}
                                    formValues={formValues}
                                    relationDisbaled={true}
                                    onServiceChange={onServiceChange}
                                  />
                                </Col>
                              ))}

                            {row.isMulti && (
                              <MultiInput
                                listName={`${section.sectionName}MultiRow${j}`}
                                cols={row?.Cols}
                                RenderFields={RenderFields}
                                customerDisabled={
                                  selectedCustomerId !== undefined &&
                                  selectedCustomerId !== ""
                                }
                                dispatchDisabled={date !== undefined}
                                projects={projects}
                                addOtherLocation={addOtherLocation}
                                onProjectChange={onProjectChange}
                                adminRoles={adminRoles}
                              />
                            )}
                          </React.Fragment>
                        </Row>
                      ))}
                    </div>
                  </Panel>
                ))}
              </Collapse>

              {selectedProjectId !== undefined && selectedProjectId !== "" && (
                <Row className="mt-3">
                  <Col span={24}>
                    <Form.Item name="shareCustomerLink" valuePropName="checked">
                      <Checkbox>
                        Do you want to share link with customer?
                      </Checkbox>
                    </Form.Item>
                  </Col>
                </Row>
              )}
            </div>

            {error && (
              <Form.Item>
                <p className="error">{error}</p>
              </Form.Item>
            )}
            <Row className="action-grp mt-4">
              <Col span={8} className="" xs={24} sm={12}>
                <Button
                  className="beam-btn yellow-btn bordered w-full"
                  onClick={() => {
                    setTimeout(() => {
                      localStorage.removeItem("form");
                      dispatch({ type: SET_SUBMITTED, payload: false });
                      nine11Form.resetFields();
                      setScreens({
                        ...screens,
                        map: false,
                      });
                      const query = new URLSearchParams(search);
                      query.delete("pageId");
                      history.replace({
                        search: query.toString(),
                      });
                      dispatch({
                        type: "SET_SELECTED_PAGE",
                        payload: { page: undefined },
                      });
                      setPageId(undefined);
                      setAssistPageId(undefined);
                    });
                  }}
                >
                  Clear
                </Button>
              </Col>
              <Col span={8} className="pl-2" xs={24} sm={12}>
                <Form.Item>
                  <Button
                    className="beam-btn green-btn cover w-full"
                    htmlType="submit"
                    loading={searching}
                  >
                    {pageId ? "Save" : "Submit"}
                  </Button>
                </Form.Item>
              </Col>
            </Row>
          </Form>
        </div>

        {assistModalVisible && (
          <ConfirmationModal
            onClose={() => {
              setAssistModalVisible(false);
            }}
            handleConfirm={() => {
              setAssistPageId(encrypted_token?.assistPageId);
              setAssistModalVisible(false);
            }}
            message={`Do you want to add assist user to the event page?`}
          />
        )}
      </div>
    );
  };

export default DispatchPanel;
