import moment from "moment";
import type { PillTone } from "../../common/ui";

// One `type:timesheet` custom object per driver per day, written by the
// mobile app's shift timer (live-react mobile: helpers/shiftTimesheet.ts):
//   partitions: org:<id>, user:<userId>, type:timesheet, date:YYYYMMDD
//   info: { sessions[{ startTime, endTime?, breakTimeInSeconds, pauseTime }],
//           totalWorkedTimeInMinutes, breakTimeInSeconds, startTime, endTime, isClockedIn }
// Older rows have no `sessions`, only the top-level start/end.

// An open session older than this is treated as a forgotten clock-out.
const OPEN_SESSION_MAX_HOURS = 24;

export type TimesheetStatusKey = "onShift" | "onBreak" | "completed" | "missingClockOut";

export const STATUS: Record<TimesheetStatusKey, { label: string; tone: PillTone }> = {
  onShift: { label: "On shift", tone: "green" },
  onBreak: { label: "On break", tone: "amber" },
  completed: { label: "Completed", tone: "gray" },
  missingClockOut: { label: "Missing clock-out", tone: "red" },
};

export interface TimesheetSession {
  start: moment.Moment;
  end?: moment.Moment;
  breakSeconds: number;
  pausedAt?: moment.Moment;
}

export interface TimesheetRow {
  key: string;
  userId?: string;
  driverName: string;
  /** YYYYMMDD */
  date: string;
  clockIn?: moment.Moment;
  clockOut?: moment.Moment;
  sessions: TimesheetSession[];
  workedMinutes: number;
  breakMinutes: number;
  status: TimesheetStatusKey;
}

const toMoment = (value: any) => {
  if (!value) return undefined;
  const m = moment(value);
  return m.isValid() ? m : undefined;
};

const readSessions = (info: any): TimesheetSession[] => {
  const raw = Array.isArray(info?.sessions) && info.sessions.length ? info.sessions : [info];
  return raw
    .map((s: any) => ({
      start: toMoment(s?.startTime),
      end: toMoment(s?.endTime),
      breakSeconds: Number(s?.breakTimeInSeconds) || 0,
      pausedAt: toMoment(s?.pauseTime),
    }))
    .filter((s: any) => !!s.start) as TimesheetSession[];
};

const workedSeconds = (s: TimesheetSession, until: moment.Moment) =>
  Math.max(0, until.diff(s.start, "seconds") - s.breakSeconds);

const partition = (partitions: any, prefix: string) =>
  (Array.isArray(partitions) ? partitions : [])
    .find((p: any) => typeof p === "string" && p.startsWith(`${prefix}:`))
    ?.slice(prefix.length + 1);

/** Turns an aggregate result into a row, or undefined when it has no clock-in. */
export const toTimesheetRow = (
  x: any,
  driverName: (userId?: string) => string,
  now = moment()
): TimesheetRow | undefined => {
  const info = x?.info;
  const sessions = readSessions(info);
  if (!sessions.length) return undefined;

  const userId = partition(x?.partitions, "user");
  const last = sessions[sessions.length - 1];
  const open = !last.end;
  const stale = open && now.diff(last.start, "hours", true) > OPEN_SESSION_MAX_HOURS;

  // Completed sessions, plus the running one while it's live (up to the pause if paused).
  const completedSeconds = sessions.reduce(
    (sum, s) => (s.end ? sum + workedSeconds(s, s.end) : sum),
    0
  );
  const liveSeconds = open && !stale ? workedSeconds(last, last.pausedAt || now) : 0;
  const hasSessions = Array.isArray(info?.sessions) && info.sessions.length > 0;
  const workedMinutes =
    hasSessions || !open
      ? Math.floor((completedSeconds + liveSeconds) / 60)
      : Number(info?.totalWorkedTimeInMinutes) || 0;

  const status: TimesheetStatusKey = !open
    ? "completed"
    : stale
    ? "missingClockOut"
    : last.pausedAt
    ? "onBreak"
    : "onShift";

  return {
    key: `${x?.objectId}`,
    userId,
    driverName: driverName(userId),
    date: partition(x?.partitions, "date") || sessions[0].start.format("YYYYMMDD"),
    clockIn: sessions[0].start,
    clockOut: open ? undefined : last.end,
    sessions,
    workedMinutes,
    breakMinutes: Math.floor(sessions.reduce((sum, s) => sum + s.breakSeconds, 0) / 60),
    status,
  };
};

/** "8h 05m", "45m" */
export const formatDuration = (minutes: number) => {
  const total = Math.max(0, Math.floor(minutes || 0));
  const h = Math.floor(total / 60);
  const m = total % 60;
  return h ? `${h}h ${`${m}`.padStart(2, "0")}m` : `${m}m`;
};

export const formatDay = (yyyymmdd: string) => {
  const m = moment(yyyymmdd, "YYYYMMDD", true);
  return m.isValid() ? m.format("ddd, MMM D") : yyyymmdd;
};
