import React, { FC, useEffect, useState } from "react";
import { Input, Button } from "antd";
import { MinusOutlined, PlusOutlined } from "@ant-design/icons";

const NumberInput: FC<{
  value?: number;
  onChange: (val: number) => void;
  placeholder?: string;
  disabled?: boolean;
  min?: number;
  max?: number;
  step?: number | string;
}> = ({
  value,
  onChange,
  placeholder,
  disabled,
  min,
  max,
  step = "0.01",
}) => {
    const [val, setVal] = useState<number>(value ?? 0);

    useEffect(() => {
      // if (typeof value === "number") {
      //   console.log('value123', value);
      //   setVal(value);
      // }
      setVal(value ?? 0);

      console.log('value', value);
    }, [value]);

    const isAboveMin = (v: number) => min === undefined || v >= min;
    const isBelowMax = (v: number) => max === undefined || v <= max;

    const handleChange = (newVal: any) => {
      if (isAboveMin(newVal) && isBelowMax(newVal)) {
        setVal(newVal);
        onChange(newVal);
      }
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const inputVal = parseFloat(e.target.value);
      if (!isNaN(inputVal)) {
        if (isAboveMin(inputVal) && isBelowMax(inputVal)) {
          setVal(inputVal);
          onChange(inputVal);
        }
      }
    };

    return (
      <div className="d-flex custom-number">
        <Button
          className="beam-btn d-flex"
          disabled={disabled || (min !== undefined && val <= min)}
          onClick={() => handleChange(val - 1)}
        >
          <MinusOutlined />
        </Button>
        <Input
          className="beam-input mx-2"
          placeholder={placeholder || "Enter Number"}
          type="number"
          min={min}
          max={max}
          step={step}
          disabled={disabled}
          value={val}
          onWheel={(e: any) => e.target.blur()}
          onChange={handleInputChange}
        />
        <Button
          className="beam-btn d-flex"
          disabled={disabled || (max !== undefined && val >= max)}
          onClick={() => handleChange(val + 1)}
        >
          <PlusOutlined />
        </Button>
      </div>
    );
  };

export default NumberInput;
