import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Tooltip } from "antd";
import { FormOutlined } from "@ant-design/icons";
import dayjs from "dayjs";
import { useDispatch, useSelector } from "react-redux";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import {
  getCustomCreateRequestPublishTopic,
  getCustomCreateSubscriptionTopic,
  getCustomUpdateSubscriptionTopic,
  getCustomUpdateRequestPublishTopic,
} from "hooks/MQTTConstants";
import { SocketTopics } from "constants/enums";
import { RootState } from "reducers/rootReducer";
import { formatForRedis } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import {
  DataTableCard,
  EmptyState,
  PageHeader,
  Pill,
  RowActions,
  matchesSearch,
} from "../../common/ui";
import EditShiftModal from "./EditShiftModal";
import { RenameRosterModal, RosterFormModal, RosterFormValues } from "./RosterFormModal";
import {
  buildDayRows,
  cellSlots,
  countDays,
  formatHours,
  formatPeriod,
  getRosterStats,
  getRosterStatus,
  minutesOnShift,
  shiftRosterRows,
} from "./shiftUtils";

import "../Dashboard.scss";
import "./Shift.scss";

type RosterModalState = { type: "new" } | { type: "copy"; action: any } | undefined;

interface RosterRow {
  key: string;
  name: string;
  startDate: string;
  endDate: string;
  days: number;
  status: ReturnType<typeof getRosterStatus>;
  driverCount: number;
  minutes: number;
  action: any;
}

// Responders: can take jobs (OnMove) and are not admins.
const isResponderRole = (role: any) => {
  const p: string[] = role?.permissions || [];
  return p.includes(PERMISSION_TYPES.OnMove) && !p.includes(PERMISSION_TYPES.Admin);
};

const DATA_COLUMNS = [
  {
    title: "Name",
    key: "name",
    dataIndex: "name",
    sorter: (a: RosterRow, b: RosterRow) => (a.name || "").localeCompare(b.name || ""),
    render: (name: string) => <span className="mx-shift-list__name">{name || "Untitled roster"}</span>,
  },
  {
    title: "Period",
    key: "period",
    sorter: (a: RosterRow, b: RosterRow) => (a.startDate || "").localeCompare(b.startDate || ""),
    render: (_: any, r: RosterRow) => (
      <div>
        <div>{formatPeriod(r.startDate, r.endDate)}</div>
        <div className="mx-shift-list__sub">
          {r.days} {r.days === 1 ? "day" : "days"}
        </div>
      </div>
    ),
  },
  {
    title: "Status",
    key: "status",
    sorter: (a: RosterRow, b: RosterRow) => a.status.order - b.status.order,
    render: (_: any, r: RosterRow) => <Pill tone={r.status.tone}>{r.status.label}</Pill>,
  },
];

const ShiftModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userId?: string;
}> = ({ socket, userId }) => {
  const { encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const [rosters, setRosters] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [driverDataSource, setDriverDataSource] = useState<any[]>([]);
  const [editing, setEditing] = useState<any>(undefined);
  const [rosterModal, setRosterModal] = useState<RosterModalState>(undefined);
  const [renaming, setRenaming] = useState<any>(undefined);
  const [saving, setSaving] = useState(false);

  const getResponders = (roles: any[]) => {
    const rolesQuery = (roles || []).filter(isResponderRole).map((y: any) => `@roleId === '${y._id}'`);
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(projects?.userServiceId)}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        list: {
          objectIds: userId ? [userId.toString()] : undefined,
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
        },
      },
      apply: { expression: "", name: "" },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
      },
      anyStatus: false,
    };
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          setDriverDataSource(
            (response || []).map((x) => ({
              driverId: x.id,
              driverName: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
            }))
          );
          getShift();
        },
      })
    );
  };

  const getShift = (silent = false) => {
    const request: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:createdAt`,
          searchQuery: `@partitions:{'org\\:${formatForRedis(
            projects?.userServiceId
          )}'}@partitions:{type\\:shift}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          info: "$.info",
          objectId: "$.objectId",
          partitions: "$.partitions",
          status: "$..status",
        },
      },
      filter: { expression: "" },
    };
    if (!silent) setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: request,
        callback: (response) => {
          setRosters(response || []);
          setLoading(false);
        },
      })
    );
  };

  const publishCustomUpdate = (objectId: string, changes: any[]) =>
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getCustomUpdateRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({ objectId, changes })
    );

  const createRoster = ({ name, startDate, endDate }: RosterFormValues) => {
    const source = rosterModal?.type === "copy" ? rosterModal.action?.info : undefined;
    // Whole days so the dashboard's overlap filter sees the first and last day.
    const startTimestamp = dayjs(startDate).startOf("day").valueOf();
    const endTimestamp = dayjs(endDate).endOf("day").valueOf();
    const shift = source
      ? shiftRosterRows(source.shift, source.startDate, source.endDate, startDate)
      : buildDayRows(startDate, endDate);

    setSaving(true);
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getCustomCreateRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        changes: [
          {
            op: "add",
            path: "/partitions",
            value: [
              `org:${encrypted_token?.cudbServiceId || encrypted_token?.serviceId}`,
              `type:shift`,
              `startDate:${startTimestamp}`,
              `endDate:${endTimestamp}`,
            ],
          },
          { op: "add", path: "/createdAt", value: new Date().getTime() },
          {
            op: "add",
            path: "/info",
            value: { startDate, endDate, startTimestamp, endTimestamp, name, shift },
          },
        ],
      })
    );
  };

  const renameRoster = (trimmed: string) => {
    const id = renaming?.objectId;
    // Only the name changes, so a stale copy of /info/shift can't overwrite edits.
    publishCustomUpdate(id, [{ op: "replace", path: "/info/name", value: trimmed }]);
    const rename = (x: any) =>
      x?.objectId === id ? { ...x, info: { ...x.info, name: trimmed } } : x;
    setRosters((prev) => prev.map(rename));
    setEditing((prev) => (prev ? rename(prev) : prev));
    setRenaming(undefined);
  };

  const deleteRoster = (id: string) => {
    publishCustomUpdate(id, [{ op: "replace", path: "/objectStatus", value: "deleted" }]);
    setRosters((prev) => prev.filter((x) => x?.objectId !== id));
  };

  useEffect(() => {
    if (!userId) document.title = "Shift | Beam";
  }, []);

  useEffect(() => {
    if (!projects?.adminUserId) return;
    getResponders(adminUserRoles);
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomCreateSubscriptionTopic(encrypted_token?.connectionId),
      () => {
        setRosterModal(undefined);
        setSaving(false);
        getShift();
      }
    );
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomUpdateSubscriptionTopic(encrypted_token?.connectionId),
      () => getShift(true)
    );
  }, [projects]);

  const tableRows: RosterRow[] = useMemo(
    () =>
      rosters
        .map((x) => {
          const info = x?.info || {};
          const stats = userId
            ? {
                driverCount: 0,
                minutes: (Array.isArray(info.shift) ? info.shift : []).reduce(
                  (sum, row) => sum + minutesOnShift(cellSlots(row, userId), row?.key),
                  0
                ),
              }
            : getRosterStats(info.shift);
          return {
            key: x?.objectId,
            name: info.name,
            startDate: info.startDate,
            endDate: info.endDate,
            days: countDays(info.startDate, info.endDate),
            status: getRosterStatus(info.startDate, info.endDate),
            ...stats,
            action: x,
          };
        })
        .filter((r) => matchesSearch(search, r.name))
        .sort((a, b) => (b.startDate || "").localeCompare(a.startDate || "")),
    [rosters, search, userId]
  );

  // Handlers change every render; columns read them through a ref so the
  // column definitions stay static.
  const handlers = useRef<any>({});
  handlers.current = { setEditing, setRenaming, setRosterModal, deleteRoster };

  const columns = useMemo(
    () => [
      ...DATA_COLUMNS,
      userId
        ? {
            title: "Your hours",
            key: "minutes",
            align: "right" as const,
            render: (_: any, r: RosterRow) => formatHours(r.minutes),
          }
        : {
            title: "Scheduled",
            key: "scheduled",
            sorter: (a: RosterRow, b: RosterRow) => a.minutes - b.minutes,
            render: (_: any, r: RosterRow) => (
              <div>
                <div>
                  {r.driverCount} {r.driverCount === 1 ? "driver" : "drivers"}
                </div>
                <div className="mx-shift-list__sub">{formatHours(r.minutes)} on shift</div>
              </div>
            ),
          },
      {
        title: "",
        key: "actions",
        align: "right" as const,
        width: userId ? 60 : 170,
        render: (_: any, r: RosterRow) =>
          userId ? (
            <RowActions onView={() => handlers.current.setEditing(r.action)} />
          ) : (
            <span className="mx-shift-list__actions" onClick={(e) => e.stopPropagation()}>
              <Tooltip title="Rename">
                <Button
                  size="small"
                  icon={<FormOutlined />}
                  onClick={() => handlers.current.setRenaming(r.action)}
                />
              </Tooltip>
              <RowActions
                onEdit={() => handlers.current.setEditing(r.action)}
                onCopy={() => handlers.current.setRosterModal({ type: "copy", action: r.action })}
                onDelete={() => handlers.current.deleteRoster(r.key)}
                deleteConfirm={`Delete roster "${r.name || "Untitled"}"?`}
              />
            </span>
          ),
      },
    ],
    [userId]
  );

  return (
    <div className="mx-shift">
      {!userId && (
        <PageHeader
          title="Shifts"
          subtitle="Weekly driver rosters used to suggest drivers when assigning jobs"
          search={{ value: search, onChange: setSearch, placeholder: "Search rosters" }}
          primaryAction={{ label: "New roster", onClick: () => setRosterModal({ type: "new" }) }}
        />
      )}

      <DataTableCard<RosterRow>
        loading={loading}
        clickable
        caption={`${tableRows.length} ${tableRows.length === 1 ? "roster" : "rosters"}`}
        dataSource={tableRows}
        columns={columns}
        scroll={{ x: true }}
        onRow={(r) => ({ onClick: () => setEditing(r.action) })}
        rowClassName={(r) => (r.status.order === 0 ? "mx-shift-list__row--active" : "")}
        empty={
          search ? (
            <EmptyState title="No rosters match your search" />
          ) : (
            <EmptyState
              title="No rosters yet"
              description="Create a roster to plan which drivers are on shift each day."
              action={
                userId ? undefined : { label: "New roster", onClick: () => setRosterModal({ type: "new" }) }
              }
            />
          )
        }
      />

      {editing !== undefined && (
        <EditShiftModal
          socket={socket}
          student={editing}
          onClose={() => setEditing(undefined)}
          adminRoles={adminUserRoles}
          drivers={driverDataSource}
          onAdd={() => getShift(true)}
          onRename={userId ? undefined : () => setRenaming(editing)}
          userId={userId}
        />
      )}

      {rosterModal && (
        <RosterFormModal
          source={rosterModal.type === "copy" ? rosterModal.action?.info : undefined}
          rosters={rosters}
          saving={saving}
          onCancel={() => setRosterModal(undefined)}
          onSubmit={createRoster}
        />
      )}

      {renaming && (
        <RenameRosterModal
          name={renaming?.info?.name}
          onCancel={() => setRenaming(undefined)}
          onSubmit={renameRoster}
        />
      )}
    </div>
  );
};

export default ShiftModal;
