import React, { FC, useMemo, useState } from "react";
import { Card, Col, DatePicker, Radio, Row } from "antd";
import moment, { Moment } from "moment";
import {
  ArrowDownOutlined,
  ArrowUpOutlined,
  FundOutlined,
  TeamOutlined,
} from "@ant-design/icons";

import {
  AgingBucket,
  CustomerGroupDimension,
  CustomerGroupRow,
  Domain,
  LedgerSide,
  TransactionFilter,
} from "../types";
import { DAY, DOMAIN_LABELS, LEDGER_ROWS, NOW, PROJECTS } from "../mockData";
import {
  BridgeStep,
  computeAging,
  computeKpis,
  customerGroups,
  formatMoney,
  formatMoneyShort,
  formatPct,
  formatSigned,
  pctChange,
  previousWindow,
  profitBridge,
  withinWindow,
  TimeWindow,
} from "../selectors";
import KpiCards, { DASHBOARD_KPI_META, KpiTile } from "../KpiCards";
import { LedgerSideCard } from "../CashPanels";
import ChartFrame, { ChartView, ChartViewToggle } from "../charts/ChartFrame";
import WaterfallChart from "../charts/WaterfallChart";
import StackedBarChart, { StackItem } from "../charts/StackedBarChart";
import { CHART_COLORS } from "../charts/theme";

const { RangePicker } = DatePicker;

const BRIDGE_LEGEND = [
  { key: "total", label: "Totals", color: CHART_COLORS.purple },
  { key: "step", label: "Deductions & costs", color: CHART_COLORS.orange },
];

/**
 * A group's revenue bar is split into what it cost and what was left.
 * When costs exceed revenue the bar runs on past revenue in red.
 */
const GROUP_SERIES = [
  { key: "costs", label: "Costs", color: CHART_COLORS.orange },
  { key: "profit", label: "Profit", color: CHART_COLORS.green },
  { key: "loss", label: "Loss", color: CHART_COLORS.red },
];

const DEFAULT_RANGE: TimeWindow = { from: NOW - 365 * DAY, to: NOW };

const rangeText = (window: TimeWindow) =>
  `${moment(window.from).format("D MMM YYYY")} - ${moment(window.to).format("D MMM YYYY")}`;

interface Props {
  domain: Domain;
  /** Opens the Transactions screen with the given filters applied. */
  onOpenTransactions: (preset: Partial<TransactionFilter>) => void;
  socket?: ISocket;
}

/**
 * The big picture: the P&L tiles with their change against the previous
 * period, the profit bridge, revenue and profit by customer group, and
 * the receivable and payable exposure. Anything line-level lives on the
 * Transactions screen; the aging detail and reminders on Reports.
 *
 * Every figure is mock data - see mockData.ts for why.
 */
const DashboardScreen: FC<Props> = ({ domain, onOpenTransactions }) => {
  const [range, setRange] = useState<TimeWindow>(DEFAULT_RANGE);
  const [dimension, setDimension] = useState<CustomerGroupDimension>("customer-type");
  const [views, setViews] = useState<Record<"bridge" | "groups", ChartView>>({
    bridge: "chart",
    groups: "chart",
  });

  const labels = DOMAIN_LABELS[domain];
  const previous = useMemo(() => previousWindow(range), [range]);

  /** Rows in the selected range: what every figure on the page reads. */
  const rows = useMemo(
    () => LEDGER_ROWS[domain].filter((row) => withinWindow(row, range)),
    [domain, range]
  );

  /** The same slice over the previous period, for the comparisons. */
  const previousRows = useMemo(
    () => LEDGER_ROWS[domain].filter((row) => withinWindow(row, previous)),
    [domain, previous]
  );

  const kpis = useMemo(() => computeKpis(rows), [rows]);
  const previousKpis = useMemo(() => computeKpis(previousRows), [previousRows]);
  const agingAr = useMemo(() => computeAging(rows, "ar"), [rows]);
  const agingAp = useMemo(() => computeAging(rows, "ap"), [rows]);
  const bridge = useMemo(() => profitBridge(kpis, previousKpis), [kpis, previousKpis]);
  const groups = useMemo(
    () =>
      customerGroups(rows, dimension, (role) =>
        role === "Parent" ? `Parents & ${labels.nav.players.toLowerCase()}` : undefined
      ),
    [rows, dimension, labels]
  );

  const tiles = useMemo<KpiTile[]>(
    () =>
      DASHBOARD_KPI_META.map((meta) => {
        const value = kpis[meta.key] as number;
        const change = pctChange(value, previousKpis[meta.key] as number);
        const good = change === null ? null : (change >= 0) === (meta.upIs === "good");
        const changeNode =
          change === null ? (
            <span className="cfo-muted">no prior period to compare</span>
          ) : (
            <>
              <span className={good ? "cfo-amount--in" : "cfo-amount--due"}>{formatPct(change, true)}</span> vs previous
            </>
          );
        return {
          ...meta,
          hint: (
            <span className="cfo-kpi-tip">
              <span>{meta.hint}</span>
              <strong>{formatMoney(value, "USD")}</strong>
              <span>Previous period: {formatMoney(previousKpis[meta.key] as number, "USD")}</span>
            </span>
          ),
          value: formatMoneyShort(value, "USD"),
          sub:
            meta.key === "profit" ? (
              <>
                {formatPct(kpis.marginPct)} margin · {changeNode}
              </>
            ) : (
              changeNode
            ),
        };
      }),
    [kpis, previousKpis]
  );

  /** The stacked bar for one group: costs, then profit, or the loss past revenue. */
  const groupItems = useMemo<StackItem[]>(
    () =>
      groups.map((group) => {
        const loss = Math.max(0, -group.profit);
        return {
          id: group.id,
          name: group.name,
          values: {
            costs: Math.min(group.costs, group.revenue),
            profit: Math.max(0, group.profit),
            loss,
          },
          total: group.revenue + loss,
          extra: [
            { label: "Revenue", value: `${formatMoney(group.revenue, "USD")} · ${group.revenuePct}%` },
            { label: "Customers", value: `${group.customers} · ${group.customersPct}%` },
            { label: "Margin", value: formatPct(group.marginPct) },
          ],
        };
      }),
    [groups]
  );

  /** Clicking a group opens its transactions. */
  const openGroup = (id: string) => {
    switch (dimension) {
      case "customer-type":
        onOpenTransactions({ entityRoles: [id], range });
        break;
      case "project-kind":
        onOpenTransactions({
          projectIds: PROJECTS.filter((p) => p.domain === domain && p.kind === id).map((p) => p.id),
          range,
        });
        break;
      case "project":
      default:
        onOpenTransactions({ projectIds: [id], range });
    }
  };

  const openAging = (side: LedgerSide) => (bucket: AgingBucket | null) => {
    if (bucket) onOpenTransactions({ side, aging: bucket, range });
  };

  const toWindow = (values: [Moment | null, Moment | null] | null): TimeWindow | null =>
    values && values[0] && values[1]
      ? { from: values[0].startOf("day").valueOf(), to: values[1].endOf("day").valueOf() }
      : null;

  /* Signed values: a positive change is always good news, a negative one always bad. */
  const changeClass = (step: BridgeStep) =>
    step.change > 0 ? "cfo-amount--in" : step.change < 0 ? "cfo-amount--due" : undefined;

  const pctCell = (value: number | null, tone?: "in" | "due") => (
    <span className={`cfo-pct${tone ? ` cfo-amount--${tone}` : ""}`}>{formatPct(value)}</span>
  );

  const DIMENSION_OPTIONS: { value: CustomerGroupDimension; label: string }[] = [
    { value: "customer-type", label: "Customer type" },
    { value: "project-kind", label: `${labels.navSingular.team} / event kind` },
    { value: "project", label: labels.navSingular.team },
  ];

  return (
    <div className="school-overview cfo-dashboard">
      <Row justify="space-between" align="middle" className="overview-header" gutter={[0, 12]}>
        <Col>
          <h2 className="overview-title">CFO Dashboard</h2>
          <p className="overview-subtitle">
            {moment().format("dddd, MMMM D, YYYY")} · {labels.label} · {rangeText(range)}
          </p>
        </Col>
        <Col>
          <RangePicker
            allowClear={false}
            value={[moment(range.from), moment(range.to)]}
            format="D MMM YYYY"
            disabledDate={(current) => !!current && current.valueOf() > moment().endOf("day").valueOf()}
            onChange={(values) => {
              const next = toWindow(values as any);
              if (next) setRange(next);
            }}
          />
        </Col>
      </Row>

      <h3 className="section-heading">Revenue &amp; profit</h3>

      <KpiCards tiles={tiles} />

      <Row gutter={[20, 20]} className="mt-3">
        <Col xs={24}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <FundOutlined style={{ color: CHART_COLORS.purple }} /> Profit bridge
              </span>
            }
            extra={
              <span className="cfo-chart__extra">
                <span className="report-card-date">
                  {rangeText(range)} vs {rangeText(previous)}
                </span>
                <ChartViewToggle view={views.bridge} onChange={(view) => setViews({ ...views, bridge: view })} />
              </span>
            }
          >
            <ChartFrame<BridgeStep>
              view={views.bridge}
              legend={BRIDGE_LEGEND}
              data={bridge}
              rowKey={(step) => step.key}
              ariaLabel="Profit bridge from gross revenue to profit, against the previous period"
              columns={[
                { key: "label", title: "Item", render: (step) => step.label },
                {
                  key: "value",
                  title: `Current (${rangeText(range)})`,
                  align: "right",
                  render: (step) => formatSigned(step.signed, "USD"),
                },
                {
                  key: "previous",
                  title: `Previous period (${rangeText(previous)})`,
                  align: "right",
                  render: (step) => formatSigned(step.signedPrevious, "USD"),
                },
                {
                  key: "change",
                  title: "Change",
                  align: "right",
                  render: (step) => (
                    <span className={changeClass(step)}>
                      {step.change > 0 ? "+" : ""}
                      {formatSigned(step.change, "USD")}
                    </span>
                  ),
                },
                {
                  key: "changePct",
                  title: "Change %",
                  align: "right",
                  render: (step) =>
                    step.changePct === null ? (
                      <span className="cfo-muted">n/a</span>
                    ) : (
                      <span className={changeClass(step)}>{formatPct(step.changePct, true)}</span>
                    ),
                },
              ]}
            >
              {(api) => <WaterfallChart steps={bridge} currency="USD" api={api} />}
            </ChartFrame>
          </Card>
        </Col>
      </Row>

      <h3 className="section-heading">Customer groups</h3>

      <Row gutter={[20, 20]}>
        <Col xs={24}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <TeamOutlined style={{ color: CHART_COLORS.blue }} /> Revenue &amp; profit by group
              </span>
            }
            extra={
              <span className="cfo-chart__extra">
                <Radio.Group
                  size="small"
                  value={dimension}
                  onChange={(e) => setDimension(e.target.value)}
                  options={DIMENSION_OPTIONS}
                  optionType="button"
                />
                <ChartViewToggle view={views.groups} onChange={(view) => setViews({ ...views, groups: view })} />
              </span>
            }
          >
            <ChartFrame<CustomerGroupRow>
              view={views.groups}
              legend={GROUP_SERIES}
              data={groups}
              rowKey={(group) => group.id}
              ariaLabel="Revenue, costs and profit by customer group"
              columns={[
                { key: "name", title: "Group", render: (g) => g.name },
                {
                  key: "customers",
                  title: "Customers",
                  align: "right",
                  render: (g) => (
                    <>
                      {g.customers} {pctCell(g.customersPct)}
                    </>
                  ),
                },
                {
                  key: "revenue",
                  title: "Net revenue",
                  align: "right",
                  render: (g) => (
                    <>
                      {formatMoney(g.revenue, "USD")} {pctCell(g.revenuePct)}
                    </>
                  ),
                },
                {
                  key: "collected",
                  title: "Collected",
                  align: "right",
                  render: (g) => (
                    <>
                      {formatMoney(g.collected, "USD")} {pctCell(g.collectedPct)}
                    </>
                  ),
                },
                { key: "costs", title: "Costs", align: "right", render: (g) => formatMoney(g.costs, "USD") },
                {
                  key: "profit",
                  title: "Profit",
                  align: "right",
                  render: (g) => (
                    <span className={g.profit < 0 ? "cfo-amount--due" : "cfo-amount--in"}>
                      {formatSigned(g.profit, "USD")}
                    </span>
                  ),
                },
                {
                  key: "margin",
                  title: "Margin",
                  align: "right",
                  render: (g) => pctCell(g.marginPct, g.marginPct !== null && g.marginPct < 0 ? "due" : undefined),
                },
              ]}
            >
              {(api) => (
                <StackedBarChart
                  items={groupItems}
                  series={GROUP_SERIES}
                  currency="USD"
                  api={api}
                  selected={null}
                  onSelect={openGroup}
                />
              )}
            </ChartFrame>
            <p className="report-footnote">
              {dimension === "customer-type"
                ? "Costs are booked per project and shared across the customer types in that project by revenue. Click a bar to open its transactions."
                : "Click a bar to open its transactions."}
            </p>
          </Card>
        </Col>
      </Row>

      <h3 className="section-heading">Receivables &amp; payables</h3>

      <Row gutter={[20, 20]}>
        <Col xs={24} lg={12}>
          <LedgerSideCard
            side="ar"
            title="Accounts receivable"
            icon={<ArrowDownOutlined style={{ color: CHART_COLORS.green }} />}
            currency="USD"
            stats={[
              { label: "Net collected", value: kpis.netCollected, tone: "in" },
              { label: "Current AR", value: kpis.currentAr },
              { label: "Overdue AR", value: kpis.overdueAr, tone: "due" },
            ]}
            aging={agingAr}
            activeBucket={null}
            onSelect={openAging("ar")}
          />
        </Col>
        <Col xs={24} lg={12}>
          <LedgerSideCard
            side="ap"
            title="Accounts payable"
            icon={<ArrowUpOutlined style={{ color: CHART_COLORS.orange }} />}
            tag={{ text: "AP mocked", hint: "No accounts-payable source exists in the platform yet - these figures are placeholders." }}
            currency="USD"
            stats={[
              { label: "Disbursed", value: kpis.disbursedAp, tone: "out" },
              { label: "Committed", value: kpis.committedAp },
              { label: "Overdue AP", value: kpis.overdueAp, tone: "due" },
            ]}
            aging={agingAp}
            activeBucket={null}
            onSelect={openAging("ap")}
          />
        </Col>
      </Row>
    </div>
  );
};

export default DashboardScreen;
