import type { PillTone } from "./ui";

/**
 * Shift slot vocabulary shared by the shift editor and the assignment tools.
 * Values are persisted in `info.shift[].{driverId}[].shiftType/locationType`,
 * so existing values must never be renamed.
 */
export const SHIFT_TYPES: {
  value: string;
  label: string;
  tone: PillTone;
  color: string;
  /** Whether a driver in this slot can normally take a job. */
  assignable: boolean;
}[] = [
  { value: "Shift", label: "Shift", tone: "green", color: "#40CC52", assignable: true },
  { value: "Available", label: "Available", tone: "blue", color: "#508AFA", assignable: true },
  { value: "On Call", label: "On Call", tone: "amber", color: "#FBAE16", assignable: true },
  { value: "N/A", label: "N/A", tone: "gray", color: "#91A5C6", assignable: false },
];

export const SHIFT_LOCATIONS = [
  "Kingston",
  "Brockville",
  "Belleville",
  "Perth",
  "Office",
  "Dispatch",
];

export const getShiftType = (value?: string) =>
  SHIFT_TYPES.find((t) => t.value === value) ?? {
    value: value ?? "",
    label: value || "Unspecified",
    tone: "gray" as PillTone,
    color: "#91A5C6",
    assignable: false,
  };
