import React from "react";
import { Tooltip } from "antd";
import { getShiftType } from "../shiftTypes";
import { DayJob, formatMinutes, SlotInterval } from "./availability";

const DAY_MIN = 24 * 60;
const TICKS = [0, 6, 12, 18, 24];

interface Props {
  slots: SlotInterval[];
  jobs?: DayJob[];
  /** Minutes; draws the "this job" marker. */
  pickupMin?: number;
  showTicks?: boolean;
}

const pct = (min: number) => `${(Math.min(Math.max(min, 0), DAY_MIN) / DAY_MIN) * 100}%`;

/** 24h strip: shift slots as coloured bands, jobs as dots, the new pickup as a line. */
const DayTimeline = ({ slots, jobs = [], pickupMin, showTicks }: Props) => (
  <div className="mx-timeline">
    <div className="mx-timeline__track">
      {slots.map((slot, i) => {
        const type = getShiftType(slot.shiftType);
        return (
          <Tooltip
            key={i}
            title={`${type.label} ${formatMinutes(slot.start)}–${formatMinutes(slot.end)}${
              slot.locationType ? ` · ${slot.locationType}` : ""
            }`}
          >
            <span
              className="mx-timeline__slot"
              style={{
                left: pct(slot.start),
                width: `calc(${pct(slot.end)} - ${pct(slot.start)})`,
                background: type.color,
              }}
            />
          </Tooltip>
        );
      })}
      {jobs
        .filter((j) => j.pickupMin !== undefined)
        .map((job) => (
          <Tooltip key={job.pageId} title={`${formatMinutes(job.pickupMin)} · ${job.label}`}>
            <span className="mx-timeline__job" style={{ left: pct(job.pickupMin) }} />
          </Tooltip>
        ))}
      {pickupMin !== undefined && (
        <Tooltip title={`This job · ${formatMinutes(pickupMin)}`}>
          <span className="mx-timeline__pickup" style={{ left: pct(pickupMin) }} />
        </Tooltip>
      )}
    </div>
    {showTicks && (
      <div className="mx-timeline__ticks">
        {TICKS.map((h) => (
          <span key={h} style={{ left: pct(h * 60) }}>
            {String(h).padStart(2, "0")}
          </span>
        ))}
      </div>
    )}
  </div>
);

export default DayTimeline;
