import React, { useCallback, useEffect, useRef, useState } from "react";
import { Tooltip } from "antd";
import { FlagFilled, MailOutlined, PhoneOutlined } from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { Pill } from "../../common/ui";
import { FLAG_COLORS, StaffRow, useStaffQuery } from "./staffApi";
import "./Driver.scss";

const SEARCH_DEBOUNCE_MS = 400;

/**
 * Loads a staff list with a debounced server-side search. Stale replies from
 * earlier searches are ignored and a timeout surfaces as `loadFailed`.
 */
export const useStaffList = (type: string, userRole?: any) => {
  const { projects, adminUserRoles } = useSelector((state: RootState) => state.auth);
  const queryStaff = useStaffQuery(type, userRole);
  const [rows, setRows] = useState<StaffRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [search, setSearch] = useState("");
  const searchRef = useRef("");
  const searchTimeout = useRef<any>();
  const requestSeq = useRef(0);
  const mounted = useRef(true);
  // Latest query without making `load` depend on it (roles arrive later).
  const queryRef = useRef(queryStaff);
  queryRef.current = queryStaff;

  const load = useCallback(async (text = searchRef.current) => {
    const seq = ++requestSeq.current;
    setLoading(true);
    const result = await queryRef.current(text);
    if (!mounted.current || seq !== requestSeq.current) return;
    setLoading(false);
    setLoadFailed(!result);
    if (result) setRows(result);
  }, []);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(searchTimeout.current);
    };
  }, []);

  useEffect(() => {
    if (projects?.adminUserId && adminUserRoles) load();
  }, [projects?.adminUserId, adminUserRoles, load]);

  const onSearch = (value: string) => {
    setSearch(value);
    searchRef.current = value;
    clearTimeout(searchTimeout.current);
    searchTimeout.current = setTimeout(() => load(value), SEARCH_DEBOUNCE_MS);
  };

  return { rows, loading, loadFailed, search, onSearch, load };
};

export const PersonCell = ({ row }: { row: StaffRow }) => (
  <div className="mx-staff__person">
    <span className="mx-staff__avatar">{row.initials}</span>
    <div className="mx-staff__person-text">
      <div className="mx-staff__name">{row.name}</div>
      {(row.customId || row.beamId) && (
        <div className="mx-staff__sub">
          {[row.customId && `ID ${row.customId}`, row.beamId].filter(Boolean).join(" · ")}
        </div>
      )}
    </div>
  </div>
);

export const ContactCell = ({ row }: { row: StaffRow }) =>
  row.email || row.phone ? (
    <div className="mx-staff__contact">
      {row.email && (
        <div>
          <MailOutlined /> {row.email}
        </div>
      )}
      {row.phone && (
        <div className="mx-staff__sub">
          <PhoneOutlined /> {row.phone}
        </div>
      )}
    </div>
  ) : (
    <span className="mx-staff__muted">No contact details</span>
  );

export const RoleCell = ({ row }: { row: StaffRow }) =>
  row.roleName ? (
    <Pill tone="blue" plain>
      {row.roleName}
    </Pill>
  ) : (
    <span className="mx-staff__muted">—</span>
  );

/** The colour flag set on the user from the dispatch dashboard. */
export const FlagCell = ({ row }: { row: StaffRow }) =>
  row.flag ? (
    <Tooltip title={`Flagged ${row.flag}`}>
      <FlagFilled
        className="mx-staff__flag"
        style={{ color: FLAG_COLORS[`${row.flag}`.toLowerCase()] || FLAG_COLORS.gray }}
      />
    </Tooltip>
  ) : (
    <span className="mx-staff__muted">—</span>
  );

export const countCaption = (count: number, noun: string, searching: boolean) =>
  `${count} ${searching ? "matching " : ""}${count === 1 ? noun : `${noun}s`}`;
