import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button } from "antd";
import type { ColumnsType } from "antd/es/table";
import { Moment } from "moment";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import {
  getAccountsRequestPublishTopic,
  getAccountsSubscriptionTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { DataTableCard, EmptyState, PageHeader, Pill, RowActions } from "../../common/ui";
import EditRecurringModal from "./EditRecurringModal";
import { RecurringRecord, isScheduleOk, useRecurringQuery, useScheduleApi } from "./recurringApi";
import {
  ScheduleStatus,
  describePattern,
  describeRange,
  formatTime,
  getScheduleStatus,
  listOccurrences,
  nextOccurrence,
} from "./recurrence";

import "../Dashboard.scss";
import "./Recurring.scss";

const SEARCH_DEBOUNCE_MS = 400;

interface RecurringRow {
  key: string;
  patient: string;
  route: string;
  serviceType?: string;
  pattern: string;
  time?: string;
  returnTime?: string;
  range: string;
  /** undefined when the schedule has no end date */
  rides?: number;
  next?: Moment;
  status: ScheduleStatus;
  record: RecurringRecord;
}

const capitalizeWords = (str = "") => str.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());

const placeName = (name?: string, location?: any) =>
  name || location?.attributes?.address || location?.label || "";

const toRow = (record: RecurringRecord): RecurringRow => {
  const attrs = record?.data?.events?.[0]?.unstructuredAttributes || {};
  const schedule = record?.data?.schedule;
  const { dates, unbounded } = listOccurrences(schedule);
  const from = placeName(attrs.pickupLocationName, attrs.pickupLocation);
  const to = placeName(attrs.dropoffLocationName, attrs.dropoffLocation);
  return {
    key: `${record.id}`,
    patient:
      capitalizeWords(record.patientFullName) ||
      [attrs.patientFirstName, attrs.patientLastName].filter(Boolean).join(" "),
    route: from || to ? `${from || "?"} → ${to || "?"}` : "",
    serviceType: attrs.serviceType,
    pattern: describePattern(schedule),
    time: formatTime(attrs.pickupTime),
    returnTime: attrs.serviceType !== "O/W" ? formatTime(attrs.returnPickupTime) : undefined,
    range: describeRange(schedule),
    rides: unbounded ? undefined : dates.length,
    next: nextOccurrence(schedule),
    status: getScheduleStatus(schedule),
    record,
  };
};

const DATA_COLUMNS: ColumnsType<RecurringRow> = [
  {
    title: "Patient",
    key: "patient",
    sorter: (a, b) => a.patient.localeCompare(b.patient),
    render: (_, r) => (
      <div>
        <div className="mx-recurring-list__name">{r.patient || "Unnamed patient"}</div>
        {r.route && (
          <div className="mx-recurring-list__sub mx-recurring-list__route" title={r.route}>
            {r.route}
          </div>
        )}
      </div>
    ),
  },
  {
    title: "Repeats",
    key: "pattern",
    render: (_, r) => (
      <div>
        <div>{r.time ? `${r.pattern} at ${r.time}` : r.pattern}</div>
        <div className="mx-recurring-list__sub">
          {[r.serviceType, r.returnTime && `return ${r.returnTime}`].filter(Boolean).join(" · ") ||
            (r.time ? "" : "No pickup time")}
        </div>
      </div>
    ),
  },
  {
    title: "Dates",
    key: "range",
    render: (_, r) => (
      <div>
        <div>{r.range || <span className="mx-recurring-list__muted">Not set</span>}</div>
        {r.rides !== undefined && (
          <div className="mx-recurring-list__sub">
            {r.rides} {r.rides === 1 ? "ride" : "rides"}
          </div>
        )}
      </div>
    ),
  },
  {
    title: "Next ride",
    key: "next",
    sorter: (a, b) => (a.next?.valueOf() ?? Infinity) - (b.next?.valueOf() ?? Infinity),
    render: (_, r) =>
      r.next ? (
        r.next.format("ddd, MMM D")
      ) : (
        <span className="mx-recurring-list__muted">None</span>
      ),
  },
  {
    title: "Status",
    key: "status",
    sorter: (a, b) => a.status.order - b.status.order,
    render: (_, r) => <Pill tone={r.status.tone}>{r.status.label}</Pill>,
  },
];

/** Recurring bookings: a booking template plus the days it turns into rides. */
const RecurringModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, componentUuid }) => {
  const { encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const queryRecurring = useRecurringQuery();
  const api = useScheduleApi();
  const uuid = useRef(componentUuid || generateUUID()).current;

  const [records, setRecords] = useState<RecurringRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [search, setSearch] = useState("");
  // undefined = closed, {} = new, { data } = duplicate, { scheduleId, data } = edit
  const [editing, setEditing] = useState<any>(undefined);

  const searchRef = useRef("");
  const searchTimeout = useRef<any>();
  const requestSeq = useRef(0);
  const mounted = useRef(true);

  const load = useCallback(
    async (text = searchRef.current) => {
      const seq = ++requestSeq.current;
      setLoading(true);
      const result = await queryRecurring(text);
      // Ignore stale replies from earlier searches.
      if (!mounted.current || seq !== requestSeq.current) return;
      setLoading(false);
      setLoadFailed(!result);
      if (result) setRecords(result);
    },
    [queryRecurring]
  );

  useEffect(() => {
    mounted.current = true;
    document.title = "Recurring | Beam";
    return () => {
      mounted.current = false;
      clearTimeout(searchTimeout.current);
    };
  }, []);

  useEffect(() => {
    if (!projects?.adminUserId) return;
    load();
    // Refresh billing accounts for the booking form.
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getAccountsSubscriptionTopic(encrypted_token?.connectionId),
      undefined,
      uuid
    );
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getAccountsRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        userId: encrypted_token?.userId,
        cudbServiceId: encrypted_token?.cudbServiceId || encrypted_token?.serviceId,
      })
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects]);

  const onSearch = (value: string) => {
    setSearch(value);
    searchRef.current = value;
    clearTimeout(searchTimeout.current);
    searchTimeout.current = setTimeout(() => load(value), SEARCH_DEBOUNCE_MS);
  };

  const deleteRecurring = async (row: RecurringRow) => {
    setRecords((current) => current.filter((r) => `${r.id}` !== row.key));
    const response = await api.remove({ objectId: row.key });
    if (!mounted.current) return;
    if (isScheduleOk(response)) {
      pushNotification("Recurring booking deleted", "success", "TOP_CENTER", 3000);
    } else {
      pushNotification("Couldn't delete the recurring booking. Please try again.", "error", "TOP_CENTER", 4000);
    }
    load();
  };

  const closeEditor = () => {
    setEditing(undefined);
    dispatch({ type: "SET_SELECTED_PAGE", payload: { page: undefined } });
  };

  const rows = useMemo(
    () =>
      records
        .map(toRow)
        .sort(
          (a, b) =>
            a.status.order - b.status.order ||
            (a.next?.valueOf() ?? Infinity) - (b.next?.valueOf() ?? Infinity)
        ),
    [records]
  );

  // Columns stay static; handlers are read through a ref.
  const handlers = useRef<any>({});
  handlers.current = { setEditing, deleteRecurring };

  const columns: ColumnsType<RecurringRow> = useMemo(
    () => [
      ...DATA_COLUMNS,
      {
        title: "",
        key: "actions",
        align: "right",
        width: 120,
        render: (_, r) => (
          <RowActions
            onEdit={() =>
              handlers.current.setEditing({ scheduleId: r.record.id, data: r.record.data })
            }
            onCopy={() => handlers.current.setEditing({ data: r.record.data })}
            onDelete={() => handlers.current.deleteRecurring(r)}
            deleteConfirm={`Delete the recurring booking for ${r.patient || "this patient"}? No new rides will be created; rides already created stay.`}
          />
        ),
      },
    ],
    []
  );

  const count = rows.length;
  const noun = count === 1 ? "recurring booking" : "recurring bookings";

  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load recurring bookings"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={() => load()}>
          Try again
        </Button>
      }
    />
  ) : search.trim() ? (
    <EmptyState title="No matching recurring bookings" description="Try a different patient name." />
  ) : (
    <EmptyState
      title="No recurring bookings yet"
      description="Set up a booking once, e.g. dialysis every Mon, Wed & Fri, and a ride is created for each date."
      action={{ label: "New recurring booking", onClick: () => setEditing({}) }}
    />
  );

  return (
    <div className="mx-recurring-list">
      <PageHeader
        title="Recurring"
        subtitle="Bookings that repeat on a schedule. Each date becomes a ride automatically."
        search={{ value: search, onChange: onSearch, placeholder: "Search by patient name", loading }}
        primaryAction={{ label: "New recurring booking", onClick: () => setEditing({}) }}
      />

      <DataTableCard<RecurringRow>
        rowKey="key"
        loading={loading}
        clickable
        caption={search.trim() ? `${count} matching ${noun}` : `${count} ${noun}`}
        columns={columns}
        dataSource={rows}
        empty={emptyState}
        scroll={{ x: true }}
        onRow={(r) => ({
          onClick: () => setEditing({ scheduleId: r.record.id, data: r.record.data }),
        })}
      />

      {editing !== undefined && (
        <EditRecurringModal
          socket={socket}
          student={editing}
          adminRoles={adminUserRoles}
          onClose={closeEditor}
          onAdd={() => {
            closeEditor();
            load();
          }}
        />
      )}
    </div>
  );
};

export default RecurringModal;
