// Vehicles are `asset` users; their details live at /persistent/static/asset
// and their availability at /nonpersistent/static/live/status = { name, color }.
// Type and assigned driver come from the ride-dps "vehicle projects" that the
// booking form (common/VehicleInput) also reads — read-only here.

export const REQUEST_TIMEOUT_MS = 15000;

/** Format of every date string stored on the asset (maintenance, last service). */
export const STORED_DATE_FORMAT = "MM/DD/YYYY HH:mm:ss";

export interface VehicleAsset {
  id: string | number;
  static?: Record<string, any>;
  status?: string;
  maintenance?: VehicleMaintenance;
}

export interface VehicleMaintenance {
  location?: { label?: string } & Record<string, any>;
  typeOfWork?: string;
  dropoffDateTime?: string;
  pickupDateTime?: string;
  additionalInformation?: string;
  driverPickup?: { id?: string; beamId?: string };
  driverDropoff?: { id?: string; beamId?: string };
}

export interface VehicleRow {
  key: string;
  name: string;
  licensePlate?: string;
  makeAndModel?: string;
  year?: string;
  vin?: string;
  permit?: string;
  status?: string;
  maintenance?: VehicleMaintenance;
  typeName?: string;
  driverName?: string;
  asset: VehicleAsset;
}

/** Status colours as stored in `status.name`, with the hex kept in `status.color`. */
export const STATUS_OPTIONS: { value: string; label: string; hex: string }[] = [
  { value: "green", label: "Available", hex: "#40CC52" },
  { value: "red", label: "Unavailable", hex: "#FF5F25" },
];

const PILL_TONES: PillTone[] = ["green", "amber", "red", "blue", "purple", "gray"];

export const statusDisplay = (status?: string): { label: string; tone: PillTone } => {
  const known = STATUS_OPTIONS.find((o) => o.value === status);
  if (known) return { label: known.label, tone: known.value as PillTone };
  if (!status) return { label: "Not set", tone: "gray" };
  // Set elsewhere (e.g. the driver board) with a colour we don't label.
  return { label: "Other", tone: PILL_TONES.includes(status as PillTone) ? (status as PillTone) : "gray" };
};

/** Parses a stored date string; undefined when missing or unreadable. */
export const parseStoredDate = (value?: string): Moment | undefined => {
  if (!value) return undefined;
  const strict = moment(value, STORED_DATE_FORMAT, true);
  if (strict.isValid()) return strict;
  const loose = moment(new Date(value));
  return loose.isValid() ? loose : undefined;
};

export const formatMaintenanceMessage = (maintenance: VehicleMaintenance | undefined, vehicleName: string) => {
  const dropoff = parseStoredDate(maintenance?.dropoffDateTime);
  if (!maintenance || !dropoff) return "";
  const { location, typeOfWork, additionalInformation, driverDropoff, driverPickup } = maintenance;
  let message = [
    `${dropoff.format("hh:mm A")} - ${dropoff.format("MMM-DD")}`,
    `Vehicle Maintenance for ${vehicleName || "Vehicle"}`,
    location?.label ? `at ${location.label}` : "",
    typeOfWork ? `for ${typeOfWork}` : "",
  ]
    .filter(Boolean)
    .join(" ");
  if (additionalInformation) message += `. ${additionalInformation}`;
  if (driverDropoff?.beamId) message += `. Dropoff Driver - ${driverDropoff.beamId}`;
  if (driverPickup?.beamId) message += `. Pickup Driver - ${driverPickup.beamId}`;
  return message;
};

export type MaintenanceState =
  | { kind: "none" }
  | { kind: "upcoming" | "inShop" | "done"; dropoff: Moment; pickup?: Moment };

export const maintenanceState = (maintenance?: VehicleMaintenance): MaintenanceState => {
  const dropoff = parseStoredDate(maintenance?.dropoffDateTime);
  if (!dropoff) return { kind: "none" };
  const pickup = parseStoredDate(maintenance?.pickupDateTime);
  const now = moment();
  if (dropoff.isAfter(now)) return { kind: "upcoming", dropoff, pickup };
  if (!pickup || pickup.isAfter(now)) return { kind: "inShop", dropoff, pickup };
  return { kind: "done", dropoff, pickup };
};

/**
 * Lists the org's vehicles. Resolves null when the request fails or times out
 * (GET_AGGREGATE doesn't call back on errors).
 */
export const useVehicleQuery = () => {
  const dispatch = useDispatch();
  const { projects } = useSelector((state: RootState) => state.auth);

  return useCallback(
    () =>
      new Promise<VehicleAsset[] | null>((resolve) => {
        const timer = setTimeout(() => resolve(null), REQUEST_TIMEOUT_MS);
        dispatch(
          GET_AGGREGATE({
            requestData: {
              select: {
                index: {
                  searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
                  searchQuery: `@userType:{asset}@serviceId:{'${formatForRedis(
                    projects?.userServiceId
                  )}'}`,
                  searchOptions: "TIMEOUT 5000",
                },
                load: {
                  id: "$.objectId",
                  static: "$.persistent.static.asset",
                  type: "$.persistent.static.asset.type",
                  name: "$.persistent.static.asset.name",
                  status: "$.nonpersistent.static.live.status.name",
                  licensePlate: "$.persistent.static.asset.licensePlate",
                  makeAndModel: "$.persistent.static.asset.makeAndModel",
                  vin: "$.persistent.static.asset.vin",
                  permit: "$.persistent.static.asset.permit",
                  maintenance: "$.persistent.static.asset.maintenance",
                },
              },
              apply: { expression: "", name: "" },
              result: {},
              filter: { expression: "exists(@type) && @type=='vehicle' && exists(@name)" },
              anyStatus: false,
            },
            callback: (response: VehicleAsset[]) => {
              clearTimeout(timer);
              resolve(response || []);
            },
          })
        );
      }),
    [dispatch, projects?.userServiceId]
  );
};

export interface VehicleLinks {
  /** Vehicle projects keyed by asset objectId (`vehicleId`). */
  byVehicleId: Record<string, any>;
  byName: Record<string, any>;
  typeNames: Record<string, string>;
}

const indexProjects = (list: any[]) => {
  const byVehicleId: Record<string, any> = {};
  const byName: Record<string, any> = {};
  (list || []).forEach((p) => {
    if (!p) return;
    if (p.vehicleId !== undefined) byVehicleId[`${p.vehicleId}`] = p;
    if (p.name) byName[`${p.name}`.trim().toLowerCase()] = p;
  });
  return { byVehicleId, byName };
};

/**
 * Vehicle projects (assigned driver, type) and vehicle type names. Starts from
 * whatever the booking form already cached in redux, then refreshes.
 */
export const useVehicleLinks = (socket: ISocket, uuid: string): VehicleLinks => {
  const { projects, encrypted_token, vehicles, vehicleTypes } = useSelector(
    (state: RootState) => state.auth
  );
  const { getUserRequestPayload } = useSocketActions();
  const [projectIndex, setProjectIndex] = useState(() =>
    indexProjects((vehicles || []).map((v: any) => v?.obj))
  );
  const [typeNames, setTypeNames] = useState<Record<string, string>>(() =>
    Object.fromEntries((vehicleTypes || []).map((t: any) => [`${t?.id}`, t?.name]))
  );
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    if (!projects?.userServiceId) return undefined;
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getVehiclesSubscriptionTopic(encrypted_token?.connectionId),
      (response: any) => {
        const list = response?.response?.data?.projects;
        if (mounted.current && Array.isArray(list)) setProjectIndex(indexProjects(list));
      },
      uuid
    );
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getVehiclesPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({ userId: encrypted_token?.userId, cudbServiceId: projects?.userServiceId })
    );

    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      getVehicleTypesTopic(encrypted_token?.connectionId),
      (response: any) => {
        const list = response?.data?.[0]?.[0];
        if (!mounted.current || !Array.isArray(list)) return;
        setTypeNames(Object.fromEntries(list.map((t: any) => [`${t?._id}`, t?.name])));
      },
      uuid
    );
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(projects?.adminUserId, "$", getVehicleTypesPath()),
      getVehicleTypesTopic(encrypted_token?.connectionId),
      projects?.userServiceId
    );
    return () => {
      mounted.current = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.userServiceId]);

  return { ...projectIndex, typeNames };
};

export const toVehicleRow = (asset: VehicleAsset, links: VehicleLinks): VehicleRow => {
  const s = asset?.static || {};
  const project =
    links.byVehicleId[`${asset?.id}`] ||
    (s.name ? links.byName[`${s.name}`.trim().toLowerCase()] : undefined);
  const typeId = project?.typeId ?? s.typeId;
  return {
    key: `${asset?.id}`,
    name: s.name || "",
    licensePlate: s.licensePlate,
    makeAndModel: s.makeAndModel,
    year: s.year,
    vin: s.vin,
    permit: s.permit,
    status: asset?.status,
    maintenance: asset?.maintenance,
    typeName: (typeId !== undefined && links.typeNames[`${typeId}`]) || s.vehicleType,
    driverName: project?.assosiatedUserBeamId || s.alternativeIds?.beamId,
    asset,
  };
};
