import React from "react";
import { Button } from "antd";
import { UserAddOutlined } from "@ant-design/icons";
import { ActionCell, RowActions, ShiftCell, StatusCell } from "./components/cells";

/**
 * Built once per mount. Cells call through `actions`, which always delegates
 * to the latest handlers, so the columns never need rebuilding (rebuilding
 * them used to reset widths/visibility on every search).
 */
export const buildColumns = (actions: RowActions) => [
  {
    title: "Status",
    key: "pageStatus",
    dataIndex: "pageStatus",
    minWidth: 100,
    render: (status: string, record) => (
      <StatusCell status={status} record={record} actions={actions} />
    ),
  },
  {
    title: "Action",
    key: "action",
    dataIndex: "action",
    minWidth: 100,
    render: (_: any, record) => <ActionCell record={record} actions={actions} />,
  },
  { title: "Dispatch instructions", key: "instructions", dataIndex: "instructions", minWidth: 100 },
  { title: "Patient name", key: "patientName", dataIndex: "patientName", minWidth: 100 },
  {
    title: "Driver",
    key: "driverNameFull",
    dataIndex: "driverNameFull",
    width: 150,
    render: (text: string, record) =>
      !record.isShift && !record.driverId && record.pageStatus !== "black" ? (
        <Button
          size="small"
          type="dashed"
          icon={<UserAddOutlined />}
          onClick={(e) => {
            e.stopPropagation();
            actions.onAction("assignment", record);
          }}
        >
          Assign driver
        </Button>
      ) : (
        text
      ),
  },
  {
    title: "Shift",
    key: "shift",
    dataIndex: "shift",
    minWidth: 100,
    render: (_: any, record) => <ShiftCell record={record} />,
  },
  {
    title: "Vehicle",
    key: "vehicleName",
    dataIndex: "vehicleName",
    minWidth: 100,
    sorter: (a, b) => a.vehicleName?.localeCompare(b?.vehicleName),
  },
  { title: "Time", key: "pickupTime", dataIndex: "pickupTime", minWidth: 100 },
  { title: "Date", key: "pickupDate", dataIndex: "pickupDate", minWidth: 100 },
  { title: "Transfer type", key: "transferType", dataIndex: "transferType", minWidth: 100 },
  { title: "Equipment", key: "equipmentNeeded", dataIndex: "equipmentNeeded", minWidth: 100 },
  {
    title: "Description",
    key: "description",
    dataIndex: "description",
    width: 400,
    render: (text: string) => <div style={{ whiteSpace: "pre-wrap" }}>{text}</div>,
  },
];
