import React, { useMemo, useState } from "react";
import { Button, message, Segmented, Tooltip } from "antd";
import { ThunderboltOutlined } from "@ant-design/icons";
import moment from "moment";
import { EmptyState, Pill } from "../../../common/ui";
import { getShiftType } from "../../../common/shiftTypes";
import {
  DayJob,
  DriverEvaluation,
  DriverRecord,
  evaluateDriver,
  formatMinutes,
  planAssignments,
  PlanResult,
  rankDrivers,
  rowToDayJob,
} from "../../../common/driverAvailability/availability";
import { useDriverDay } from "../../../common/driverAvailability/useDriverDay";
import { STATUS_OPTIONS, statusColorMapping } from "../constants";
import { RideRow } from "../types";
import PlanPanel from "./PlanPanel";
import QuickAssignModal from "./QuickAssignModal";
import "./DispatchBoard.scss";

// Rides don't carry a duration; draw each as a one-hour block.
const JOB_BLOCK_MIN = 60;
const DRAG_TYPE = "application/x-beam-ride";
const APPLY_SPACING_MS = 600;

type BoardJob = DayJob & { pending?: boolean; ghost?: boolean };
type LaneFilter = "working" | "all";

interface Props {
  day: number;
  rows: RideRow[];
  /** Assign without the form; resolves false if the form must be used. */
  onQuickAssign: (row: RideRow, driver: DriverRecord) => Promise<boolean>;
  /** pageId -> driver currently being assigned. */
  pending: Record<string, DriverRecord>;
  onOpenJob: (row: RideRow, preferredDriverId?: string) => void;
  onEditJob: (row: RideRow) => void;
}

/** Packs overlapping blocks into stacked sub-rows. */
const packJobs = (jobs: BoardJob[]) => {
  const rowsEnd: number[] = [];
  return jobs
    .filter((j) => j.pickupMin !== undefined)
    .sort((a, b) => a.pickupMin - b.pickupMin)
    .map((job) => {
      let row = rowsEnd.findIndex((end) => end <= job.pickupMin);
      if (row === -1) row = rowsEnd.push(0) - 1;
      rowsEnd[row] = job.pickupMin + JOB_BLOCK_MIN;
      return { job, row };
    });
};

const statusLabel = (color?: string) =>
  STATUS_OPTIONS.find((s) => s.color === color)?.label ?? "Pending";

const JobChip = ({
  job,
  style,
  onOpen,
  onEdit,
}: {
  job: BoardJob;
  style?: React.CSSProperties;
  onOpen: () => void;
  onEdit: () => void;
}) => {
  const row: RideRow = job.raw;
  const color = statusColorMapping[job.status] ?? statusColorMapping.purple;
  const draggable = !job.ghost && !job.pending && job.status !== "black";
  const classes = [
    "mx-board__job",
    job.status === "black" && "mx-board__job--cancelled",
    job.pending && "mx-board__job--pending",
    job.ghost && "mx-board__job--ghost",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <Tooltip
      title={
        <div>
          <strong>{job.label}</strong>
          <div>
            {job.pickupMin !== undefined ? formatMinutes(job.pickupMin) : "No pickup time"} ·{" "}
            {job.ghost ? "Suggested" : job.pending ? "Assigning…" : statusLabel(job.status)}
          </div>
          {row?.address && <div>From: {row.address}</div>}
          {row?.dropoffAddress && <div>To: {row.dropoffAddress}</div>}
          {row?.transferType && <div>{row.transferType}</div>}
          {draggable && (
            <div style={{ opacity: 0.7, marginTop: 4 }}>
              Drag onto a driver to assign · click for details · double-click to edit
            </div>
          )}
        </div>
      }
    >
      <div
        className={classes}
        style={{ ...style, borderLeftColor: job.ghost ? undefined : color }}
        draggable={draggable}
        onDragStart={(e) => {
          e.dataTransfer.setData(DRAG_TYPE, job.pageId);
          e.dataTransfer.effectAllowed = "move";
        }}
        onClick={job.ghost ? undefined : onOpen}
        onDoubleClick={job.ghost ? undefined : onEdit}
      >
        <span className="mx-board__job-time">
          {job.pickupMin !== undefined ? formatMinutes(job.pickupMin) : "--:--"}
        </span>
        <span className="mx-board__job-label">
          {job.pending ? "Assigning… " : ""}
          {job.label}
        </span>
      </div>
    </Tooltip>
  );
};

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

const DispatchBoard = ({ day, rows, onQuickAssign, pending, onOpenJob, onEditJob }: Props) => {
  // Pending assignments are shown in their new lane straight away.
  const jobs: BoardJob[] = useMemo(
    () =>
      rows
        .filter((r) => !r.isShift)
        .map((row) => {
          const job: BoardJob = rowToDayJob(row);
          const target = pending[job.pageId];
          return target ? { ...job, driverIds: [target.id], pending: true } : job;
        }),
    [rows, pending]
  );
  const { drivers, slotsByDriver, timeOffDriverIds, loading } = useDriverDay({ day, jobs });
  const [laneFilter, setLaneFilter] = useState<LaneFilter>("working");
  const [dropTarget, setDropTarget] = useState<string>();
  const [confirm, setConfirm] = useState<{ job: BoardJob; driverId: string }>();
  const [plan, setPlan] = useState<PlanResult | null>(null);
  const [applying, setApplying] = useState<{ done: number; total: number }>();

  const baseOptions = { slotsByDriver, timeOffDriverIds, jobs, day };
  const evaluations = useMemo(
    () => rankDrivers(drivers, baseOptions),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [drivers, slotsByDriver, timeOffDriverIds, jobs, day]
  );

  const unassigned = jobs.filter((j) => j.driverIds.length === 0 && j.status !== "black");
  const ghostsByDriver = useMemo(() => {
    const map: Record<string, BoardJob[]> = {};
    plan?.proposals.forEach(({ job, evaluation }) => {
      (map[evaluation.driver.id] = map[evaluation.driver.id] || []).push({ ...job, ghost: true });
    });
    return map;
  }, [plan]);

  const lanes = evaluations
    .filter(
      (e) =>
        laneFilter === "all" ||
        e.slots.length > 0 ||
        e.jobs.length > 0 ||
        ghostsByDriver[e.driver.id]?.length
    )
    .sort((a, b) => {
      const aStart = a.slots[0]?.start ?? Infinity;
      const bStart = b.slots[0]?.start ?? Infinity;
      return aStart - bStart || a.driver.name.localeCompare(b.driver.name);
    });

  // Fit the visible window to the day's activity, in whole hours.
  const [windowStart, windowEnd] = useMemo(() => {
    const points = [
      ...jobs.map((j) => j.pickupMin).filter((m) => m !== undefined),
      ...evaluations.flatMap((e) => e.slots.flatMap((s) => [s.start, s.end])),
    ];
    const min = Math.min(6 * 60, ...points);
    const max = Math.max(20 * 60, ...points.map((p) => p + JOB_BLOCK_MIN));
    return [Math.max(0, Math.floor(min / 60) * 60), Math.min(30 * 60, Math.ceil(max / 60) * 60)];
  }, [jobs, evaluations]);

  const span = windowEnd - windowStart;
  const pct = (min: number) =>
    `${((Math.min(Math.max(min, windowStart), windowEnd) - windowStart) / span) * 100}%`;
  const hours = Array.from({ length: span / 60 + 1 }, (_, i) => windowStart + i * 60);
  const isToday = moment(day).isSame(moment(), "day");
  const nowMin = moment().diff(moment().startOf("day"), "minutes");

  const jobById = (pageId: string) => jobs.find((j) => j.pageId === pageId);
  const driverById = (id: string) => drivers.find((d) => d.id === id);

  /* ------------------------------------------------------------ actions */

  const handleDrop = (e: React.DragEvent, driverId?: string) => {
    e.preventDefault();
    setDropTarget(undefined);
    const job = jobById(e.dataTransfer.getData(DRAG_TYPE));
    if (!job) return;
    if (!driverId) {
      message.info("To remove a driver, open the ride and clear the assignment.");
      return;
    }
    if (job.driverIds[0] === driverId) return;
    setConfirm({ job, driverId });
  };

  const assignJob = async (job: BoardJob, driver: DriverRecord) => {
    const ok = await onQuickAssign(job.raw, driver);
    if (!ok) onOpenJob(job.raw, driver.id);
    return ok;
  };

  const suggestPlan = () =>
    setPlan(planAssignments(unassigned, drivers, { slotsByDriver, timeOffDriverIds, jobs, day }));

  const removeFromPlan = (pageId: string) =>
    setPlan((prev) =>
      prev && {
        ...prev,
        proposals: prev.proposals.filter((p) => p.job.pageId !== pageId),
      }
    );

  const acceptProposal = async (pageId: string) => {
    const proposal = plan?.proposals.find((p) => p.job.pageId === pageId);
    if (!proposal) return;
    removeFromPlan(pageId);
    await assignJob(proposal.job, proposal.evaluation.driver);
  };

  // One at a time, spaced out, so each booking publishes cleanly.
  const acceptAll = async () => {
    const proposals = plan?.proposals || [];
    setApplying({ done: 0, total: proposals.length });
    for (let i = 0; i < proposals.length; i++) {
      removeFromPlan(proposals[i].job.pageId);
      await assignJob(proposals[i].job, proposals[i].evaluation.driver);
      setApplying({ done: i + 1, total: proposals.length });
      if (i < proposals.length - 1) await wait(APPLY_SPACING_MS);
    }
    setApplying(undefined);
  };

  const dropProps = (laneId: string, driverId?: string) => ({
    onDragOver: (e: React.DragEvent) => {
      if (e.dataTransfer.types.includes(DRAG_TYPE)) {
        e.preventDefault();
        setDropTarget(laneId);
      }
    },
    onDragLeave: () => setDropTarget((t) => (t === laneId ? undefined : t)),
    onDrop: (e: React.DragEvent) => handleDrop(e, driverId),
  });

  /* ------------------------------------------------------------ render */

  const chip = (job: BoardJob, style?: React.CSSProperties) => (
    <JobChip
      key={`${job.pageId}${job.ghost ? "-ghost" : ""}`}
      job={job}
      style={style}
      onOpen={() => onOpenJob(job.raw)}
      onEdit={() => onEditJob(job.raw)}
    />
  );

  const renderTrack = (laneJobs: BoardJob[], evaluation?: DriverEvaluation) => {
    const packed = packJobs(laneJobs);
    const depth = Math.max(1, ...packed.map((p) => p.row + 1));
    return (
      <div className="mx-board__track" style={{ height: depth * 30 + 10 }}>
        {hours.map((h) => (
          <span key={h} className="mx-board__gridline" style={{ left: pct(h) }} />
        ))}
        {evaluation?.slots.map((slot, i) => (
          <span
            key={i}
            className="mx-board__slot"
            style={{
              left: pct(slot.start),
              width: `calc(${pct(slot.end)} - ${pct(slot.start)})`,
              background: getShiftType(slot.shiftType).color,
            }}
            title={`${slot.shiftType} ${formatMinutes(slot.start)}–${formatMinutes(slot.end)}${
              slot.locationType ? ` · ${slot.locationType}` : ""
            }`}
          />
        ))}
        {packed.map(({ job, row }) =>
          chip(job, {
            left: pct(job.pickupMin),
            width: `calc(${pct(job.pickupMin + JOB_BLOCK_MIN)} - ${pct(job.pickupMin)})`,
            top: 5 + row * 30,
          })
        )}
        {isToday && nowMin >= windowStart && nowMin <= windowEnd && (
          <span className="mx-board__now" style={{ left: pct(nowMin) }} />
        )}
      </div>
    );
  };

  // Jobs without a pickup time can't sit on the timeline; list them by the name.
  const untimedList = (laneJobs: BoardJob[]) => {
    const untimed = laneJobs.filter((j) => j.pickupMin === undefined);
    return untimed.length > 0 ? (
      <div className="mx-board__untimed">
        <span className="mx-board__muted">No pickup time</span>
        {untimed.map((job) => chip(job))}
      </div>
    ) : null;
  };

  const confirmEvaluation =
    confirm &&
    driverById(confirm.driverId) &&
    evaluateDriver(driverById(confirm.driverId), {
      ...baseOptions,
      pickupMin: confirm.job.pickupMin,
      pageId: confirm.job.pageId,
    });

  const plannable = unassigned.filter((j) => j.pickupMin !== undefined).length;

  return (
    <div className="mx-board-wrap">
      {plan && (
        <PlanPanel
          plan={plan}
          applying={applying}
          onAccept={acceptProposal}
          onDismiss={removeFromPlan}
          onAcceptAll={acceptAll}
          onOpenJob={(pageId) => {
            const job = jobById(pageId);
            if (job) onOpenJob(job.raw);
          }}
          onClose={() => setPlan(null)}
        />
      )}

      <div className="mx-board">
        <div className="mx-board__toolbar">
          <div>
            <strong>{moment(day).format("dddd, MMM D")}</strong>
            <span className="mx-board__muted">
              {" "}
              · {unassigned.length} unassigned ·{" "}
              {evaluations.filter((e) => e.slots.length > 0).length} drivers scheduled
            </span>
          </div>
          <div className="mx-board__toolbar-actions">
            <Tooltip
              title={
                plannable
                  ? "Suggest a driver for every unassigned job. You review before anything is saved."
                  : "No unassigned jobs with a pickup time"
              }
            >
              <Button
                className="mx-btn-primary"
                icon={<ThunderboltOutlined />}
                disabled={!plannable || loading || !!applying}
                onClick={suggestPlan}
              >
                Suggest plan
              </Button>
            </Tooltip>
            <Segmented
              size="small"
              value={laneFilter}
              onChange={(v) => setLaneFilter(v as LaneFilter)}
              options={[
                { label: "Scheduled drivers", value: "working" },
                { label: "All drivers", value: "all" },
              ]}
            />
          </div>
        </div>

        <div className="mx-board__grid">
          <div className="mx-board__row mx-board__row--axis">
            <div className="mx-board__label" />
            <div className="mx-board__axis">
              {hours.map((h) => (
                <span key={h} style={{ left: pct(h) }}>
                  {formatMinutes(h)}
                </span>
              ))}
            </div>
          </div>

          <div className="mx-board__row mx-board__row--unassigned" {...dropProps("unassigned")}>
            <div className="mx-board__label">
              <div className="mx-board__name">Unassigned</div>
              <Pill tone={unassigned.length ? "purple" : "gray"} plain>
                {unassigned.length} {unassigned.length === 1 ? "job" : "jobs"}
              </Pill>
              {untimedList(unassigned)}
            </div>
            {renderTrack(unassigned)}
          </div>

          {lanes.length === 0 && !loading && (
            <EmptyState
              title="No drivers scheduled for this day"
              description="Add them to a shift roster, or show all drivers."
              action={
                laneFilter === "working"
                  ? { label: "Show all drivers", onClick: () => setLaneFilter("all") }
                  : undefined
              }
            />
          )}

          {lanes.map((evaluation) => {
            const laneId = evaluation.driver.id;
            const laneJobs: BoardJob[] = [...evaluation.jobs, ...(ghostsByDriver[laneId] || [])];
            return (
              <div
                key={laneId}
                className={`mx-board__row ${dropTarget === laneId ? "mx-board__row--drop" : ""}`}
                {...dropProps(laneId, laneId)}
              >
                <div className="mx-board__label">
                  <div className="mx-board__name">{evaluation.driver.name}</div>
                  <div className="mx-board__meta">
                    {evaluation.availability === "time-off" ? (
                      <Pill tone="red">Time off</Pill>
                    ) : evaluation.slots.length ? (
                      <Pill tone="green" plain>
                        {evaluation.scheduledHours}h scheduled
                      </Pill>
                    ) : (
                      <Pill tone="gray" plain>
                        Not scheduled
                      </Pill>
                    )}
                    <span className="mx-board__muted">
                      {evaluation.jobs.length} {evaluation.jobs.length === 1 ? "job" : "jobs"}
                    </span>
                  </div>
                  {untimedList(evaluation.jobs)}
                </div>
                {renderTrack(laneJobs, evaluation)}
              </div>
            );
          })}
        </div>
      </div>

      {confirm && confirmEvaluation && (
        <QuickAssignModal
          job={confirm.job}
          evaluation={confirmEvaluation}
          onCancel={() => setConfirm(undefined)}
          onMoreOptions={() => {
            setConfirm(undefined);
            onOpenJob(confirm.job.raw, confirm.driverId);
          }}
          onAssign={async () => {
            await assignJob(confirm.job, confirmEvaluation.driver);
            setConfirm(undefined);
          }}
        />
      )}
    </div>
  );
};

export default DispatchBoard;
