import React, { FC, useEffect, useMemo, useState } from "react";
import { Button, Empty, Modal, Steps, Tag } from "antd";

import ConfirmationModal from "../../../../common/Confirmation";
import { pushNotification } from "utils/notifications";

import { PaymentRequestDraft, PaymentRequestTarget, ProjectMember } from "./types";
import { getPaymentConfig } from "./mockData";
import { money, validatePaymentConfig } from "./paymentConfig";
import { createDraft, membersFor, requestTotal, wizardModeOf } from "./SendPaymentRequest/draft";
import StepConfiguration from "./SendPaymentRequest/StepConfiguration";
import StepRecipients from "./SendPaymentRequest/StepRecipients";
import StepReview from "./SendPaymentRequest/StepReview";
import MemberCustomiseModal from "./SendPaymentRequest/MemberCustomiseModal";

interface Props {
  open: boolean;
  target: PaymentRequestTarget | null;
  onClose: () => void;
  onSent?: (result: { recipients: number; total: number }) => void;
}

/**
 * Send a payment request, in three steps: the configuration it is built
 * on (editable in full), who receives it (with per-member copies when
 * the CFO wants some members on different terms), and a review.
 *
 * The draft is a snapshot: the project's stored configuration is not
 * changed unless the CFO ticks "Also save". Nothing is written anywhere
 * yet - see the TODO in `send`.
 */
const SendPaymentRequestModal: FC<Props> = ({ open, target, onClose, onSent }) => {
  const [step, setStep] = useState(0);
  const [draft, setDraftState] = useState<PaymentRequestDraft | null>(null);
  const [customising, setCustomising] = useState<ProjectMember | null>(null);
  const [confirming, setConfirming] = useState(false);

  const wizardMode = wizardModeOf(target);
  const members = useMemo(() => membersFor(target), [target]);
  const focusIds = (target && target.focusMemberIds) || [];
  const source = target
    ? getPaymentConfig(target.payee ? target.payee.paymentConfigId : target.project ? target.project.paymentConfigId : null)
    : null;
  const subjectName = target
    ? target.payee
      ? target.payee.name
      : target.project
      ? target.project.name
      : ""
    : "";

  useEffect(() => {
    setDraftState(createDraft(target));
    setStep(0);
    setCustomising(null);
    setConfirming(false);
  }, [target, open]);

  const setDraft = (update: (current: PaymentRequestDraft) => PaymentRequestDraft) =>
    setDraftState((current) => (current ? update(current) : current));

  const errors = useMemo(() => (draft ? validatePaymentConfig(draft.config) : []), [draft]);
  const recipients = draft ? draft.recipientIds.length : 0;
  const total = draft ? requestTotal(draft) : 0;
  const currency = draft ? draft.config.currency : "USD";
  const recipientWord = recipients === 1 ? "recipient" : "recipients";

  const send = () => {
    // TODO(backend): publish the payment request - the group configuration
    // snapshot, the recipient ids and each override - over the socket once
    // the endpoint exists. `draft.saveToProject` also writes the config.
    setConfirming(false);
    pushNotification(
      `Payment request sent to ${recipients} ${recipientWord}${draft && draft.saveToProject ? " and configuration saved" : ""}`,
      "success",
      "TOP_CENTER",
      1500
    );
    if (onSent) onSent({ recipients, total });
    onClose();
  };

  const nextDisabled = (step === 0 && errors.length > 0) || (step === 1 && recipients === 0);

  const footer = [
    <Button key="cancel" className="beam-btn orange-btn bordered" onClick={onClose}>
      Cancel
    </Button>,
  ];
  if (draft && step > 0) {
    footer.push(
      <Button key="back" className="beam-btn gray-btn bordered" onClick={() => setStep(step - 1)}>
        Back
      </Button>
    );
  }
  if (draft && step < 2) {
    footer.push(
      <Button key="next" className="beam-btn blue-btn cover" disabled={nextDisabled} onClick={() => setStep(step + 1)}>
        Next
      </Button>
    );
  }
  if (draft && step === 2) {
    footer.push(
      <Button key="send" className="beam-btn green-btn cover" disabled={recipients === 0} onClick={() => setConfirming(true)}>
        Send to {recipients} {recipientWord}
      </Button>
    );
  }

  return (
    <>
      <Modal
        visible={open}
        width={1040}
        onCancel={onClose}
        className="beam-modal cfo-action-modal cfo-wizard"
        bodyStyle={{ maxHeight: "72vh", overflow: "auto" }}
        title={
          <div className="cfo-wizard__title">
            <div className="cfo-action-modal__title">
              <span>Send Payment Request</span>
              {subjectName && <Tag color="geekblue">{subjectName}</Tag>}
              {draft && (
                <span className="cfo-action-modal__scope">
                  {recipients} {recipientWord} · {money(total, currency)}
                </span>
              )}
            </div>
            {draft && (
              <Steps
                size="small"
                current={step}
                className="cfo-wizard__steps"
                onChange={(next) => next < step && setStep(next)}
                items={[
                  { title: "Configuration", description: errors.length ? `${errors.length} to fix` : "Review and adjust" },
                  { title: "Recipients", description: draft.mode === "custom" ? "Customise members" : "Same for everyone" },
                  { title: "Review & send" },
                ]}
              />
            )}
          </div>
        }
        footer={footer}
      >
        {!draft && (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description={
              subjectName
                ? `${subjectName} has no payment configuration attached. Attach one from the admin portal's Payment Configuration screen before sending a request.`
                : "Select a project or payee first."
            }
          />
        )}

        {draft && source && step === 0 && (
          <StepConfiguration
            draft={draft}
            setDraft={setDraft}
            errors={errors}
            wizardMode={wizardMode}
            source={source}
            subjectName={subjectName}
          />
        )}
        {draft && step === 1 && (
          <StepRecipients
            draft={draft}
            setDraft={setDraft}
            members={members}
            wizardMode={wizardMode}
            focusIds={focusIds}
            onCustomise={setCustomising}
          />
        )}
        {draft && step === 2 && (
          <StepReview draft={draft} members={members} wizardMode={wizardMode} subjectName={subjectName} />
        )}
      </Modal>

      {draft && customising && (
        <MemberCustomiseModal
          key={customising.id}
          member={customising}
          draft={draft}
          onClose={() => setCustomising(null)}
          onApply={(request) => {
            const id = customising.id;
            setDraft((current) => ({
              ...current,
              overrides: { ...current.overrides, [id]: request },
              recipientIds:
                current.recipientIds.indexOf(id) === -1 ? current.recipientIds.concat(id) : current.recipientIds,
            }));
            setCustomising(null);
          }}
        />
      )}

      {confirming && draft && (
        <ConfirmationModal
          message={`Send a payment request to ${recipients} ${recipientWord} for ${money(total, currency)}?`}
          onClose={() => setConfirming(false)}
          handleConfirm={send}
        />
      )}
    </>
  );
};

export default SendPaymentRequestModal;
