import React, { FC, useState } from "react";
import { Button, Form, Input, InputNumber, Modal, Table } from "antd";
import type { ColumnsType } from "antd/es/table";
import type { FormListFieldData } from "antd/es/form/FormList";
import { PlusOutlined } from "@ant-design/icons";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { itemPath, nameKey, useAdminUserUpdate } from "../Pricing/adminCollection";
import { EmptyState, FormModal, FormSection, Pill, RowActions } from "../../common/ui";

// Persisted item shape (read by common/EquipmentInput):
//   { key, name, description, maxWeight }  — maxWeight kept as a string like the old text input.
export interface EquipmentItem {
  key: string;
  name: string;
  description?: string;
  maxWeight?: number | string;
}

export interface EquipmentType {
  _id: string;
  name: string;
  equipments?: EquipmentItem[];
}

export const TYPE_NAME_MAX = 60;
const ITEM_NAME_MAX = 60;
const DESCRIPTION_MAX = 300;

const toStoredNumber = (value: any) =>
  value === null || value === undefined || value === "" ? "" : String(value);

const newItem = (): EquipmentItem => ({ key: generateUUID(), name: "", description: "", maxWeight: "" });

const EditEquipmentModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: EquipmentType;
  adminRoles?: any;
  onAdd?: (type: EquipmentType) => void;
  /** Names of the other equipment types, for the duplicate-name check. */
  existingNames?: string[];
}> = ({ onClose, socket, student, onAdd, existingNames = [] }) => {
  const [form] = Form.useForm();
  const updateAdmin = useAdminUserUpdate(socket);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);

  const close = () => {
    if (!dirty) return onClose();
    Modal.confirm({
      title: "Discard unsaved changes?",
      content: "Your edits to this equipment type haven't been saved.",
      okText: "Discard",
      okButtonProps: { danger: true },
      cancelText: "Keep editing",
      onOk: onClose,
    });
  };

  const save = async () => {
    const values = form.getFieldsValue(true);
    const name = `${values.name}`.trim();
    const equipments: EquipmentItem[] = (values.equipments || []).map((item: EquipmentItem) => ({
      key: item.key || generateUUID(),
      name: `${item.name || ""}`.trim(),
      description: `${item.description || ""}`.trim(),
      maxWeight: toStoredNumber(item.maxWeight),
    }));
    const path = itemPath("equipmentManagement", student._id);
    const changes: any[] = [{ op: "add", path: `${path}/equipments`, value: equipments }];
    if (name !== student?.name) changes.unshift({ op: "add", path: `${path}/name`, value: name });

    setSaving(true);
    try {
      const ok = await updateAdmin(changes);
      if (!ok) {
        pushNotification("Couldn't save the equipment type, please try again", "error", "TOP_CENTER", 3000);
        return;
      }
      pushNotification("Equipment saved", "success", "TOP_CENTER", 2000);
      setDirty(false);
      onAdd?.({ ...student, name, equipments });
    } finally {
      setSaving(false);
    }
  };

  const uniqueItemName = (index: number) => ({
    validator: (_: any, value: any) => {
      const items: EquipmentItem[] = form.getFieldValue("equipments") || [];
      const clash = items.some((item, i) => i !== index && nameKey(item?.name) === nameKey(value));
      return clash ? Promise.reject(new Error("Another item has this name")) : Promise.resolve();
    },
  });

  const itemColumns = (remove: (index: number) => void): ColumnsType<FormListFieldData> => [
    {
      title: "Item",
      key: "name",
      width: 200,
      render: (_, field) => (
        <Form.Item
          name={[field.name, "name"]}
          validateFirst
          rules={[
            { required: true, whitespace: true, message: "Enter a name" },
            { max: ITEM_NAME_MAX, message: `Max ${ITEM_NAME_MAX} characters` },
            uniqueItemName(field.name),
          ]}
          style={{ margin: 0 }}
        >
          <Input placeholder="e.g. HW 1" />
        </Form.Item>
      ),
    },
    {
      title: "Description",
      key: "description",
      render: (_, field) => (
        <Form.Item
          name={[field.name, "description"]}
          rules={[{ max: DESCRIPTION_MAX, message: `Max ${DESCRIPTION_MAX} characters` }]}
          style={{ margin: 0, minWidth: 240 }}
        >
          <Input.TextArea autoSize={{ minRows: 1, maxRows: 4 }} placeholder="Shown to dispatchers when booking" />
        </Form.Item>
      ),
    },
    {
      title: "Max weight",
      key: "maxWeight",
      width: 150,
      render: (_, field) => (
        <Form.Item
          name={[field.name, "maxWeight"]}
          normalize={toStoredNumber}
          rules={[
            {
              validator: (_r, value) =>
                value === "" || value === undefined || Number(value) >= 0
                  ? Promise.resolve()
                  : Promise.reject(new Error("Can't be negative")),
            },
          ]}
          style={{ margin: 0 }}
        >
          <InputNumber min={0} addonAfter="lb" style={{ width: "100%" }} />
        </Form.Item>
      ),
    },
    {
      title: "",
      key: "actions",
      width: 60,
      align: "right",
      render: (_, field) => {
        const itemName = form.getFieldValue(["equipments", field.name, "name"]);
        return (
          <RowActions
            onDelete={() => {
              remove(field.name);
              setDirty(true);
            }}
            deleteConfirm={itemName ? `Remove "${itemName}"?` : "Remove this item?"}
          />
        );
      },
    },
  ];

  return (
    <FormModal
      open
      width={900}
      title={`Edit ${student?.name || "equipment type"}`}
      subtitle="Changes are kept here until you press Save."
      onCancel={close}
      onSubmit={form.submit}
      saving={saving}
      footerExtra={dirty ? <Pill tone="amber">Unsaved changes</Pill> : null}
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        initialValues={{ name: student?.name, equipments: student?.equipments || [] }}
        onValuesChange={() => setDirty(true)}
        onFinish={save}
      >
        <FormSection title="Details">
          <Form.Item
            label="Type name"
            name="name"
            validateFirst
            rules={[
              { required: true, whitespace: true, message: "Enter a name" },
              { max: TYPE_NAME_MAX, message: `Keep it under ${TYPE_NAME_MAX} characters` },
              {
                validator: (_, value) =>
                  existingNames.some((n) => nameKey(n) === nameKey(value))
                    ? Promise.reject(new Error("An equipment type with this name already exists"))
                    : Promise.resolve(),
              },
            ]}
            style={{ marginBottom: 0 }}
          >
            <Input placeholder="e.g. Wheelchairs" />
          </Form.Item>
        </FormSection>

        <Form.List name="equipments">
          {(fields, { add, remove }) => {
            const addItem = () => {
              add(newItem());
              setDirty(true);
            };
            return (
              <FormSection
                title={`Items (${fields.length})`}
                description="The specific equipment dispatchers can pick for a trip."
                extra={
                  fields.length > 0 && (
                    <Button className="mx-btn-secondary" icon={<PlusOutlined />} onClick={addItem}>
                      Add item
                    </Button>
                  )
                }
              >
                <Table<FormListFieldData>
                  size="small"
                  rowKey="key"
                  pagination={false}
                  columns={itemColumns(remove)}
                  dataSource={fields}
                  scroll={{ x: "max-content" }}
                  locale={{
                    emptyText: (
                      <EmptyState
                        title="No items yet"
                        description="Add each piece of equipment with its weight limit."
                        action={{ label: "Add item", onClick: addItem }}
                      />
                    ),
                  }}
                />
              </FormSection>
            );
          }}
        </Form.List>
      </Form>
    </FormModal>
  );
};

export default EditEquipmentModal;
