import { useEffect, useMemo, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "reducers/reducer";
import { formatForRedis } from "utils/appUtil";
import {
  buildPagesRequest,
  buildShiftRequest,
} from "../../Dashboard/DashboardModal/utils/queries";
import {
  buildRideRow,
  loadCachedUsers,
  normalizeSearchResult,
} from "../../Dashboard/DashboardModal/utils/rows";
import { resolveTimeRange } from "../../Dashboard/DashboardModal/utils/timeRange";
import { DayJob, DriverRecord, mergeShiftRows, rowToDayJob } from "./availability";

const ECO = process.env.REACT_APP_ECO_SYSTEM;
const DIRECTORY_TTL_MS = 5 * 60 * 1000;

// Drivers rarely change; share one fetch across drawers/forms for a while.
const directoryCache: Record<string, { at: number; drivers: DriverRecord[] }> = {};

const buildDirectoryRequest = (userServiceId: string, adminUserRoles: any[]) => {
  const roles = (adminUserRoles || [])
    .filter((r) => r.permissions?.includes("onMove") && !r.permissions?.includes("admin"))
    .map((r) => `@roleId === '${r._id}'`);
  return {
    objectType: "user",
    select: {
      index: {
        searchIndex: `${ECO}:userNameIndex`,
        searchQuery: `@serviceId:{'${formatForRedis(userServiceId)}'}`,
        searchOptions: "TIMEOUT 5000",
      },
      load: {
        email: "$..live.alternativeIds.email",
        phone: "$..live.alternativeIds.phone",
        beamIds: "$..beamIds",
        profile: "$..profile",
        roleId: "$..admin.profile.roleId",
        extendedBio: "$..extendedBio",
      },
    },
    groupBy: {
      properties: ["@email", "@phone", "@profile", "@roleId", "@extendedBio", "@beamIds"],
      reducers: [{ func: "TOLIST", arguments: ["@objectId"], name: "objectIds" }],
    },
    apply: { expression: "", name: "" },
    result: { pagination: { offset: 0, limit: 1000 } },
    filter: { expression: `exists(@roleId) && (${roles.join("||")})` },
    anyStatus: false,
  };
};

// Mirrors the option object ResponderInput builds, so values are interchangeable.
const toDriverRecord = (x: any): DriverRecord => {
  const firstName = x?.profile?.firstName ?? "";
  const lastName = x?.profile?.lastName ?? "";
  const name = `${firstName} ${lastName}`.trim();
  const obj = {
    id: x?.objectIds?.toString(),
    name,
    extendedBio: x?.extendedBio,
    extendedBioValue: x?.extendedBioValue,
    firstName,
    lastName,
    gender: x?.profile?.gender ?? "",
    dob: x?.profile?.dob ?? "",
    email: x.email,
    phone: x.phone,
    beamId: x?.beamIds?.[0] ?? `${firstName.toLowerCase()}.${lastName.toLowerCase()}`,
    location: x?.profile?.location?.coordinates
      ? {
          coordinates: [
            x.profile.location.coordinates.long,
            x.profile.location.coordinates.lat,
          ],
        }
      : undefined,
  };
  return { id: obj.id, name: name || obj.beamId, obj };
};

const buildTimeOffRequest = (userServiceId: string, dayStart: number) => ({
  select: {
    index: {
      searchIndex: `${ECO}:custom:createdAt`,
      searchQuery: `@partitions:{'org\\:${formatForRedis(userServiceId)}'}@partitions:{type\\:timeoff}`,
      searchOptions: "VERBATIM TIMEOUT 10000",
    },
    load: {
      info: "$.info",
      partitions: "$.partitions",
      endDateTimestamp: "$..endDateTimestamp",
    },
  },
  filter: { expression: `exists(@endDateTimestamp) && @endDateTimestamp > ${dayStart}` },
});

interface Options {
  /** Any timestamp within the day of interest. */
  day?: number;
  /** Jobs already loaded by the caller (e.g. the dashboard); skips a fetch. */
  jobs?: DayJob[];
}

/** Everything needed to judge who can take a job on a given day. */
export const useDriverDay = ({ day, jobs: providedJobs }: Options) => {
  const dispatch = useDispatch();
  const { projects, adminUserRoles, encrypted_token } = useSelector(
    (state: RootState) => state.auth
  );
  const serviceId = projects?.userServiceId;
  const dayStart = day !== undefined ? moment(day).startOf("day").valueOf() : undefined;

  const [drivers, setDrivers] = useState<DriverRecord[]>(
    () => (serviceId && directoryCache[serviceId]?.drivers) || []
  );
  const [slotsByDriver, setSlotsByDriver] = useState<Record<string, any[]>>({});
  const [timeOffDriverIds, setTimeOffDriverIds] = useState<Set<string>>(new Set());
  const [fetchedJobs, setFetchedJobs] = useState<DayJob[]>([]);
  const [pending, setPending] = useState(0);

  const request = (requestData: any, onResult: (response: any[]) => void) => {
    let cancelled = false;
    setPending((p) => p + 1);
    dispatch(
      GET_AGGREGATE({
        requestData,
        callback: (response) => {
          if (!cancelled) onResult(Array.isArray(response) ? response : []);
          setPending((p) => Math.max(0, p - 1));
        },
      })
    );
    return () => {
      cancelled = true;
    };
  };

  useEffect(() => {
    if (!serviceId || !adminUserRoles) return;
    const cached = directoryCache[serviceId];
    if (cached && Date.now() - cached.at < DIRECTORY_TTL_MS) {
      setDrivers(cached.drivers);
      return;
    }
    return request(buildDirectoryRequest(serviceId, adminUserRoles), (response) => {
      const list = response
        .map(toDriverRecord)
        .filter((d) => d.id)
        .sort((a, b) => a.name.localeCompare(b.name));
      directoryCache[serviceId] = { at: Date.now(), drivers: list };
      setDrivers(list);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [serviceId, adminUserRoles]);

  useEffect(() => {
    if (!serviceId || dayStart === undefined) return;
    return request(buildShiftRequest({ userServiceId: serviceId }, dayStart), (response) =>
      setSlotsByDriver(mergeShiftRows(response, dayStart))
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [serviceId, dayStart]);

  useEffect(() => {
    if (!serviceId || dayStart === undefined) return;
    const dayEnd = moment(dayStart).endOf("day").valueOf();
    return request(buildTimeOffRequest(serviceId, dayStart), (response) => {
      const ids = response
        .filter(
          (x) => x?.info?.status === "Accepted" && (x?.info?.startDateTimestamp ?? 0) <= dayEnd
        )
        .map((x) => x?.partitions?.find((p: string) => p?.startsWith("user:"))?.split(":")[1])
        .filter(Boolean);
      setTimeOffDriverIds(new Set(ids));
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [serviceId, dayStart]);

  useEffect(() => {
    if (providedJobs || !serviceId || dayStart === undefined || !encrypted_token?.userId) return;
    const ctx = {
      userId: encrypted_token.userId,
      adminUserId: projects?.adminUserId,
      userServiceId: serviceId,
    };
    const filters = {
      entityType: "project" as const,
      areaType: "state" as const,
      timeRange: resolveTimeRange({
        selected: "specificDate",
        startTimestamp: dayStart,
        endTimestamp: dayStart,
      }),
    };
    return request(buildPagesRequest(ctx, filters), (response) => {
      const users = loadCachedUsers();
      setFetchedJobs(
        response
          .map((x) => buildRideRow(normalizeSearchResult(x), users, ctx))
          .filter((row) => row.pageStatus !== "black")
          .map(rowToDayJob)
      );
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [providedJobs, serviceId, dayStart, encrypted_token?.userId, projects?.adminUserId]);

  const jobs = useMemo(() => providedJobs ?? fetchedJobs, [providedJobs, fetchedJobs]);

  return {
    drivers,
    slotsByDriver,
    timeOffDriverIds,
    jobs,
    loading: pending > 0,
    ready: drivers.length > 0,
  };
};
