import React, { useEffect, useState } from "react";
import { DatePicker, Select } from "antd";
import moment from "moment";
import { TimeRangeKey, TimeRangeValue } from "../types";

const { RangePicker } = DatePicker;

const OPTIONS: { value: TimeRangeKey; label: string }[] = [
  { value: "today", label: "Today" },
  { value: "todayAndBeyond", label: "Today and Beyond" },
  { value: "tomorrow", label: "Tomorrow" },
  { value: "nextWeek", label: "Next Week" },
  { value: "allTime", label: "All Time" },
  { value: "specificDate", label: "Specific Date" },
  { value: "customRange", label: "Custom Range" },
];

const NEEDS_PICKER: TimeRangeKey[] = ["customRange", "specificDate"];

interface Props {
  value: TimeRangeValue;
  onChange: (value: TimeRangeValue) => void;
}

/**
 * Controlled by the parent's filter state. Choosing a preset that needs a
 * date only shows the picker; the filter changes once a date is picked.
 */
const TimeRangeSelector = ({ value, onChange }: Props) => {
  const [pendingPreset, setPendingPreset] = useState<TimeRangeKey>();
  const selected = pendingPreset ?? value.selected;
  const { startTimestamp, endTimestamp } = value;

  // An external change (e.g. reset) wins over a half-finished selection.
  useEffect(() => setPendingPreset(undefined), [value]);

  const handlePreset = (preset: TimeRangeKey) => {
    if (NEEDS_PICKER.includes(preset)) {
      setPendingPreset(preset);
    } else {
      setPendingPreset(undefined);
      onChange({ selected: preset });
    }
  };

  const isCurrent = (key: TimeRangeKey) => value.selected === key && startTimestamp;
  const rangeValue: any = isCurrent("customRange")
    ? [moment(startTimestamp), moment(endTimestamp)]
    : null;
  const dateValue: any = isCurrent("specificDate") ? moment(startTimestamp) : null;

  return (
    <div className="w-100">
      <Select
        style={{ width: 200 }}
        placeholder="Select time range"
        className="w-100"
        value={selected}
        onChange={handlePreset}
        options={OPTIONS}
      />

      {selected === "customRange" && (
        <RangePicker
          style={{ marginTop: 16 }}
          format="YYYY-MM-DD"
          value={rangeValue}
          onChange={(dates: any) => {
            if (!dates?.[0] || !dates?.[1]) return;
            onChange({
              selected: "customRange",
              startTimestamp: dates[0].valueOf(),
              endTimestamp: dates[1].valueOf(),
            });
          }}
        />
      )}

      {selected === "specificDate" && (
        <DatePicker
          style={{ marginTop: 16 }}
          format="YYYY-MM-DD"
          value={dateValue}
          onChange={(date: any) => {
            if (!date) return;
            onChange({
              selected: "specificDate",
              startTimestamp: date.valueOf(),
              endTimestamp: date.valueOf(),
            });
          }}
        />
      )}
    </div>
  );
};

export default TimeRangeSelector;
