  const getRideEstimation = (pickupLocation, dropoffLocation) => {
    const origin = pickupLocation?.value?.coordinates;
    const destination = dropoffLocation?.value?.coordinates;
    const DirectionsService = new google.maps.DirectionsService();
    DirectionsService.route(
      {
        origin: new google.maps.LatLng(origin.lat, origin.long),
        destination: new google.maps.LatLng(destination.lat, destination.long),
        travelMode: google.maps.TravelMode.DRIVING,
        drivingOptions: {
          departureTime: new Date(), // Current time or any future date
          trafficModel: google.maps.TrafficModel.PESSIMISTIC, // Pessimistic traffic model
        },
      },
      (body, status) => {
        if (status === google.maps.DirectionsStatus.OK) {
          console.log("direction result here", body);

          if (body?.routes?.length > 0 && body?.routes?.[0]?.legs?.length > 0) {
            const route = body.routes[0].legs[0];
            const distance = route.distance.value;
            const duration = route.duration.value;
            const durationInTraffic = route.duration_in_traffic
              ? route.duration_in_traffic.value
              : null;
            setEstimation({ distance, duration, durationInTraffic });
          } else {
            new Error("cannot find distance between start and end");
          }
        } else {
          console.error(`error fetching directions ${body}`);
        }
      }
    );
  };

