import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";

const MIN_WIDTH = 50;

interface PreviewLine {
  x: number;
  top: number;
  height: number;
}

/**
 * Header cell with a drag handle. While dragging, only a guide line moves;
 * the new width is committed once on release to avoid re-rendering the whole
 * table on every pointer move.
 */
const ResizableTitle = ({ width, onResize, ...restProps }: any) => {
  const [colWidth, setColWidth] = useState(width);
  const [preview, setPreview] = useState<PreviewLine | null>(null);
  const thRef = useRef<HTMLTableCellElement>(null);
  const resizing = useRef(false);
  const onResizeRef = useRef(onResize);
  onResizeRef.current = onResize;

  useEffect(() => {
    if (!resizing.current) setColWidth(width);
  }, [width]);

  // Listeners live in a ref so add/remove always see the same functions.
  const listeners = useRef<{
    move: (e: PointerEvent) => void;
    up: (e: PointerEvent) => void;
    cancel: () => void;
  }>();

  const detach = () => {
    const l = listeners.current;
    if (!l) return;
    document.removeEventListener("pointermove", l.move);
    document.removeEventListener("pointerup", l.up);
    document.removeEventListener("pointercancel", l.cancel);
  };

  useEffect(() => detach, []);

  const findContainer = (): HTMLElement | null =>
    (thRef.current?.closest(".ant-table-wrapper") as HTMLElement) ||
    (thRef.current?.closest(".table-scroll-wrapper") as HTMLElement);

  // A click fires right after pointerup; swallow it so it doesn't sort.
  const suppressNextHeaderClick = () => {
    const prevent = (e: MouseEvent) => {
      if (thRef.current?.contains(e.target as Node)) {
        e.preventDefault();
        e.stopPropagation();
      }
      document.removeEventListener("click", prevent, true);
    };
    document.addEventListener("click", prevent, true);
    setTimeout(() => document.removeEventListener("click", prevent, true), 200);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!thRef.current) return;
    resizing.current = true;
    const container = findContainer();

    listeners.current = {
      move: (ev) => {
        if (!resizing.current || !container) return;
        ev.preventDefault();
        const rect = container.getBoundingClientRect();
        setPreview({ x: ev.clientX, top: rect.top, height: rect.height });
      },
      up: (ev) => {
        if (!resizing.current || !thRef.current) return;
        ev.preventDefault();
        resizing.current = false;
        setPreview(null);
        detach();

        // Convert the pointer position into an offsetWidth, accounting for
        // any scaling between layout and rendered size.
        const rect = thRef.current.getBoundingClientRect();
        const ratio = thRef.current.offsetWidth / (rect.right - rect.left || 1);
        const finalWidth = Math.round(Math.max((ev.clientX - rect.left) * ratio, MIN_WIDTH));

        onResizeRef.current?.(ev, { size: { width: finalWidth, height: 0 } });
        setColWidth(finalWidth);
        suppressNextHeaderClick();
      },
      cancel: () => {
        resizing.current = false;
        setPreview(null);
        detach();
      },
    };

    document.addEventListener("pointermove", listeners.current.move);
    document.addEventListener("pointerup", listeners.current.up);
    document.addEventListener("pointercancel", listeners.current.cancel);
  };

  const stop = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
  };

  return (
    <>
      <th
        {...restProps}
        ref={thRef}
        style={{
          width: colWidth,
          minWidth: colWidth,
          position: "relative",
          userSelect: "none",
          touchAction: "none",
        }}
      >
        {restProps.children}
        <div
          onPointerDown={handlePointerDown}
          onClick={stop}
          onMouseDown={stop}
          className="resizable-handle"
          style={{
            position: "absolute",
            top: 0,
            right: 0,
            width: 10,
            height: "100%",
            cursor: "col-resize",
            zIndex: 999,
            touchAction: "none",
          }}
        />
      </th>

      {preview &&
        createPortal(
          <div
            className="column-resize-preview-line"
            style={{
              position: "fixed",
              left: preview.x,
              top: preview.top,
              height: preview.height,
              width: 2,
              backgroundColor: "#508AFA",
              pointerEvents: "none",
              zIndex: 10000,
              transform: "translateX(-1px)",
            }}
          />,
          document.body
        )}
    </>
  );
};

export default ResizableTitle;
