/**
 * CFO Executive Dashboard — derivations.
 *
 * Every figure on the screen is computed from the ledger rows so the
 * KPI cards, aging buckets and grid can never disagree with each other.
 */
import {
  AgingBucket,
  BillingSnapshot,
  BillingStatus,
  Cadence,
  CustomerGroupDimension,
  CustomerGroupRow,
  DunningAlert,
  DunningBucket,
  ExecutiveKpis,
  LedgerRow,
  LedgerSide,
  ProjectRollup,
  ProjectSummary,
  RowStatus,
  ScheduleItem,
  TimeView,
  TransactionFilter,
} from "./types";

import { DAY, HOUR, PROJECTS } from "./mockData";

/** Inclusive epoch-ms window the temporal slicer resolves to. */
export interface TimeWindow {
  from: number;
  to: number;
}

const round2 = (value: number) => Number(value.toFixed(2));

export const formatMoney = (value: number, currency = "USD"): string =>
  new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value);

/** Compact form for the KPI cards, e.g. $142.5K. */
export const formatMoneyShort = (value: number, currency = "USD"): string => {
  const sign = value < 0 ? "-" : "";
  const abs = Math.abs(value);
  const symbol = currency === "USD" ? "$" : `${currency} `;
  if (abs >= 1_000_000) return `${sign}${symbol}${(abs / 1_000_000).toFixed(1)}M`;
  if (abs >= 1_000) return `${sign}${symbol}${(abs / 1_000).toFixed(1)}K`;
  return `${sign}${symbol}${abs.toFixed(0)}`;
};

/**
 * Resolves a temporal slice to a concrete window. `custom` needs the
 * picked range; the standard views are measured back from now.
 */
export const resolveWindow = (
  view: TimeView,
  now: number,
  custom?: TimeWindow | null
): TimeWindow => {
  switch (view) {
    case "weekly":
      return { from: now - 7 * DAY, to: now };
    case "monthly":
      return { from: now - 31 * DAY, to: now };
    case "annual":
      return { from: now - 365 * DAY, to: now };
    case "custom":
    default:
      return custom || { from: now - 365 * DAY, to: now };
  }
};

export const withinWindow = (row: LedgerRow, window: TimeWindow): boolean =>
  row.lastActivityAt >= window.from && row.lastActivityAt <= window.to;

/**
 * Receivable rows only. Payables are excluded from AR roll-ups so the
 * KPI cards never mix a vendor invoice into a parent's balance.
 */
export const arRows = (rows: LedgerRow[]) => rows.filter((r) => r.side === "ar");
export const apRows = (rows: LedgerRow[]) => rows.filter((r) => r.side === "ap");

export const computeKpis = (rows: LedgerRow[]): ExecutiveKpis => {
  const ar = arRows(rows);
  const ap = apRows(rows);

  const grossRevenue = ar.reduce((acc, r) => acc + r.serviceFee, 0);
  const deductions = ar.reduce(
    (acc, r) => acc + r.adjustments.reduce((inner, a) => inner + a.amount, 0),
    0
  );
  const collections = ar.reduce((acc, r) => acc + r.collected, 0);
  const currentAr = ar.reduce((acc, r) => acc + r.outstanding, 0);
  const overdueAr = ar.reduce((acc, r) => acc + r.pastDue, 0);
  const refunds = ar.reduce(
    (acc, r) => acc + (r.refund ? r.refund.amount : 0),
    0
  );

  const disbursedAp = ap.reduce((acc, r) => acc + r.collected, 0);
  const committedAp = ap.reduce((acc, r) => acc + r.outstanding, 0);
  const overdueAp = ap.reduce((acc, r) => acc + r.pastDue, 0);
  const costs = ap.reduce((acc, r) => acc + r.invoicedServiceFee, 0);
  const netRevenue = grossRevenue - deductions;
  const profit = netRevenue - costs;

  return {
    grossRevenue: round2(grossRevenue),
    deductions: round2(deductions),
    /* Equal to Σ invoicedServiceFee: mockData.build() derives that field
       as fee − Σ adjustments, so the two can never disagree. */
    netRevenue: round2(grossRevenue - deductions),
    collections: round2(collections),
    currentAr: round2(currentAr),
    overdueAr: round2(overdueAr),
    refunds: round2(refunds),
    netCollected: round2(collections - refunds),
    disbursedAp: round2(disbursedAp),
    committedAp: round2(committedAp),
    overdueAp: round2(overdueAp),
    costs: round2(costs),
    profit: round2(profit),
    marginPct: netRevenue > 0 ? Number(((profit / netRevenue) * 100).toFixed(1)) : null,
  };
};

/** Signed percentage change between two figures; null when there is no base. */
export const pctChange = (current: number, previous: number): number | null =>
  previous > 0 ? Number((((current - previous) / previous) * 100).toFixed(1)) : null;

/** "+4.2%" / "-1.0%" for a percentage; "n/a" when there is none. */
export const formatPct = (value: number | null, signed = false): string => {
  if (value === null) return "n/a";
  const sign = signed && value > 0 ? "+" : "";
  return `${sign}${value}%`;
};

/** The same number of days immediately before a window. */
export const previousWindow = (window: TimeWindow): TimeWindow => {
  const length = window.to - window.from;
  return { from: window.from - length - 1, to: window.from - 1 };
};

/** Maps elapsed overdue hours onto the aging brackets. */
export const agingBucketOf = (row: LedgerRow): AgingBucket => {
  if (row.pastDue <= 0) return "current";
  const days = row.pastDueHours / 24;
  if (days <= 30) return "1-30";
  if (days <= 60) return "31-60";
  return "61+";
};

export const AGING_ORDER: AgingBucket[] = ["current", "1-30", "31-60", "61+"];

export const AGING_LABELS: Record<AgingBucket, string> = {
  current: "Current",
  "1-30": "1-30 days",
  "31-60": "31-60 days",
  "61+": "61+ days",
};

export const computeAging = (
  rows: LedgerRow[],
  side: LedgerSide = "ar"
): Record<AgingBucket, number> => {
  const totals: Record<AgingBucket, number> = {
    current: 0,
    "1-30": 0,
    "31-60": 0,
    "61+": 0,
  };
  rows.filter((row) => row.side === side).forEach((row) => {
    const bucket = agingBucketOf(row);
    totals[bucket] += bucket === "current" ? row.outstanding : row.pastDue;
  });
  (Object.keys(totals) as AgingBucket[]).forEach((key) => {
    totals[key] = round2(totals[key]);
  });
  return totals;
};

