/**
 * Renders the offset from now the way the CFO alert centre reads it:
 * hours up to two days, then days.
 */
export const formatOffset = (timestamp: number, now: number): string => {
  const deltaHours = Math.round((timestamp - now) / HOUR);
  const abs = Math.abs(deltaHours);
  const unit = abs >= 48 ? `${Math.round(abs / 24)}d` : `${abs}h`;
  if (deltaHours === 0) return "now";
  return deltaHours > 0 ? `in ${unit}` : `${unit} ago`;
};

