/** Which sidebar table a project kind belongs to. */
export const PROJECT_GROUP: Record<string, "team" | "event"> = {
  Team: "team",
  Class: "team",
  Club: "team",
  Clinic: "event",
  Tournament: "event",
  Program: "event",
  Camp: "event",
  Showcase: "event",
  Trip: "event",
};

export const projectGroupOf = (kind: string): "team" | "event" =>
  PROJECT_GROUP[kind] || "team";

export const billingStatusOf = (billing: BillingSnapshot): BillingStatus => {
  if (billing.billed <= 0) return "not-billed";
  if (billing.pastDue > 0) return "overdue";
  if (billing.outstanding <= 0) return "paid";
  return "partial";
};

export const BILLING_STATUS_LABELS: Record<BillingStatus, string> = {
  paid: "Paid",
  partial: "Partial",
  overdue: "Overdue",
  "not-billed": "Not billed",
};

const emptySnapshot = (currency: string): BillingSnapshot => ({
  currency,
  billed: 0,
  collected: 0,
  outstanding: 0,
  pastDue: 0,
  nextDueAt: null,
  lastActivityAt: null,
});

/** Rolls the receivable lines of one project up into a billing position. */
export const summarizeProject = (
  project: ProjectSummary,
  rows: LedgerRow[]
): ProjectRollup => {
  const lines = arRows(rows).filter((row) => row.projectId === project.id);
  const billing = lines.reduce<BillingSnapshot>((acc, row) => {
    const nextDue = nextDueOf(row);
    return {
      ...acc,
      billed: acc.billed + row.invoicedServiceFee,
      collected: acc.collected + row.collected,
      outstanding: acc.outstanding + row.outstanding,
      pastDue: acc.pastDue + row.pastDue,
      nextDueAt:
        nextDue !== null && (acc.nextDueAt === null || nextDue < acc.nextDueAt)
          ? nextDue
          : acc.nextDueAt,
      lastActivityAt:
        acc.lastActivityAt === null || row.lastActivityAt > acc.lastActivityAt
          ? row.lastActivityAt
          : acc.lastActivityAt,
    };
  }, emptySnapshot(project.currency));

  (Object.keys(billing) as (keyof BillingSnapshot)[]).forEach((key) => {
    const value = billing[key];
    if (typeof value === "number" && key !== "nextDueAt" && key !== "lastActivityAt") {
      (billing as any)[key] = round2(value);
    }
  });

  return {
    ...project,
    group: projectGroupOf(project.kind),
    billing,
    collectedPct:
      billing.billed > 0
        ? Math.min(100, Math.round((billing.collected / billing.billed) * 100))
        : 0,
    status: billingStatusOf(billing),
  };
};

