/** How long after the last movement the next installment falls due. */
export const CADENCE_DAYS: Record<Cadence, number> = {
  "one-time": 14,
  recurring: 30,
  seasonal: 90,
  regular: 30,
};

/** Epoch ms of a row's next installment, or null when nothing is left to draw. */
export const nextDueOf = (row: LedgerRow): number | null =>
  row.outstanding > 0
    ? row.lastActivityAt + CADENCE_DAYS[row.cadence] * DAY
    : null;

/** Maps elapsed overdue hours onto the dunning benchmarks. */
export const dunningBucketOf = (pastDueHours: number): DunningBucket => {
  if (pastDueHours >= 336) return "T+336h";
  if (pastDueHours >= 240) return "T+240h";
  if (pastDueHours >= 120) return "T+120h";
  if (pastDueHours >= 24) return "T+24h";
  return "T+0h";
};

/**
 * Builds the Scheduler screen from the ledger and the alert feed:
 * overdue balances first (staged by how long they have been late), then
 * the next installment of every open account, then any alert milestone
 * the ledger cannot derive on its own (tournament entry balances, card
 * declines). Sorted by due time.
 */
export const buildSchedule = (
  rows: LedgerRow[],
  alerts: DunningAlert[],
  now: number
): ScheduleItem[] => {
  const items: ScheduleItem[] = [];
  const covered = new Set<string>();
  const keyOf = (entity: string, project: string) => `${entity}|${project}`;

  arRows(rows).forEach((row) => {
    if (row.pastDue > 0) {
      const stage = dunningBucketOf(row.pastDueHours);
      items.push({
        id: `${row.key}-due`,
        dueAt: now - row.pastDueHours * HOUR,
        entity: row.entity,
        entityRole: row.entityRole,
        projectId: row.projectId,
        project: row.project,
        side: row.side,
        amount: row.pastDue,
        currency: row.currency,
        stage,
        status: stage === "T+336h" ? "suspended" : "overdue",
        ledgerKey: row.key,
      });
      covered.add(keyOf(row.entity, row.project));
    }

    const nextDue = nextDueOf(row);
    if (nextDue !== null) {
      const hoursOut = (nextDue - now) / HOUR;
      items.push({
        id: `${row.key}-next`,
        dueAt: nextDue,
        entity: row.entity,
        entityRole: row.entityRole,
        projectId: row.projectId,
        project: row.project,
        side: row.side,
        amount: row.outstanding,
        currency: row.currency,
        stage: hoursOut <= 0 ? "T+0h" : hoursOut <= 72 ? "T-72h" : "scheduled",
        status: hoursOut <= 0 ? "due" : "upcoming",
        ledgerKey: row.key,
      });
      covered.add(keyOf(row.entity, row.project));
    }
  });

  alerts.forEach((alert) => {
    if (alert.bucket !== "T-72h" && alert.bucket !== "T+0h") return;
    if (covered.has(keyOf(alert.entity, alert.project))) return;
    items.push({
      id: alert.id,
      dueAt: alert.dueAt,
      entity: alert.entity,
      entityRole: "Account",
      projectId: (PROJECTS.find((p) => p.name === alert.project) || { id: null }).id,
      project: alert.project,
      side: "ar",
      amount: alert.amount,
      currency: alert.currency,
      stage: alert.bucket,
      status: alert.dueAt < now ? "due" : "upcoming",
      alertId: alert.id,
    });
  });

  return items.sort((a, b) => a.dueAt - b.dueAt);
};

