/** One column of the revenue bridge: totals above zero, deductions and refunds below it. */
export interface BridgeStep {
  key: keyof ExecutiveKpis;
  label: string;
  kind: "total" | "step-down";
  /** Magnitude, always positive. */
  value: number;
  previous: number;
  /** Signed: negative for deductions and refunds. */
  signed: number;
  signedPrevious: number;
  /** signed − signedPrevious: a positive change is always good news. */
  change: number;
  /** Null when there was nothing in the previous period to compare with. */
  changePct: number | null;
}

const bridgeStep = (
  key: keyof ExecutiveKpis,
  label: string,
  kind: BridgeStep["kind"],
  value: number,
  previous: number
): BridgeStep => {
  const sign = kind === "step-down" ? -1 : 1;
  const signed = round2(sign * value);
  const signedPrevious = round2(sign * previous);
  const change = round2(signed - signedPrevious);
  return {
    key,
    label,
    kind,
    value,
    previous,
    signed,
    signedPrevious,
    change,
    changePct: previous > 0 ? Number(((change / Math.abs(signedPrevious)) * 100).toFixed(1)) : null,
  };
};

/**
 * The P&L logic of the dashboard, each step against the previous period:
 * Gross Revenue → Deductions → Net Revenue → Costs → Profit.
 */
export const profitBridge = (kpis: ExecutiveKpis, previous: ExecutiveKpis): BridgeStep[] => [
  bridgeStep("grossRevenue", "Gross Revenue", "total", kpis.grossRevenue, previous.grossRevenue),
  bridgeStep("deductions", "Deductions", "step-down", kpis.deductions, previous.deductions),
  bridgeStep("netRevenue", "Net Revenue", "total", kpis.netRevenue, previous.netRevenue),
  bridgeStep("costs", "Costs", "step-down", kpis.costs, previous.costs),
  bridgeStep("profit", "Profit", "total", kpis.profit, previous.profit),
];

/** The cash side: Collections → Refunds → Net Collected. */
export const cashBridge = (kpis: ExecutiveKpis, previous: ExecutiveKpis): BridgeStep[] => [
  bridgeStep("collections", "Collections", "total", kpis.collections, previous.collections),
  bridgeStep("refunds", "Refunds", "step-down", kpis.refunds, previous.refunds),
  bridgeStep("netCollected", "Net Collected", "total", kpis.netCollected, previous.netCollected),
];

/** "-$1,200.00" / "$99,050.00" for a signed amount. */
export const formatSigned = (value: number, currency = "USD"): string =>
  `${value < 0 ? "-" : ""}${formatMoney(Math.abs(value), currency)}`;

/** A project's receivable position for the stacked bar. */
export interface ProjectReceivables {
  projectId: string;
  name: string;
  kind: string;
  collected: number;
  current: number;
  overdue: number;
  total: number;
}

/**
 * Receivable lines grouped by project, largest first. Projects past
 * `limit` fold into one "Other projects" bar so the chart never grows
 * past a readable number of rows.
 */
export const receivablesByProject = (rows: LedgerRow[], limit = 8): ProjectReceivables[] => {
  const map = new Map<string, ProjectReceivables>();
  arRows(rows).forEach((row) => {
    const entry = map.get(row.projectId) || {
      projectId: row.projectId,
      name: row.project,
      kind: row.projectKind,
      collected: 0,
      current: 0,
      overdue: 0,
      total: 0,
    };
    entry.collected += row.collected;
    entry.current += row.outstanding;
    entry.overdue += row.pastDue;
    entry.total = entry.collected + entry.current + entry.overdue;
    map.set(row.projectId, entry);
  });
  const sorted = Array.from(map.values()).sort((a, b) => b.total - a.total);
  const head = sorted.slice(0, limit);
  const tail = sorted.slice(limit);
  if (tail.length > 0) {
    head.push(
      tail.reduce<ProjectReceivables>(
        (acc, p) => ({
          ...acc,
          collected: acc.collected + p.collected,
          current: acc.current + p.current,
          overdue: acc.overdue + p.overdue,
          total: acc.total + p.total,
        }),
        { projectId: "other", name: `Other (${tail.length})`, kind: "", collected: 0, current: 0, overdue: 0, total: 0 }
      )
    );
  }
  return head.map((p) => ({
    ...p,
    collected: round2(p.collected),
    current: round2(p.current),
    overdue: round2(p.overdue),
    total: round2(p.total),
  }));
};

