const pct = (part: number, whole: number): number =>
  whole > 0 ? Number(((part / whole) * 100).toFixed(1)) : 0;

/** Copy for the customer-type groups the ledger knows about. */
const CUSTOMER_TYPE_LABELS: Record<string, string> = {
  Parent: "Parents & players",
  Sponsor: "Sponsors",
  "Visiting club": "Visiting clubs",
  Staff: "Staff",
  Account: "Accounts",
};

/**
 * Receivable lines rolled up by customer group, largest revenue first.
 *
 * Costs are payable lines and sit on a project. For the project-based
 * dimensions they attach directly; for customer types each project's
 * cost is spread over the types in that project by their revenue share,
 * so the profit column still adds up to the dashboard's profit figure.
 */
export const customerGroups = (
  rows: LedgerRow[],
  dimension: CustomerGroupDimension,
  /** Domain-aware copy for a customer type; falls back to the built-in labels. */
  roleLabel?: (role: string) => string | undefined
): CustomerGroupRow[] => {
  const ar = arRows(rows);
  const ap = apRows(rows);

  const groupOf = (row: LedgerRow): { id: string; name: string } => {
    switch (dimension) {
      case "customer-type":
        return {
          id: row.entityRole,
          name:
            (roleLabel && roleLabel(row.entityRole)) ||
            CUSTOMER_TYPE_LABELS[row.entityRole] ||
            `${row.entityRole}s`,
        };
      case "project-kind":
        return { id: row.projectKind, name: `${row.projectKind}s` };
      case "project":
      default:
        return { id: row.projectId, name: row.project };
    }
  };

  /* Cost per project, and revenue per project so the pro-rata share can be worked out. */
  const costByProject = new Map<string, number>();
  ap.forEach((row) => costByProject.set(row.projectId, (costByProject.get(row.projectId) || 0) + row.invoicedServiceFee));
  const revenueByProject = new Map<string, number>();
  ar.forEach((row) =>
    revenueByProject.set(row.projectId, (revenueByProject.get(row.projectId) || 0) + row.invoicedServiceFee)
  );

  interface Acc extends CustomerGroupRow {
    accounts: Set<string>;
    projects: Set<string>;
  }
  const map = new Map<string, Acc>();
  const accFor = (row: LedgerRow): Acc => {
    const group = groupOf(row);
    let acc = map.get(group.id);
    if (!acc) {
      acc = {
        id: group.id,
        name: group.name,
        customers: 0,
        customersPct: 0,
        revenue: 0,
        revenuePct: 0,
        collected: 0,
        collectedPct: 0,
        costs: 0,
        profit: 0,
        marginPct: null,
        accounts: new Set<string>(),
        projects: new Set<string>(),
      };
      map.set(group.id, acc);
    }
    return acc;
  };

  ar.forEach((row) => {
    const acc = accFor(row);
    acc.accounts.add(row.entityId);
    acc.projects.add(row.projectId);
    acc.revenue += row.invoicedServiceFee;
    acc.collected += row.collected;
    if (dimension === "customer-type") {
      const projectRevenue = revenueByProject.get(row.projectId) || 0;
      const projectCost = costByProject.get(row.projectId) || 0;
      acc.costs += projectRevenue > 0 ? projectCost * (row.invoicedServiceFee / projectRevenue) : 0;
    }
  });

  if (dimension !== "customer-type") {
    /* Direct attachment; a project with costs but no revenue still shows up. */
    ap.forEach((row) => {
      const acc = accFor(row);
      acc.projects.add(row.projectId);
    });
    map.forEach((acc) => {
      acc.costs = 0;
      acc.projects.forEach((projectId) => {
        acc.costs += costByProject.get(projectId) || 0;
      });
    });
  }

  const totalCustomers = Array.from(map.values()).reduce((sum, acc) => sum + acc.accounts.size, 0);
  const totalRevenue = Array.from(map.values()).reduce((sum, acc) => sum + acc.revenue, 0);

  return Array.from(map.values())
    .map<CustomerGroupRow>((acc) => {
      const profit = acc.revenue - acc.costs;
      return {
        id: acc.id,
        name: acc.name,
        customers: acc.accounts.size,
        customersPct: pct(acc.accounts.size, totalCustomers),
        revenue: round2(acc.revenue),
        revenuePct: pct(acc.revenue, totalRevenue),
        collected: round2(acc.collected),
        collectedPct: pct(acc.collected, acc.revenue),
        costs: round2(acc.costs),
        profit: round2(profit),
        marginPct: acc.revenue > 0 ? Number(((profit / acc.revenue) * 100).toFixed(1)) : null,
      };
    })
    .sort((a, b) => b.revenue - a.revenue);
};

