/** One account's exposure spread over the aging brackets. */
export interface AccountAging {
  key: string;
  entity: string;
  entityRole: string;
  project: string;
  projectId: string;
  buckets: Record<AgingBucket, number>;
  total: number;
  /** Share of the side's total exposure, 0-100. */
  sharePct: number;
  /** Longest overdue line on the account, in hours. */
  maxPastDueHours: number;
  ledgerKeys: string[];
}

/**
 * Exposure by account for one side of the ledger, most exposed first.
 * Exposure is what is still owed: outstanding while current, past due
 * once late - the same split the aging cards use.
 */
export const agingByAccount = (rows: LedgerRow[], side: LedgerSide): AccountAging[] => {
  const map = new Map<string, AccountAging>();
  rows
    .filter((row) => row.side === side && (row.outstanding > 0 || row.pastDue > 0))
    .forEach((row) => {
      const key = `${row.entity}|${row.projectId}`;
      const acc = map.get(key) || {
        key,
        entity: row.entity,
        entityRole: row.entityRole,
        project: row.project,
        projectId: row.projectId,
        buckets: { current: 0, "1-30": 0, "31-60": 0, "61+": 0 },
        total: 0,
        sharePct: 0,
        maxPastDueHours: 0,
        ledgerKeys: [],
      };
      const bucket = agingBucketOf(row);
      const exposure = bucket === "current" ? row.outstanding : row.pastDue;
      acc.buckets[bucket] += exposure;
      /* A late row can still carry a not-yet-due balance. */
      if (bucket !== "current" && row.outstanding > 0) acc.buckets.current += row.outstanding;
      acc.total += exposure + (bucket !== "current" ? row.outstanding : 0);
      acc.maxPastDueHours = Math.max(acc.maxPastDueHours, row.pastDueHours);
      acc.ledgerKeys.push(row.key);
      map.set(key, acc);
    });

  const grand = Array.from(map.values()).reduce((sum, acc) => sum + acc.total, 0);
  return Array.from(map.values())
    .map((acc) => ({
      ...acc,
      buckets: {
        current: round2(acc.buckets.current),
        "1-30": round2(acc.buckets["1-30"]),
        "31-60": round2(acc.buckets["31-60"]),
        "61+": round2(acc.buckets["61+"]),
      },
      total: round2(acc.total),
      sharePct: pct(acc.total, grand),
    }))
    .sort((a, b) => b.total - a.total);
};

/* ------------------------------------------------------------------ */
/* Transactions filter                                                 */
/* ------------------------------------------------------------------ */

export const EMPTY_FILTER: TransactionFilter = {
  search: "",
  range: null,
  side: null,
  projectIds: [],
  entityRoles: [],
  rowStatuses: [],
  scheduleStatuses: [],
  aging: null,
  forms: [],
  methods: [],
  cadences: [],
  amountMin: null,
  amountMax: null,
  flags: [],
  only: [],
};

export const ROW_STATUS_LABELS: Record<RowStatus, string> = {
  paid: "Paid",
  partial: "Partial",
  overdue: "Overdue",
  refunded: "Refunded",
};

/** Where a single ledger line stands. Refunds win, then arrears, then settlement. */
export const rowStatusOf = (row: LedgerRow): RowStatus => {
  if (row.refund) return "refunded";
  if (row.pastDue > 0) return "overdue";
  if (row.outstanding <= 0) return "paid";
  return "partial";
};

/** How many filters are set, for the badge on the filter button. Search and dates are visible on their own. */
export const countActiveFilters = (filter: TransactionFilter): number =>
  [
    filter.side !== null,
    filter.projectIds.length > 0,
    filter.entityRoles.length > 0,
    filter.rowStatuses.length > 0,
    filter.scheduleStatuses.length > 0,
    filter.aging !== null,
    filter.forms.length > 0,
    filter.methods.length > 0,
    filter.cadences.length > 0,
    filter.amountMin !== null || filter.amountMax !== null,
    filter.flags.length > 0,
    filter.only.length > 0,
  ].filter(Boolean).length;

const matchesSearch = (haystack: string, term: string) =>
  !term || haystack.toLowerCase().indexOf(term.toLowerCase()) !== -1;

const inAmount = (amount: number, filter: TransactionFilter) =>
  (filter.amountMin === null || amount >= filter.amountMin) &&
  (filter.amountMax === null || amount <= filter.amountMax);

const anyOf = <T,>(chosen: T[], value: T) => chosen.length === 0 || chosen.indexOf(value) !== -1;

/** Ledger lines that pass every set filter. */
export const filterLedgerRows = (rows: LedgerRow[], filter: TransactionFilter): LedgerRow[] => {
  const term = filter.search.trim();
  return rows.filter((row) => {
    if (!matchesSearch(`${row.entity} ${row.project} ${row.invoiceId} ${row.entityRole}`, term)) return false;
    if (filter.range && (row.lastActivityAt < filter.range.from || row.lastActivityAt > filter.range.to)) return false;
    if (filter.side && row.side !== filter.side) return false;
    if (!anyOf(filter.projectIds, row.projectId)) return false;
    if (!anyOf(filter.entityRoles, row.entityRole)) return false;
    if (!anyOf(filter.rowStatuses, rowStatusOf(row))) return false;
    if (filter.aging && agingBucketOf(row) !== filter.aging) return false;
    if (!anyOf(filter.forms, row.form)) return false;
    if (!anyOf(filter.methods, row.method)) return false;
    if (!anyOf(filter.cadences, row.cadence)) return false;
    if (!inAmount(row.invoicedServiceFee, filter)) return false;
    if (filter.flags.length > 0 && !row.flags.some((flag) => filter.flags.indexOf(flag.kind) !== -1)) return false;
    if (filter.only.indexOf("adjustments") !== -1 && row.adjustments.length === 0) return false;
    if (filter.only.indexOf("refund") !== -1 && !row.refund) return false;
    if (filter.only.indexOf("flags") !== -1 && row.flags.length === 0) return false;
    return true;
  });
};

/**
 * Schedule items that pass the filters that apply to them. Ledger-only
 * filters (form, method, cadence, flags, markers) are answered by the
 * ledger line behind the item when there is one, and ignored otherwise.
 */
export const filterScheduleItems = (
  items: ScheduleItem[],
  rows: LedgerRow[],
  filter: TransactionFilter
): ScheduleItem[] => {
  const term = filter.search.trim();
  const byKey = new Map(rows.map((row) => [row.key, row] as [string, LedgerRow]));
  return items.filter((item) => {
    if (!matchesSearch(`${item.entity} ${item.project} ${item.entityRole}`, term)) return false;
    if (filter.range && (item.dueAt < filter.range.from || item.dueAt > filter.range.to)) return false;
    if (filter.side && item.side !== filter.side) return false;
    if (filter.projectIds.length > 0 && (!item.projectId || filter.projectIds.indexOf(item.projectId) === -1)) return false;
    if (!anyOf(filter.entityRoles, item.entityRole)) return false;
    if (!anyOf(filter.scheduleStatuses, item.status)) return false;
    if (!inAmount(item.amount, filter)) return false;

    const row = item.ledgerKey ? byKey.get(item.ledgerKey) : undefined;
    if (row) {
      if (filter.aging && agingBucketOf(row) !== filter.aging) return false;
      if (!anyOf(filter.forms, row.form)) return false;
      if (!anyOf(filter.methods, row.method)) return false;
      if (!anyOf(filter.cadences, row.cadence)) return false;
      if (filter.flags.length > 0 && !row.flags.some((flag) => filter.flags.indexOf(flag.kind) !== -1)) return false;
      if (filter.only.indexOf("adjustments") !== -1 && row.adjustments.length === 0) return false;
      if (filter.only.indexOf("refund") !== -1 && !row.refund) return false;
      if (filter.only.indexOf("flags") !== -1 && row.flags.length === 0) return false;
    }
    return true;
  });
};
