const ProfileList = ({coachList, currentCoachPage, totalCount = 0, defaultPageSize = 10, onChange}) => {
   const [profiles, setProfiles] = useState(coachList);
   const [currentPage, setCurrentPage] = useState(currentCoachPage);

  const onPageChange = (page)=>{
    setCurrentPage(page);
    onChange(page);
  }

   let notification = "";

   const removeProfile = (id)=>{

   const filteredProfiles  = profiles.filter((el)=> el.id !== id);
    setProfiles([...filteredProfiles]);
    notification = "Coach removed from search successfully";
    pushNotification(
      notification,
      "successs",
      "TOP_CENTER",
      1000
    );
  }

  
  return (
  <>
  <div className="profile-list">
     {coachList.map((sampleProfile, idx)=>
        <ProfileCard  key={idx} profile={sampleProfile}  remove={removeProfile} />
     )}
  </div>

      <div className="pagination">
      <Pagination
          current={currentPage}
          total={totalCount}
          pageSize={defaultPageSize} // Number of profiles per page
          onChange={(page) => onPageChange(page)}
          showSizeChanger={false} // Optional: hide page size changer
        />
      </div>
   
  </>);

};

export default ProfileList;
