import React, { useState } from "react";
import { Alert, Button, Modal } from "antd";
import { Pill } from "../../../common/ui";
import {
  AVAILABILITY_META,
  DayJob,
  DriverEvaluation,
  formatMinutes,
  isRecommended,
} from "../../../common/driverAvailability/availability";
import DayTimeline from "../../../common/driverAvailability/DayTimeline";

interface Props {
  job?: DayJob;
  evaluation?: DriverEvaluation;
  onAssign: () => Promise<void>;
  onMoreOptions: () => void;
  onCancel: () => void;
}

/** One-click confirmation after dropping a job on a driver. */
const QuickAssignModal = ({ job, evaluation, onAssign, onMoreOptions, onCancel }: Props) => {
  const [saving, setSaving] = useState(false);
  if (!job || !evaluation) return null;

  const meta = AVAILABILITY_META[evaluation.availability];
  const row = job.raw || {};
  const warning = isRecommended(evaluation)
    ? undefined
    : evaluation.availability === "time-off"
    ? `${evaluation.driver.name} has approved time off today.`
    : evaluation.conflicts.length
    ? `Clashes with ${evaluation.conflicts
        .map((c) => `${c.label} at ${formatMinutes(c.pickupMin)}`)
        .join(", ")}.`
    : `${evaluation.driver.name} isn't on shift at this time.`;

  return (
    <Modal
      open
      width={520}
      className="mx-modal"
      title={`Assign to ${evaluation.driver.name}?`}
      onCancel={onCancel}
      footer={[
        <Button key="more" type="link" onClick={onMoreOptions} style={{ marginRight: "auto" }}>
          More options…
        </Button>,
        <Button key="cancel" className="mx-btn-secondary" onClick={onCancel}>
          Cancel
        </Button>,
        <Button
          key="assign"
          className="mx-btn-primary"
          loading={saving}
          onClick={async () => {
            setSaving(true);
            await onAssign();
            setSaving(false);
          }}
        >
          Assign
        </Button>,
      ]}
    >
      <div className="mx-job-summary">
        <div className="mx-job-summary__head">
          <div className="mx-job-summary__patient">{job.label}</div>
          <div className="mx-job-summary__when">
            {job.pickupMin !== undefined ? `Pickup ${formatMinutes(job.pickupMin)}` : "No pickup time"}
          </div>
        </div>
        <div className="mx-job-summary__route">
          {row.address && (
            <div>
              <span className="mx-job-summary__dot mx-job-summary__dot--from" />
              {row.address}
            </div>
          )}
          {row.dropoffAddress && (
            <div>
              <span className="mx-job-summary__dot mx-job-summary__dot--to" />
              {row.dropoffAddress}
            </div>
          )}
        </div>
        {row.driverNameFull?.trim() && (
          <div className="mx-job-summary__note">Currently: {row.driverNameFull}</div>
        )}
      </div>

      <div style={{ display: "flex", gap: 6, alignItems: "center", marginBottom: 6 }}>
        <Pill tone={meta.tone}>{meta.label}</Pill>
        <Pill tone="gray" plain>
          {evaluation.jobs.length} other {evaluation.jobs.length === 1 ? "job" : "jobs"} today
        </Pill>
      </div>
      {evaluation.reasons.length > 0 && (
        <div style={{ color: "#6b7a90", fontSize: 13 }}>{evaluation.reasons.join(" · ")}</div>
      )}
      <DayTimeline
        slots={evaluation.slots}
        jobs={evaluation.jobs}
        pickupMin={job.pickupMin}
        showTicks
      />
      {warning && <Alert className="mt-3" type="warning" showIcon message={warning} />}
    </Modal>
  );
};

export default QuickAssignModal;
