const INCOME_BRACKETS = [
    { min: 0, max: 31300, householdSize: 3 },           // $0-$31,300 = household size of 3 or fewer
    { min: 31301, max: 42300, householdSize: 4 },       // $31,301-$42,300 = household size of 4
    { min: 42301, max: 53300, householdSize: 5 },       // $42,301-$53,300 = household size of 5
    { min: 53301, max: 64300, householdSize: 6 },       // $53,301-$64,300 = household size of 6
    { min: 64301, max: 75300, householdSize: 7 },       // $64,301-$75,300 = household size of 7
    { min: 75301, max: 86300, householdSize: 8 },       // $75,301-$86,300 = household size of 8
    { min: 86301, max: 97300, householdSize: 9 },       // $86,301-$97,300 = household size of 9
    { min: 97301, max: 108300, householdSize: 10 },     // $97,301-$108,300 = household size of 10
    { min: 108301, max: 119300, householdSize: 11 },    // $108,301-$119,300 = household size of 11
    { min: 119301, max: 130300, householdSize: 12 },    // $119,301-$130,300 = household size of 12
    { min: 130301, max: 141300, householdSize: 13 },    // $130,301-$141,300 = household size of 13
    { min: 141301, max: 152300, householdSize: 14 },    // $141,301-$152,300 = household size of 14
    { min: 152301, max: Infinity, householdSize: 15 },  // $152,301+ = household size of 15+
];

function parseIncome(incomeString: string): number | null {
    if (!incomeString || typeof incomeString !== 'string') {
        return null;
    }

    const match = incomeString.match(/\$?([0-9,]+)/);
    if (!match) {
        return null;
    }

    // Remove commas and convert to number
    const parsed = parseInt(match[1].replace(/,/g, ''), 10);

    // Return null if parsing resulted in NaN or if the original string doesn't look like a valid income
    if (isNaN(parsed) || !incomeString.match(/^\$?[0-9,]+/)) {
        return null;
    }

    return parsed;
}

function calculateHouseholdSize(dependents: number, adults: number): number {
    // Ensure we have at least one dependent (required for TANF eligibility)
    if (dependents < 1) {
        return 0; // Not eligible - no dependents
    }

    // Count all dependents
    const dependentCount = dependents;

    // Count up to 2 adults (if more than 2 adults, still only count 2)
    const adultCount = Math.min(adults, 2);

    return dependentCount + adultCount;
}

function getMaxIncomeForHouseholdSize(householdSize: number): number {
    for (const bracket of INCOME_BRACKETS) {
        if (bracket.householdSize === householdSize) {
            return bracket.max;
        }
    }
    // If household size is larger than any bracket, use the highest income limit
    return INCOME_BRACKETS[INCOME_BRACKETS.length - 1].max;
}

/**
 * Calculates TANF eligibility based on household composition and income
 * 
 * @param data Object containing household income and member counts
 * @returns "Yes" if eligible, "No" if not eligible
 */
export function calculateTANFEligibility(data: any): string {
    try {
        // Parse input data (support both new and legacy keys)
        const dependents = parseInt(
            (data['17yearsOldMembers'] ?? data.seventeenYearsOldMembers ?? '0'),
            10
        );
        const adults = parseInt(
            (data['18To65yearsOldMembers'] ?? data.eighteenTo65YearsOldMembers ?? '0'),
            10
        );
        const income = parseIncome(data.houseHoldIncome || '');

        // Validate input data
        if (isNaN(dependents) || isNaN(adults) || income === null) {
            console.warn('TANF Eligibility: Invalid input data', { dependents, adults, income });
            return "No";
        }

        // Calculate actual household size
        const actualHouseholdSize = calculateHouseholdSize(dependents, adults);

        // Check if family has dependents (required for TANF eligibility)
        if (actualHouseholdSize === 0) {
            return "No"; // No dependents = not eligible
        }

        // Get maximum income allowed for this household size
        const maxIncomeAllowed = getMaxIncomeForHouseholdSize(actualHouseholdSize);

        // Eligibility rule: household qualifies if their income is within the allowed limit
        // Each household size has a maximum income limit
        const isEligible = income <= maxIncomeAllowed;

        console.log('TANF Eligibility Calculation:', {
            dependents,
            adults,
            income,
            actualHouseholdSize,
            maxIncomeAllowed,
            isEligible
        });

        return isEligible ? "Yes" : "No";

    } catch (error) {
        console.error('TANF Eligibility Calculation Error:', error);
        return "No";
    }
}

