import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  getConstraints,
  getConstraintsCatalog,
  getSettings,
  listActivities,
  listResources,
} from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage, SchedulerApiError } from "services/apis/aiSchedulerClient";
import { pushNotification } from "utils/notifications";
import {
  ConstraintDef,
  OrgSettings,
  SchedActivity,
  SchedResource,
} from "services/apis/aiSchedulerTypes";

export interface SchedulerData {
  settings: OrgSettings | undefined;
  settingsMissing: boolean;
  resources: SchedResource[];
  activities: SchedActivity[];
  catalog: ConstraintDef[];
  overrides: ConstraintDef[];
  resourcesById: Record<string, SchedResource>;
  activitiesById: Record<string, SchedActivity>;
  loading: boolean;
  loadError: string | undefined;
  unauthorized: boolean;
  refetchSettings: () => Promise<void>;
  refetchResources: () => Promise<void>;
  refetchActivities: () => Promise<void>;
  refetchConstraints: () => Promise<void>;
  refetchAll: () => Promise<void>;
}

const useSchedulerData = (orgId: string | undefined): SchedulerData => {
  const [settings, setSettings] = useState<OrgSettings | undefined>(undefined);
  const [settingsMissing, setSettingsMissing] = useState(false);
  const [resources, setResources] = useState<SchedResource[]>([]);
  const [activities, setActivities] = useState<SchedActivity[]>([]);
  const [catalog, setCatalog] = useState<ConstraintDef[]>([]);
  const [overrides, setOverrides] = useState<ConstraintDef[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | undefined>(undefined);
  const [unauthorized, setUnauthorized] = useState(false);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const refetchSettings = useCallback(async () => {
    if (!orgId) return;
    try {
      const s = await getSettings(orgId);
      if (!mountedRef.current) return;
      if (s && s.slotMinutes && s.days?.length) {
        setSettings(s);
        setSettingsMissing(false);
      } else {
        setSettings(undefined);
        setSettingsMissing(true);
      }
    } catch (e: any) {
      if (!mountedRef.current) return;
      // A brand-new org has no settings yet; treat 404 as "not configured".
      if (e instanceof SchedulerApiError && e.status === 404) {
        setSettings(undefined);
        setSettingsMissing(true);
      } else {
        throw e;
      }
    }
  }, [orgId]);

  const refetchResources = useCallback(async () => {
    if (!orgId) return;
    const list = await listResources(orgId);
    if (mountedRef.current) setResources(list || []);
  }, [orgId]);

  const refetchActivities = useCallback(async () => {
    if (!orgId) return;
    const list = await listActivities(orgId);
    if (mountedRef.current) setActivities(list || []);
  }, [orgId]);

  const refetchConstraints = useCallback(async () => {
    if (!orgId) return;
    const [cat, over] = await Promise.all([
      getConstraintsCatalog(orgId),
      getConstraints(orgId),
    ]);
    if (mountedRef.current) {
      setCatalog(cat || []);
      setOverrides(over || []);
    }
  }, [orgId]);

  const refetchAll = useCallback(async () => {
    if (!orgId) return;
    setLoading(true);
    setLoadError(undefined);
    setUnauthorized(false);
    try {
      await Promise.all([
        refetchSettings(),
        refetchResources(),
        refetchActivities(),
        refetchConstraints(),
      ]);
    } catch (e: any) {
      if (mountedRef.current) {
        if (e instanceof SchedulerApiError && e.status === 401) {
          setUnauthorized(true);
        }
        setLoadError(getErrorMessage(e));
      }
    } finally {
      if (mountedRef.current) setLoading(false);
    }
  }, [orgId, refetchSettings, refetchResources, refetchActivities, refetchConstraints]);

  useEffect(() => {
    refetchAll();
  }, [refetchAll]);

  const resourcesById = useMemo(() => {
    const map: Record<string, SchedResource> = {};
    resources.forEach((r) => {
      if (r.id) map[r.id] = r;
    });
    return map;
  }, [resources]);

  const activitiesById = useMemo(() => {
    const map: Record<string, SchedActivity> = {};
    activities.forEach((a) => {
      if (a.id) map[a.id] = a;
    });
    return map;
  }, [activities]);

  // Individual refetchers are called fire-and-forget from save flows —
  // surface failures as toasts instead of unhandled rejections.
  const safe = useCallback(
    (fn: () => Promise<void>) => async () => {
      try {
        await fn();
      } catch (e) {
        pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
      }
    },
    []
  );

  const safeRefetchSettings = useMemo(() => safe(refetchSettings), [safe, refetchSettings]);
  const safeRefetchResources = useMemo(() => safe(refetchResources), [safe, refetchResources]);
  const safeRefetchActivities = useMemo(() => safe(refetchActivities), [safe, refetchActivities]);
  const safeRefetchConstraints = useMemo(() => safe(refetchConstraints), [safe, refetchConstraints]);

  return {
    settings,
    settingsMissing,
    resources,
    activities,
    catalog,
    overrides,
    resourcesById,
    activitiesById,
    loading,
    loadError,
    unauthorized,
    refetchSettings: safeRefetchSettings,
    refetchResources: safeRefetchResources,
    refetchActivities: safeRefetchActivities,
    refetchConstraints: safeRefetchConstraints,
    refetchAll,
  };
};

export default useSchedulerData;
