import React, { FC } from "react";
import { Form, Input, InputNumber, Select } from "antd";

import { AppliedAdjustments, PaymentConfig } from "../types";
import { describeAmount, ruleAmount } from "../paymentConfig";
import { nullable, num } from "../PaymentConfigForm/fields";

interface Props {
  config: PaymentConfig;
  value: AppliedAdjustments;
  onChange: (next: AppliedAdjustments) => void;
  /** Group level shows only promo and waiver; a member gets all four plus a note. */
  scope: "group" | "member";
  note?: string;
  onNoteChange?: (next: string) => void;
}

/**
 * The per-registration inputs of section 6.1: which waiver and promo
 * code apply, the scholarship award, and which child of the household
 * the recipient is. Picked from the configuration they belong to.
 */
const AppliedStrip: FC<Props> = ({ config, value, onChange, scope, note, onNoteChange }) => {
  const patch = (changes: Partial<AppliedAdjustments>) => onChange({ ...value, ...changes });
  const { currency } = config;
  const waivers = config.discounts.waivers;
  const promos = config.discounts.promoCodes;
  const scholarshipCap = config.scholarship.enabled
    ? ruleAmount(config.scholarship, config.totalAmount)
    : 0;

  return (
    <div className="cfo-applied-strip">
      <div className="cfo-applied-strip__head">
        <span className="cfo-applied-strip__title">Applied to this request</span>
        <span className="cfo-applied-strip__hint">
          Adjustments the configuration offers but does not decide by itself.
        </span>
      </div>
      <Form layout="vertical" className="cfo-applied-strip__form">
        <Form.Item label="Waiver">
          <Select
            allowClear
            placeholder={waivers.length ? "None" : "No waivers on this configuration"}
            disabled={waivers.length === 0}
            value={value.waiverId || undefined}
            options={waivers.map((w) => ({ value: w._id, label: `${w.name} (${describeAmount(w, currency)})` }))}
            onChange={(waiverId) => patch({ waiverId: waiverId || null })}
          />
        </Form.Item>
        <Form.Item label="Promo code">
          {promos.length > 0 ? (
            <Select
              allowClear
              placeholder="None"
              value={value.promoCode || undefined}
              options={promos.map((p) => ({ value: p.code, label: `${p.code} (${describeAmount(p, currency)})` }))}
              onChange={(promoCode) => patch({ promoCode: promoCode || null })}
            />
          ) : (
            <Input disabled placeholder="No promo codes on this configuration" />
          )}
        </Form.Item>
        {scope === "member" && (
          <>
            <Form.Item
              label="Scholarship award"
              extra={
                config.scholarship.enabled
                  ? `Up to ${describeAmount(config.scholarship, currency)} of the running total`
                  : "Scholarships are not offered on this configuration"
              }
            >
              <InputNumber
                style={{ width: "100%" }}
                min={0}
                max={scholarshipCap || undefined}
                disabled={!config.scholarship.enabled}
                value={value.scholarshipAward === null ? undefined : value.scholarshipAward}
                addonAfter={currency}
                onChange={(next) => patch({ scholarshipAward: nullable(next) })}
              />
            </Form.Item>
            <Form.Item
              label="Child number in household"
              extra={
                config.discounts.sibling.enabled
                  ? `Sibling discount from child ${config.discounts.sibling.appliesFromChild}`
                  : "No sibling discount on this configuration"
              }
            >
              <InputNumber
                style={{ width: "100%" }}
                min={1}
                step={1}
                value={value.childNumber}
                onChange={(next) => patch({ childNumber: Math.max(1, Math.round(num(next))) })}
              />
            </Form.Item>
            <Form.Item label="Note (audit trail)" className="cfo-applied-strip__note">
              <Input.TextArea
                rows={1}
                value={note}
                placeholder="Why this member deviates from the group request"
                onChange={(e) => onNoteChange && onNoteChange(e.target.value)}
              />
            </Form.Item>
          </>
        )}
      </Form>
    </div>
  );
};

export default AppliedStrip;
