import React, { FC, useMemo, useRef, useState } from "react";
import { Col, Modal, Row, Table } from "antd";
import { useDispatch, useSelector } from "react-redux";
import { SocketTopics } from "constants/enums";
import { getFocusPagePublishTopic } from "hooks/MQTTConstants";
import { RootState } from "reducers/rootReducer";
import { ADD_OTHER_LOCATION, ENCRYPT_TOKEN, SET_SUBMITTED } from "reducers/reducer";
import "react-resizable/css/styles.css";
import "../Dashboard.scss";
import { buildColumns } from "./columns";
import ColumnVisibilityDropdown from "./components/ColumnVisibilityDropdown";
import { AssignmentDrawer, ChatDrawer } from "./components/DashboardDrawers";
import FilterPanel from "./components/filters/FilterPanel";
import ActiveFilterChips, { getActiveFilters } from "./components/filters/ActiveFilterChips";
import HistoryModal from "./components/HistoryModal";
import ResizableTitle from "./components/ResizableTitle";
import SortModal from "./components/SortModal";
import StatusSummary from "./components/StatusSummary";
import Toolbar from "./components/Toolbar";
import { RowActionKey, RowActions } from "./components/cells";
import { useDashboardFilters } from "./hooks/useDashboardFilters";
import { useFilterOptions } from "./hooks/useFilterOptions";
import { useResizableColumns } from "./hooks/useResizableColumns";
import { useRideData } from "./hooks/useRideData";
import { useSortOrders } from "./hooks/useSortOrders";
import { useQuickAssign } from "./hooks/useQuickAssign";
import { useSyncedScroll } from "./hooks/useSyncedScroll";
import { RideRow } from "./types";
import DispatchBoard from "./components/DispatchBoard";
import { DashboardView } from "./components/Toolbar";
import { EmptyState } from "../../common/ui";
import { exportToPDF, exportToSpreadsheet } from "./utils/export";
import { groupRowsByShift } from "./utils/rows";
import { applyDefaultSort, applyMultiColumnSort } from "./utils/sorting";

export { RideStatus, colorRideStatusMapping, statusColorMapping } from "./constants";

const TABLE_COMPONENTS = { header: { cell: ResizableTitle } };
const VIEW_STORAGE_KEY = "dashboardView";

const DashboardModal: FC<{
  socket: ISocket;
  params?: any;
  filter?: boolean;
  selected?: string;
  componentUuid?: string;
  toggleMap?: () => void;
  /** Whether the map above the table is showing (for the toolbar toggle). */
  mapVisible?: boolean;
  toggleDispatch?: () => void;
}> = ({ socket, filter, selected, componentUuid, toggleMap, mapVisible, toggleDispatch }) => {
  const dispatch = useDispatch();
  const { encrypted_token, projects, selectedPage } = useSelector(
    (state: RootState) => state.auth
  );

  const { filters, update, setTimeRange, reset } = useDashboardFilters();
  const options = useFilterOptions(socket, filters.entityType, filters.areaType);
  const activeFilters = getActiveFilters(
    filters,
    { onChange: update, onTimeRangeChange: setTimeRange },
    options
  );
  const data = useRideData({ socket, filters, componentUuid, forcedView: selected });
  const [sortOrders, setSortOrders] = useSortOrders();
  const quickAssign = useQuickAssign(socket, data.rows);

  const [showFilters, setShowFilters] = useState(false);
  const [showSortModal, setShowSortModal] = useState(false);
  const [chatUrl, setChatUrl] = useState<string>();
  // Which ride is being assigned, and the driver it was dropped on (board).
  const [assigning, setAssigning] = useState<{ row: RideRow; driverId?: string } | null>(null);
  const [view, setView] = useState<DashboardView>(() => {
    try {
      return localStorage.getItem(VIEW_STORAGE_KEY) === "board" ? "board" : "table";
    } catch {
      return "table";
    }
  });
  const changeView = (next: DashboardView) => {
    setView(next);
    try {
      localStorage.setItem(VIEW_STORAGE_KEY, next);
    } catch {
      // Non-essential preference.
    }
  };
  const [historyRow, setHistoryRow] = useState<RideRow | null>(null);

  // Grouping and sorting are derived from the raw rows, so a live update,
  // a new sort or late-arriving shift data can never leave them out of step.
  const tableData = useMemo(() => {
    const { rows, responders, shift, shiftDay } = data;
    const grouped =
      shiftDay !== undefined ? groupRowsByShift(rows, responders, shift, shiftDay) : rows;
    if (sortOrders.length > 0) return applyMultiColumnSort(grouped, sortOrders);
    return shiftDay !== undefined ? grouped : applyDefaultSort(grouped);
  }, [data.rows, data.responders, data.shift, data.shiftDay, sortOrders]);

  /* ------------------------------------------------------------ row actions */

  const selectPage = (record: RideRow) => {
    dispatch({ type: SET_SUBMITTED, payload: false });
    dispatch({ type: "SET_SELECTED_PAGE", payload: { page: record?.action?.page } });
  };

  const openChat = (pageId: string) =>
    dispatch(
      ENCRYPT_TOKEN({
        data: {
          payload: JSON.stringify({
            userId: encrypted_token?.userId,
            connectionId: encrypted_token?.connectionId,
            cudbServiceId: projects?.userServiceId,
          }),
        },
        callback: (token) =>
          setChatUrl(
            `${process.env.REACT_APP_WEB}/auth/login?token=${token.encryptedPayload}&redirect=page/${pageId}`
          ),
      })
    );

  const openAssignment = (record: RideRow, driverId?: string) => {
    selectPage(record);
    setAssigning({ row: record, driverId });
  };

  const confirmDelete = (record: RideRow) => {
    const pageId = record.action?.pageId?.toString() || record.key?.toString();
    Modal.confirm({
      title: "Delete Confirmation",
      content: "Are you sure you want to delete this item?",
      okText: "Yes, Delete",
      okType: "danger",
      cancelText: "Cancel",
      onOk: () => data.deletePage(pageId),
    });
  };

  const handleAction = (key: RowActionKey, record: RideRow) => {
    const { action } = record;
    switch (key) {
      case "focus-chat":
        openChat(action?.pageId);
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getFocusPagePublishTopic(action?.pageId, encrypted_token?.userId),
          { page: action?.page }
        );
        break;
      case "copy":
        navigator.clipboard.writeText(record.description ?? "");
        break;
      case "focus-map": {
        const attrs = action?.page?.profile?.unstructuredAttributes;
        dispatch({ type: ADD_OTHER_LOCATION, payload: { pickupLocation: attrs?.pickupLocation } });
        dispatch({ type: ADD_OTHER_LOCATION, payload: { dropoffLocation: attrs?.dropoffLocation } });
        break;
      }
      case "assignment":
        openAssignment(record);
        break;
      case "history":
        setHistoryRow(record);
        break;
      case "summary":
        window.open(
          `${window.location.origin}/${action.summary}?connectionId=${encrypted_token?.connectionId}&pageId=${action.pageId}&cudbServiceId=${action.cudbServiceId}`,
          "_blank"
        );
        break;
      case "delete":
        confirmDelete(record);
        break;
    }
  };

  // Columns are built once; this ref always points at the current handlers.
  const actionsRef = useRef<RowActions>();
  actionsRef.current = {
    onStatusChange: (record, color) => data.changeStatus(record.key, color),
    onAction: handleAction,
  };
  const baseColumns = useMemo(
    () =>
      buildColumns({
        onStatusChange: (...args) => actionsRef.current.onStatusChange(...args),
        onAction: (...args) => actionsRef.current.onAction(...args),
      }),
    []
  );
  const { columns, totalWidth, visibleKeys, setVisibleKeys, resetLayout } =
    useResizableColumns(baseColumns);

  const { topRef, tableRef } = useSyncedScroll([columns.length]);

  /* ---------------------------------------------------------------- toolbar */

  const handleExport = (type: "csv" | "xlsx" | "pdf") =>
    type === "pdf" ? exportToPDF(tableData, baseColumns) : exportToSpreadsheet(tableData, type);

  const handleReset = () => {
    reset();
    data.reload();
  };

  const closeAssignment = () => {
    dispatch({ type: "SET_SELECTED_PAGE", payload: { page: undefined } });
    dispatch({ type: SET_SUBMITTED, payload: false });
    setAssigning(null);
  };

  return (
    <React.Fragment>
      <FilterPanel
        visible={showFilters}
        filters={filters}
        onChange={update}
        onTimeRangeChange={setTimeRange}
        onExport={handleExport}
        onClearAll={handleReset}
        activeCount={activeFilters.length}
        {...options}
      />

      {filter && (
        <StatusSummary
          counts={data.statusCount}
          selected={filters.status}
          onSelect={(status) => update({ status })}
        />
      )}

      <Toolbar
        view={view}
        onViewChange={changeView}
        loading={data.loading}
        onToggleMap={toggleMap}
        mapVisible={mapVisible}
        onToggleFilters={() => setShowFilters((v) => !v)}
        filtersOpen={showFilters}
        activeFilterCount={activeFilters.length}
        sortCount={sortOrders.length}
        onRefresh={data.reload}
        onReset={handleReset}
        onSort={() => setShowSortModal(true)}
        columnSettings={
          <ColumnVisibilityDropdown
            columns={baseColumns}
            visibleKeys={visibleKeys}
            onChange={setVisibleKeys}
            onReset={resetLayout}
          />
        }
      />

      <ActiveFilterChips chips={activeFilters} onClearAll={handleReset} />

      {view === "board" ? (
        data.shiftDay !== undefined ? (
          <DispatchBoard
            day={data.shiftDay}
            rows={data.rows}
            onQuickAssign={quickAssign.assign}
            pending={quickAssign.pending}
            onOpenJob={openAssignment}
            onEditJob={(record) => {
              selectPage(record);
              toggleDispatch?.();
            }}
          />
        ) : (
          <EmptyState
            title="The driver board shows one day at a time"
            description="Pick Today, Tomorrow or a specific date to see drivers' shifts and jobs side by side."
            action={{ label: "Show today", onClick: () => setTimeRange({ selected: "today" }) }}
          />
        )
      ) : (
      <Row gutter={20} className="scrollable-table">
        <Col xs={24} sm={24} md={24} className="table-scroll-wrapper">
          <div
            ref={topRef}
            className="custom-scrollbar"
            style={{ overflowX: "auto", overflowY: "hidden", height: 12, marginBottom: 8 }}
          >
            <div style={{ width: totalWidth, height: 1 }} />
          </div>

          <div ref={tableRef} style={{ marginBottom: 100 }}>
            <Table
              tableLayout="fixed"
              dataSource={tableData}
              columns={columns}
              components={TABLE_COMPONENTS}
              pagination={false}
              scroll={{ y: 1000, x: totalWidth }}
              onRow={(record) => ({
                onDoubleClick: () => {
                  selectPage(record);
                  toggleDispatch?.();
                },
              })}
              rowClassName={(record) => {
                if (!record) return "";
                const selectedId = selectedPage?.page?.pageId?.toString();
                if (record.key === selectedId && !selectedPage?.ignorePage) {
                  return "row-selected";
                }
                return record.pageStatus ? `medical-${record.pageStatus}-row` : "";
              }}
            />
          </div>
        </Col>
      </Row>
      )}

      <ChatDrawer url={chatUrl} onClose={() => setChatUrl(undefined)} />

      <AssignmentDrawer
        open={!!assigning}
        preferredDriverId={assigning?.driverId}
        title={
          assigning && (
            <span>
              Assign driver
              <span className="mx-drawer-subtitle">
                {assigning.row.patientName}
                {assigning.row.pickupTime && assigning.row.pickupTime !== "Unknown Time"
                  ? ` · ${assigning.row.pickupDate || ""} ${assigning.row.pickupTime}`
                  : ""}
              </span>
            </span>
          )
        }
        socket={socket}
        onClose={closeAssignment}
        onDone={() => setAssigning(null)}
      />

      <HistoryModal
        open={!!historyRow}
        changelog={historyRow?.changeLog}
        onClose={() => setHistoryRow(null)}
      />

      <SortModal
        open={showSortModal}
        sortOrders={sortOrders}
        onApply={setSortOrders}
        onClose={() => setShowSortModal(false)}
      />
    </React.Fragment>
  );
};

export default DashboardModal;
