import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Assignment,
  Day,
  OrgSettings,
  SchedActivity,
  SchedResource,
  Violation,
} from "services/apis/aiSchedulerTypes";
import {
  assignmentKey,
  packLanes,
  snap,
  toHHMM,
  toMin,
  visibleDays,
} from "../utils";
import AssignmentBlock from "./AssignmentBlock";

const GUTTER_W = 56;
const COL_GAP = 8;
const DRAG_THRESHOLD_PX = 4;
export const DEFAULT_PX_PER_MIN = 2.2;

interface DragState {
  key: string;
  assignment: Assignment;
  startX: number;
  startY: number;
  active: boolean; // passed the threshold
  targetDay: Day;
  targetStartMin: number;
}

const TimetableGrid: FC<{
  settings: OrgSettings;
  assignments: Assignment[];
  activitiesById: Record<string, SchedActivity>;
  resourcesById: Record<string, SchedResource>;
  // violations attributed per assignment key (soft ones shown on blocks)
  violationsByKey: Record<string, Violation[]>;
  validatingKey?: string;
  // resource id to spotlight — other blocks dim
  focusResourceId?: string;
  // key of the block that was just blocked by a hard violation (shake it)
  shakeKey?: string;
  // vertical zoom: pixels per minute
  pxPerMin?: number;
  readOnly?: boolean;
  onMove: (key: string, day: Day, startMin: number) => void;
}> = ({
  settings,
  assignments,
  activitiesById,
  resourcesById,
  violationsByKey,
  validatingKey,
  focusResourceId,
  shakeKey,
  pxPerMin = DEFAULT_PX_PER_MIN,
  readOnly,
  onMove,
}) => {
    const gridRef = useRef<HTMLDivElement>(null);
    const [drag, setDrag] = useState<DragState | null>(null);
    const dragRef = useRef<DragState | null>(null);
    dragRef.current = drag;
    const [openPopoverKey, setOpenPopoverKey] = useState<string | undefined>(undefined);

    const days = useMemo(() => visibleDays(settings, assignments), [settings, assignments]);
    const dayStartMin = toMin(settings.dayStart);
    const dayEndMin = toMin(settings.dayEnd);
    const totalMin = Math.max(dayEndMin - dayStartMin, settings.slotMinutes);
    const bodyHeight = totalMin * pxPerMin;
    // Slot lines every slot, but never denser than one line per 30 min — small
    // slots (5/10/15 min) would otherwise turn the grid into noise.
    const lineEveryMin = Math.max(settings.slotMinutes, 30);

    const byDay = useMemo(() => {
      const map: Record<string, Assignment[]> = {};
      days.forEach((d) => (map[d] = []));
      assignments.forEach((a) => {
        if (!map[a.day]) map[a.day] = [];
        map[a.day].push(a);
      });
      return map;
    }, [assignments, days]);

    const hourMarks = useMemo(() => {
      const marks: number[] = [];
      const firstHour = Math.ceil(dayStartMin / 60) * 60;
      for (let m = firstHour; m <= dayEndMin; m += 60) marks.push(m);
      return marks;
    }, [dayStartMin, dayEndMin]);

    const isPinned = useCallback(
      (a: Assignment): boolean =>
        !!activitiesById[a.activityId]?.pinned?.some(
          (p) => p.occurrence === a.occurrence
        ),
      [activitiesById]
    );

    const matchesFocus = useCallback(
      (a: Assignment): boolean => {
        if (!focusResourceId) return true;
        return Object.values(a.resources || {}).some((ids) =>
          ids?.includes(focusResourceId)
        );
      },
      [focusResourceId]
    );

    // Convert a pointer position into a snapped (day, startMin) target.
    const locateTarget = useCallback(
      (clientX: number, clientY: number, duration: number): { day: Day; startMin: number } | null => {
        const el = gridRef.current;
        if (!el) return null;
        const rect = el.getBoundingClientRect();
        const y = clientY - rect.top + el.scrollTop - HEADER_H;
        // Grid body: [gutter] gap [day] gap [day]… with 6px right padding.
        const n = days.length;
        const colW = (rect.width - GUTTER_W - 6 - COL_GAP * n) / n;
        const x = clientX - rect.left - GUTTER_W - COL_GAP;
        let dayIdx = Math.floor(x / (colW + COL_GAP));
        dayIdx = Math.max(0, Math.min(n - 1, dayIdx));
        let startMin = snap(y / pxPerMin + dayStartMin, settings.slotMinutes);
        startMin = Math.max(dayStartMin, Math.min(startMin, dayEndMin - duration));
        return { day: days[dayIdx], startMin };
      },
      [days, dayStartMin, dayEndMin, settings.slotMinutes, pxPerMin]
    );

    const handlePointerDown = (a: Assignment) => (e: React.PointerEvent) => {
      if (readOnly || validatingKey || isPinned(a)) return;
      if (e.button !== 0 && e.pointerType === "mouse") return;
      (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
      setDrag({
        key: assignmentKey(a),
        assignment: a,
        startX: e.clientX,
        startY: e.clientY,
        active: false,
        targetDay: a.day,
        targetStartMin: toMin(a.start),
      });
    };

    useEffect(() => {
      if (!drag) return;

      const handleMove = (e: PointerEvent) => {
        const current = dragRef.current;
        if (!current) return;
        const dx = e.clientX - current.startX;
        const dy = e.clientY - current.startY;
        const passed =
          current.active || Math.abs(dx) > DRAG_THRESHOLD_PX || Math.abs(dy) > DRAG_THRESHOLD_PX;
        if (!passed) return;
        const duration =
          toMin(current.assignment.end) - toMin(current.assignment.start);
        const target = locateTarget(e.clientX, e.clientY, duration);
        if (!target) return;
        setDrag({
          ...current,
          active: true,
          targetDay: target.day,
          targetStartMin: target.startMin,
        });
        e.preventDefault();
      };

      const handleUp = () => {
        const current = dragRef.current;
        setDrag(null);
        if (!current) return;
        if (!current.active) return; // plain click — Popover handles it
        const origStart = toMin(current.assignment.start);
        if (current.targetDay === current.assignment.day && current.targetStartMin === origStart) {
          return;
        }
        onMove(current.key, current.targetDay, current.targetStartMin);
      };

      const handleKey = (e: KeyboardEvent) => {
        if (e.key === "Escape") setDrag(null);
      };

      window.addEventListener("pointermove", handleMove);
      window.addEventListener("pointerup", handleUp);
      window.addEventListener("keydown", handleKey);
      return () => {
        window.removeEventListener("pointermove", handleMove);
        window.removeEventListener("pointerup", handleUp);
        window.removeEventListener("keydown", handleKey);
      };
    }, [drag !== null, locateTarget, onMove]); // eslint-disable-line react-hooks/exhaustive-deps

    const dragDuration = drag?.active
      ? toMin(drag.assignment.end) - toMin(drag.assignment.start)
      : 0;

    return (
      <div
        className="timetable-wrap"
        ref={gridRef}
        style={
          {
            "--n-days": days.length,
            "--gutter-w": `${GUTTER_W}px`,
            "--col-gap": `${COL_GAP}px`,
          } as React.CSSProperties
        }
      >
        <div className="tt-header-row" style={{ paddingLeft: GUTTER_W }}>
          {days.map((d) => (
            <div key={d} className={`tt-day-head${settings.days.includes(d) ? "" : " off-day"}`}>
              {d.charAt(0).toUpperCase() + d.slice(1)}
              {!settings.days.includes(d) && <span className="off-day-note"> (off-grid)</span>}
            </div>
          ))}
        </div>

        <div className="tt-body" style={{ height: bodyHeight, marginTop: 30 }}>
          <div className="tt-gutter" style={{ width: GUTTER_W }}>
            {hourMarks.map((m) => (
              <div
                key={m}
                className="tt-hour-label"
                style={{ top: (m - dayStartMin) * pxPerMin }}
              >
                {toHHMM(m)}
              </div>
            ))}
          </div>

          {days.map((d) => {
            const laidOut = packLanes(byDay[d] || []);
            return (
              <div
                key={d}
                className="tt-day-col"
                style={{
                  backgroundSize: `100% ${lineEveryMin * pxPerMin}px`,
                }}
              >
                {laidOut.map(({ assignment: a, lane, laneCount }) => {
                  const key = assignmentKey(a);
                  const top = (toMin(a.start) - dayStartMin) * pxPerMin;
                  const height = Math.max(
                    (toMin(a.end) - toMin(a.start)) * pxPerMin,
                    30
                  );
                  const widthPct = 100 / laneCount;
                  return (
                    <AssignmentBlock
                      key={key}
                      assignment={a}
                      activity={activitiesById[a.activityId]}
                      resourcesById={resourcesById}
                      violations={violationsByKey[key] || []}
                      validating={validatingKey === key}
                      dragging={drag?.active && drag.key === key}
                      pinned={isPinned(a)}
                      dimmed={!matchesFocus(a)}
                      shaking={shakeKey === key}
                      popoverVisible={openPopoverKey === key}
                      onPopoverVisibleChange={(v) =>
                        setOpenPopoverKey(v ? key : undefined)
                      }
                      onPointerDown={handlePointerDown(a)}
                      style={{
                        top,
                        height,
                        left: `calc(${lane * widthPct}% + 4px)`,
                        width: `calc(${widthPct}% - 8px)`,
                      }}
                    />
                  );
                })}

                {drag?.active && drag.targetDay === d && (
                  <div
                    className="drag-ghost"
                    style={{
                      top: (drag.targetStartMin - dayStartMin) * pxPerMin,
                      height: dragDuration * pxPerMin,
                    }}
                  >
                    {toHHMM(drag.targetStartMin)}–{toHHMM(drag.targetStartMin + dragDuration)}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

// Header row height used when translating pointer Y into grid minutes.
const HEADER_H = 34;

export default TimetableGrid;
