import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button, Dropdown, Menu, Tooltip } from "antd";
import type { ColumnsType } from "antd/es/table";
import { DownOutlined } from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { ExtendedBioTopics, SocketTopics, UserTopics } from "constants/enums";
import useSocketActions from "../../../../../hooks/socketActions";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { DataTableCard, EmptyState, PageHeader, Pill, RowActions, matchesSearch } from "../../common/ui";
import EditVehicleModal from "./EditVehicleModal";
import {
  REQUEST_TIMEOUT_MS,
  STATUS_OPTIONS,
  VehicleAsset,
  VehicleRow,
  formatMaintenanceMessage,
  maintenanceState,
  statusDisplay,
  toVehicleRow,
  useVehicleLinks,
  useVehicleQuery,
} from "./vehicleApi";
import "../Dashboard.scss";
import "./Vehicle.scss";

const Muted = ({ children }: { children: React.ReactNode }) => (
  <span className="mx-vehicle__muted">{children}</span>
);

const MaintenanceCell = ({ row }: { row: VehicleRow }) => {
  const state = maintenanceState(row.maintenance);
  if (state.kind === "none") return <Muted>—</Muted>;
  const when = (m: any) => m.format("MMM D, h:mm A");
  const pill =
    state.kind === "upcoming" ? (
      <Pill tone="amber">Shop {when(state.dropoff)}</Pill>
    ) : state.kind === "inShop" ? (
      <Pill tone="red">In shop{state.pickup ? ` until ${when(state.pickup)}` : ""}</Pill>
    ) : (
      <Pill tone="gray" plain>
        Serviced {state.dropoff.format("MMM D")}
      </Pill>
    );
  return (
    <Tooltip title={formatMaintenanceMessage(row.maintenance, row.name)}>
      <span>{pill}</span>
    </Tooltip>
  );
};

const VehicleModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, componentUuid }) => {
  const { projects, adminUserRoles } = useSelector((state: RootState) => state.auth);
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const queryVehicles = useVehicleQuery();
  const uuid = useRef(componentUuid || generateUUID()).current;
  const links = useVehicleLinks(socket, uuid);

  const [assets, setAssets] = useState<VehicleAsset[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<VehicleAsset | undefined>(undefined);

  const mounted = useRef(true);
  const requestSeq = useRef(0);
  // Status changes awaiting their UpdateUserBio reply (a shared topic).
  const pendingStatus = useRef<any[]>([]);

  const load = useCallback(async () => {
    const seq = ++requestSeq.current;
    setLoading(true);
    const result = await queryVehicles();
    if (!mounted.current || seq !== requestSeq.current) return;
    setLoading(false);
    setLoadFailed(!result);
    if (result) setAssets(result);
  }, [queryVehicles]);

  useEffect(() => {
    document.title = "Vehicle | Beam";
    mounted.current = true;
    return () => {
      mounted.current = false;
      pendingStatus.current.forEach(clearTimeout);
    };
  }, []);

  useEffect(() => {
    if (!projects?.adminUserId) return;
    load();
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        const timer = pendingStatus.current.shift();
        if (timer === undefined) return;
        clearTimeout(timer);
        pushNotification("Status updated", "success", "TOP_CENTER", 1500);
      },
      uuid
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.adminUserId]);

  const changeStatus = (row: VehicleRow, value: string) => {
    const option = STATUS_OPTIONS.find((o) => o.value === value);
    if (!option || row.status === value) return;
    setAssets((prev) => prev.map((a) => (`${a.id}` === row.key ? { ...a, status: value } : a)));
    const timer = setTimeout(() => {
      pendingStatus.current = pendingStatus.current.filter((t) => t !== timer);
      if (!mounted.current) return;
      pushNotification(
        `No response while updating ${row.name || "the vehicle"}. Reloading the list.`,
        "error",
        "TOP_CENTER",
        3000
      );
      load();
    }, REQUEST_TIMEOUT_MS);
    pendingStatus.current.push(timer);
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(row.key, [
        {
          op: "replace",
          path: `/nonpersistent/static/live/status`,
          value: { name: option.value, color: option.hex },
        },
      ]),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
  };

  const rows = useMemo(
    () =>
      assets
        .map((a) => toVehicleRow(a, links))
        .sort((a, b) => a.name.localeCompare(b.name)),
    [assets, links]
  );

  const filtered = useMemo(
    () =>
      rows.filter((r) =>
        matchesSearch(
          search,
          r.name,
          r.licensePlate,
          r.makeAndModel,
          r.vin,
          r.permit,
          r.typeName,
          r.driverName
        )
      ),
    [rows, search]
  );

  // Handlers change every render; columns read them through a ref so the
  // column definitions stay static.
  const handlers = useRef<any>({});
  handlers.current = { changeStatus, setEditing };

  const columns: ColumnsType<VehicleRow> = useMemo(
    () => [
      {
        title: "Vehicle",
        key: "name",
        dataIndex: "name",
        sorter: (a, b) => a.name.localeCompare(b.name),
        render: (_, r) => (
          <div>
            <strong>{r.name || "Unnamed vehicle"}</strong>
            <div className="mx-vehicle__sub">
              {[r.makeAndModel, r.year].filter(Boolean).join(" · ") || "No make & model"}
            </div>
          </div>
        ),
      },
      {
        title: "Registration",
        key: "licensePlate",
        render: (_, r) => (
          <div>
            <div>{r.licensePlate || <Muted>No plate</Muted>}</div>
            {(r.vin || r.permit) && (
              <div className="mx-vehicle__sub">
                {[r.vin && `VIN ${r.vin}`, r.permit && `Permit ${r.permit}`].filter(Boolean).join(" · ")}
              </div>
            )}
          </div>
        ),
      },
      {
        title: "Type",
        key: "typeName",
        sorter: (a, b) => `${a.typeName || ""}`.localeCompare(`${b.typeName || ""}`),
        render: (_, r) => (r.typeName ? <Pill tone="blue" plain>{r.typeName}</Pill> : <Muted>—</Muted>),
      },
      {
        title: "Assigned driver",
        key: "driverName",
        sorter: (a, b) => `${a.driverName || ""}`.localeCompare(`${b.driverName || ""}`),
        render: (_, r) => r.driverName || <Muted>Unassigned</Muted>,
      },
      {
        title: "Status",
        key: "status",
        sorter: (a, b) => statusDisplay(a.status).label.localeCompare(statusDisplay(b.status).label),
        render: (_, r) => {
          const { label, tone } = statusDisplay(r.status);
          return (
            <span onClick={(e) => e.stopPropagation()}>
              <Dropdown
                trigger={["click"]}
                overlay={
                  <Menu
                    selectedKeys={r.status ? [r.status] : []}
                    onClick={({ key }) => handlers.current.changeStatus(r, key)}
                    items={STATUS_OPTIONS.map((o) => ({ key: o.value, label: o.label }))}
                  />
                }
              >
                <button type="button" className="mx-vehicle__status" title="Change status">
                  <Pill tone={tone}>{label}</Pill>
                  <DownOutlined />
                </button>
              </Dropdown>
            </span>
          );
        },
      },
      {
        title: "Maintenance",
        key: "maintenance",
        render: (_, r) => <MaintenanceCell row={r} />,
      },
      {
        title: "",
        key: "actions",
        align: "right",
        width: 60,
        render: (_, r) => <RowActions onEdit={() => handlers.current.setEditing(r.asset)} />,
      },
    ],
    []
  );

  const available = rows.filter((r) => r.status === "green").length;
  const caption = search.trim()
    ? `${filtered.length} of ${rows.length} vehicles`
    : `${rows.length} ${rows.length === 1 ? "vehicle" : "vehicles"}${
        rows.length ? ` · ${available} available` : ""
      }`;

  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load vehicles"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={load}>
          Try again
        </Button>
      }
    />
  ) : search.trim() ? (
    <EmptyState
      title="No matching vehicles"
      description="Try a name, plate, VIN, permit, type or driver."
    />
  ) : (
    <EmptyState
      title="No vehicles yet"
      description="Vehicles added to your organization will show up here."
    />
  );

  return (
    <div className="mx-vehicle">
      <PageHeader
        title="Vehicles"
        subtitle="Fleet details, availability and upcoming maintenance"
        search={{
          value: search,
          onChange: setSearch,
          placeholder: "Search name, plate, VIN or driver",
        }}
      />

      <DataTableCard<VehicleRow>
        rowKey="key"
        loading={loading}
        clickable
        caption={caption}
        columns={columns}
        dataSource={filtered}
        empty={emptyState}
        scroll={{ x: true }}
        onRow={(r) => ({ onClick: () => setEditing(r.asset) })}
      />

      {editing && (
        <EditVehicleModal
          socket={socket}
          student={editing}
          adminRoles={adminUserRoles}
          onClose={() => setEditing(undefined)}
          onAdd={() => {
            setEditing(undefined);
            load();
          }}
        />
      )}
    </div>
  );
};

export default VehicleModal;
