import React, { FC, useMemo, useState } from "react";
import { Badge, Button, Checkbox, Col, DatePicker, Input, InputNumber, Radio, Row, Select, Tag } from "antd";
import { ClearOutlined, FilterOutlined, SearchOutlined } from "@ant-design/icons";
import moment, { Moment } from "moment";

import {
  AgingBucket,
  Cadence,
  CollectionForm,
  Domain,
  FlagKind,
  LedgerRow,
  PaymentMethod,
  RowStatus,
  ScheduleStatus,
  TransactionFilter,
} from "./types";
import { DOMAIN_LABELS, PROJECTS } from "./mockData";
import {
  AGING_LABELS,
  AGING_ORDER,
  EMPTY_FILTER,
  FLAG_LABELS,
  ROW_STATUS_LABELS,
  countActiveFilters,
  formatMoney,
} from "./selectors";

const { RangePicker } = DatePicker;

export type FilterMode = "ledger" | "schedule";

const SCHEDULE_STATUS_LABELS: Record<ScheduleStatus, string> = {
  upcoming: "Upcoming",
  due: "Due",
  overdue: "Overdue",
  suspended: "Suspended",
};

const FORM_LABELS: Record<CollectionForm, string> = { card: "Credit card", invoice: "Invoice (CPC)" };
const METHOD_LABELS: Record<PaymentMethod, string> = {
  upfront: "Upfront",
  installment: "Installment",
  scheduled: "Scheduled",
};
const CADENCE_LABELS: Record<Cadence, string> = {
  "one-time": "One-time",
  recurring: "Recurring",
  seasonal: "Seasonal",
  regular: "Regular",
};
const ONLY_LABELS: Record<TransactionFilter["only"][number], string> = {
  adjustments: "With adjustments",
  refund: "With a refund",
  flags: "Flagged",
};

const optionsOf = <K extends string>(labels: Record<K, string>) =>
  (Object.keys(labels) as K[]).map((value) => ({ value, label: labels[value] }));

interface Props {
  domain: Domain;
  mode: FilterMode;
  filter: TransactionFilter;
  onChange: (filter: TransactionFilter) => void;
  /** Every line of the domain, to offer the customer types that exist. */
  rows: LedgerRow[];
  /** What the filter currently yields, for the count line. */
  resultCount: number;
}

/**
 * The Transactions filter: search and dates always visible, everything
 * else behind a Filters button that badges how many are set. Set
 * filters are echoed as closable chips so the reader can see and undo
 * each one without opening the panel.
 */
const TransactionFilters: FC<Props> = ({ domain, mode, filter, onChange, rows, resultCount }) => {
  const [open, setOpen] = useState(false);
  const labels = DOMAIN_LABELS[domain];

  const set = <K extends keyof TransactionFilter>(key: K, value: TransactionFilter[K]) =>
    onChange({ ...filter, [key]: value });

  const projectOptions = useMemo(
    () => PROJECTS.filter((p) => p.domain === domain).map((p) => ({ value: p.id, label: p.name })),
    [domain]
  );
  const roleOptions = useMemo(
    () =>
      Array.from(new Set(rows.map((row) => row.entityRole)))
        .sort()
        .map((role) => ({ value: role, label: role })),
    [rows]
  );

  const active = countActiveFilters(filter);
  const projectName = (id: string) => (PROJECTS.find((p) => p.id === id) || { name: id }).name;

  /** One chip per set filter, with the change that clears it. */
  const chips: { key: string; label: string; clear: () => void }[] = [];
  if (filter.side) chips.push({ key: "side", label: filter.side.toUpperCase(), clear: () => set("side", null) });
  filter.projectIds.forEach((id) =>
    chips.push({ key: `p-${id}`, label: projectName(id), clear: () => set("projectIds", filter.projectIds.filter((x) => x !== id)) })
  );
  filter.entityRoles.forEach((role) =>
    chips.push({ key: `r-${role}`, label: role, clear: () => set("entityRoles", filter.entityRoles.filter((x) => x !== role)) })
  );
  if (mode === "ledger") {
    filter.rowStatuses.forEach((status) =>
      chips.push({
        key: `s-${status}`,
        label: ROW_STATUS_LABELS[status],
        clear: () => set("rowStatuses", filter.rowStatuses.filter((x) => x !== status)),
      })
    );
  } else {
    filter.scheduleStatuses.forEach((status) =>
      chips.push({
        key: `ss-${status}`,
        label: SCHEDULE_STATUS_LABELS[status],
        clear: () => set("scheduleStatuses", filter.scheduleStatuses.filter((x) => x !== status)),
      })
    );
  }
  if (filter.aging) chips.push({ key: "aging", label: `Aging: ${AGING_LABELS[filter.aging]}`, clear: () => set("aging", null) });
  filter.forms.forEach((form) =>
    chips.push({ key: `f-${form}`, label: FORM_LABELS[form], clear: () => set("forms", filter.forms.filter((x) => x !== form)) })
  );
  filter.methods.forEach((method) =>
    chips.push({ key: `m-${method}`, label: METHOD_LABELS[method], clear: () => set("methods", filter.methods.filter((x) => x !== method)) })
  );
  filter.cadences.forEach((cadence) =>
    chips.push({ key: `c-${cadence}`, label: CADENCE_LABELS[cadence], clear: () => set("cadences", filter.cadences.filter((x) => x !== cadence)) })
  );
  if (filter.amountMin !== null || filter.amountMax !== null) {
    const lo = filter.amountMin !== null ? formatMoney(filter.amountMin) : "…";
    const hi = filter.amountMax !== null ? formatMoney(filter.amountMax) : "…";
    chips.push({ key: "amount", label: `Amount ${lo} - ${hi}`, clear: () => onChange({ ...filter, amountMin: null, amountMax: null }) });
  }
  filter.flags.forEach((flag) =>
    chips.push({ key: `fl-${flag}`, label: FLAG_LABELS[flag], clear: () => set("flags", filter.flags.filter((x) => x !== flag)) })
  );
  filter.only.forEach((marker) =>
    chips.push({ key: `o-${marker}`, label: ONLY_LABELS[marker], clear: () => set("only", filter.only.filter((x) => x !== marker)) })
  );

  const toWindow = (values: [Moment | null, Moment | null] | null) =>
    values && values[0] && values[1]
      ? { from: values[0].startOf("day").valueOf(), to: values[1].endOf("day").valueOf() }
      : null;

  const isEmpty = active === 0 && !filter.search && !filter.range;

  return (
    <div className="cfo-filter">
      <div className="cfo-filter__bar">
        <Input
          allowClear
          value={filter.search}
          onChange={(e) => set("search", e.target.value)}
          className="cfo-filter__search"
          placeholder="Search entity, project or invoice"
          prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
        />
        <RangePicker
          allowClear
          value={filter.range ? [moment(filter.range.from), moment(filter.range.to)] : null}
          format="D MMM YYYY"
          placeholder={mode === "ledger" ? ["Activity from", "to"] : ["Due from", "to"]}
          onChange={(values) => set("range", toWindow(values as any))}
        />
        <Badge count={active} size="small" offset={[-4, 4]}>
          <Button
            className={`cfo-filter__toggle${open ? " is-open" : ""}`}
            icon={<FilterOutlined />}
            onClick={() => setOpen(!open)}
          >
            Filters
          </Button>
        </Badge>
        <Button type="text" icon={<ClearOutlined />} disabled={isEmpty} onClick={() => onChange(EMPTY_FILTER)}>
          Reset
        </Button>
      </div>

      {open && (
        <div className="cfo-filter__panel">
          <Row gutter={[16, 12]}>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Side</label>
              <Radio.Group
                size="small"
                optionType="button"
                value={filter.side || "all"}
                onChange={(e) => set("side", e.target.value === "all" ? null : e.target.value)}
                options={[
                  { value: "all", label: "All" },
                  { value: "ar", label: "Receivable" },
                  { value: "ap", label: "Payable" },
                ]}
              />
            </Col>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Status</label>
              {mode === "ledger" ? (
                <Select
                  mode="multiple"
                  allowClear
                  placeholder="Any status"
                  value={filter.rowStatuses}
                  options={optionsOf<RowStatus>(ROW_STATUS_LABELS)}
                  onChange={(value) => set("rowStatuses", value)}
                  style={{ width: "100%" }}
                />
              ) : (
                <Select
                  mode="multiple"
                  allowClear
                  placeholder="Any status"
                  value={filter.scheduleStatuses}
                  options={optionsOf<ScheduleStatus>(SCHEDULE_STATUS_LABELS)}
                  onChange={(value) => set("scheduleStatuses", value)}
                  style={{ width: "100%" }}
                />
              )}
            </Col>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Aging</label>
              <Select
                allowClear
                placeholder="Any age"
                value={filter.aging || undefined}
                options={AGING_ORDER.map((bucket: AgingBucket) => ({ value: bucket, label: AGING_LABELS[bucket] }))}
                onChange={(value) => set("aging", value || null)}
                style={{ width: "100%" }}
              />
            </Col>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Amount</label>
              <div className="cfo-filter__range">
                <InputNumber
                  placeholder="Min"
                  min={0}
                  value={filter.amountMin === null ? undefined : filter.amountMin}
                  onChange={(value) => set("amountMin", value === null || value === undefined ? null : Number(value))}
                />
                <span className="cfo-muted">to</span>
                <InputNumber
                  placeholder="Max"
                  min={0}
                  value={filter.amountMax === null ? undefined : filter.amountMax}
                  onChange={(value) => set("amountMax", value === null || value === undefined ? null : Number(value))}
                />
              </div>
            </Col>

            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">{labels.navSingular.team} / event</label>
              <Select
                mode="multiple"
                allowClear
                showSearch
                placeholder="Any project"
                value={filter.projectIds}
                options={projectOptions}
                onChange={(value) => set("projectIds", value)}
                filterOption={(input, option) =>
                  (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase())
                }
                style={{ width: "100%" }}
              />
            </Col>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Customer type</label>
              <Select
                mode="multiple"
                allowClear
                placeholder="Any type"
                value={filter.entityRoles}
                options={roleOptions}
                onChange={(value) => set("entityRoles", value)}
                style={{ width: "100%" }}
              />
            </Col>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Collection form</label>
              <Select
                mode="multiple"
                allowClear
                placeholder="Card or invoice"
                value={filter.forms}
                options={optionsOf<CollectionForm>(FORM_LABELS)}
                onChange={(value) => set("forms", value)}
                style={{ width: "100%" }}
              />
            </Col>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Payment method</label>
              <Select
                mode="multiple"
                allowClear
                placeholder="Any method"
                value={filter.methods}
                options={optionsOf<PaymentMethod>(METHOD_LABELS)}
                onChange={(value) => set("methods", value)}
                style={{ width: "100%" }}
              />
            </Col>

            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Cadence</label>
              <Select
                mode="multiple"
                allowClear
                placeholder="Any cadence"
                value={filter.cadences}
                options={optionsOf<Cadence>(CADENCE_LABELS)}
                onChange={(value) => set("cadences", value)}
                style={{ width: "100%" }}
              />
            </Col>
            <Col xs={24} md={12} lg={6}>
              <label className="cfo-filter__label">Flags</label>
              <Select
                mode="multiple"
                allowClear
                placeholder="Any flag"
                value={filter.flags}
                options={optionsOf<FlagKind>(FLAG_LABELS as Record<FlagKind, string>)}
                onChange={(value) => set("flags", value)}
                style={{ width: "100%" }}
              />
            </Col>
            <Col xs={24} lg={12}>
              <label className="cfo-filter__label">Only lines</label>
              <Checkbox.Group
                className="cfo-filter__checks"
                value={filter.only}
                options={optionsOf(ONLY_LABELS)}
                onChange={(value) => set("only", value as TransactionFilter["only"])}
              />
            </Col>
          </Row>
        </div>
      )}

      <p className="cfo-page-toolbar__note cfo-page-toolbar__note--line cfo-filter__chips">
        <span>
          {resultCount} {mode === "ledger" ? (resultCount === 1 ? "line" : "lines") : resultCount === 1 ? "payment" : "payments"}
          {filter.range &&
            ` · ${moment(filter.range.from).format("D MMM YYYY")} - ${moment(filter.range.to).format("D MMM YYYY")}`}
        </span>
        {chips.map((chip) => (
          <Tag
            key={chip.key}
            closable
            color="geekblue"
            onClose={(e) => {
              e.preventDefault();
              chip.clear();
            }}
          >
            {chip.label}
          </Tag>
        ))}
      </p>
    </div>
  );
};

export default TransactionFilters;
