import React from "react";
import { Row, Col } from "antd";
import { useDispatchPanel } from "../context";

const EstimationSummary: React.FC = () => {
  const { estimation } = useDispatchPanel();

  if (!estimation) return null;

  return (
    <Row className="beam-modal summary-modal analytics-summary-modal d-flex mt-3">
      <Col span={24}>
        <h4>Estimation</h4>
      </Col>

      <Col span={24}>
        <ul className="incident-information mt-2">
          {estimation.map((item: any, i: number) => (
            <li key={i}>
              <Row>
                <Col span={12}>
                  <p>{item.label}</p>
                </Col>
                <Col span={12}>
                  <p>{item.value}</p>
                </Col>
              </Row>
            </li>
          ))}
        </ul>
      </Col>
    </Row>
  );
};

export default EstimationSummary;
