import React, { FC, useMemo, useState } from "react";
import { Empty, Radio, Select, Tooltip } from "antd";
import {
  Assignment,
  Day,
  OrgSettings,
  SchedResource,
} from "services/apis/aiSchedulerTypes";
import { activityColor, toHHMM, toMin, visibleDays } from "../utils";

const PX_PER_MIN = 1.1;
const LANE_LABEL_W = 140;

// Read-only pivot of the schedule: rows are resources of one kind, the x-axis
// is one day's time span. Good for spotting room/teacher utilization.
const ResourceLaneView: FC<{
  settings: OrgSettings;
  assignments: Assignment[];
  resources: SchedResource[];
}> = ({ settings, assignments, resources }) => {
  const kinds = useMemo(
    () => Array.from(new Set(resources.map((r) => r.kind).filter(Boolean))),
    [resources]
  );
  const [kind, setKind] = useState<string | undefined>(kinds[0]);
  const days = visibleDays(settings, assignments);
  const [day, setDay] = useState<Day>(days[0]);

  const dayStartMin = toMin(settings.dayStart);
  const dayEndMin = toMin(settings.dayEnd);
  const spanMin = Math.max(dayEndMin - dayStartMin, settings.slotMinutes);
  const laneWidth = spanMin * PX_PER_MIN;

  const activeKind = kind && kinds.includes(kind) ? kind : kinds[0];
  const rows = useMemo(
    () => resources.filter((r) => r.kind === activeKind && r.id),
    [resources, activeKind]
  );

  const dayAssignments = useMemo(
    () => assignments.filter((a) => a.day === day),
    [assignments, day]
  );

  const hourMarks = useMemo(() => {
    const marks: number[] = [];
    const firstHour = Math.ceil(dayStartMin / 60) * 60;
    for (let m = firstHour; m <= dayEndMin; m += 60) marks.push(m);
    return marks;
  }, [dayStartMin, dayEndMin]);

  if (!kinds.length) {
    return <Empty description="Add resources to see the lane view" />;
  }

  return (
    <div className="resource-lane-view">
      <div className="lane-controls">
        <Select
          value={activeKind}
          onChange={setKind}
          style={{ width: 160 }}
          options={kinds.map((k) => ({ label: k, value: k }))}
        />
        <Radio.Group
          value={days.includes(day) ? day : days[0]}
          onChange={(e) => setDay(e.target.value)}
        >
          {days.map((d) => (
            <Radio.Button key={d} value={d}>
              {d}
            </Radio.Button>
          ))}
        </Radio.Group>
      </div>

      <div className="lane-scroll">
        <div style={{ width: LANE_LABEL_W + laneWidth, position: "relative" }}>
          <div className="lane-time-axis" style={{ marginLeft: LANE_LABEL_W }}>
            {hourMarks.map((m) => (
              <span
                key={m}
                className="lane-hour-label"
                style={{ left: (m - dayStartMin) * PX_PER_MIN }}
              >
                {toHHMM(m)}
              </span>
            ))}
          </div>
          {rows.map((r) => {
            const laneAssignments = dayAssignments.filter((a) =>
              Object.values(a.resources || {}).some((ids) => ids?.includes(r.id as string))
            );
            return (
              <div key={r.id} className="lane-row">
                <div className="lane-label" style={{ width: LANE_LABEL_W }}>
                  <span className={r.active === false ? "inactive" : undefined}>
                    {r.name}
                  </span>
                </div>
                <div
                  className="lane-track"
                  style={{
                    width: laneWidth,
                    backgroundSize: `${settings.slotMinutes * PX_PER_MIN}px 100%`,
                  }}
                >
                  {laneAssignments.map((a) => {
                    const left = (toMin(a.start) - dayStartMin) * PX_PER_MIN;
                    const width = Math.max(
                      (toMin(a.end) - toMin(a.start)) * PX_PER_MIN,
                      12
                    );
                    return (
                      <Tooltip
                        key={`${a.activityId}#${a.occurrence}`}
                        title={`${a.activityName || a.activityId} · ${a.start}–${a.end}`}
                      >
                        <div
                          className="lane-block"
                          style={{
                            left,
                            width,
                            background: activityColor(a.activityId),
                          }}
                        >
                          {a.activityName || a.activityId}
                        </div>
                      </Tooltip>
                    );
                  })}
                </div>
              </div>
            );
          })}
          {!rows.length && <Empty description={`No ${activeKind} resources`} />}
        </div>
      </div>
    </div>
  );
};

export default ResourceLaneView;
